{"command":"mkdir -p /workspace/src && cat > /workspace/src/lexer.rs <<'EOF'
//! Tokenizer for fselect queries.
//!
//! The lexer works over the list of command line arguments.  Each argument is
//! treated as a chunk; in "single argument" mode (one argument containing the
//! whole query) spaces inside the argument also terminate search roots.

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    /// a plain word or quoted string
    Str(String),
    /// a search root path
    Path(String),
    Comma,
    Open,
    Close,
    // comparison operators
    Eq,
    Ne,
    Eeq,
    Ene,
    Gt,
    Gte,
    Lt,
    Lte,
    Rx,
    NotRx,
    Like,
    NotLike,
    Between,
    In,
    // arithmetic
    Plus,
    Minus,
    Mul,
    Div,
    Mod,
    // keywords
    Select,
    From,
    Where,
    Group,
    Order,
    By,
    Limit,
    Offset,
    Into,
    And,
    Or,
    Not,
    As,
    Asc,
    Desc,
    Exists,
}

impl Token {
    pub fn is_clause_keyword(&self) -> bool {
        matches!(
            self,
            Token::From | Token::Where | Token::Group | Token::Order | Token::Limit | Token::Offset | Token::Into
        )
    }

    /// textual form of a keyword/operator token when it is used as a plain string
    pub fn as_word(&self) -> Option<String> {
        let s = match self {
            Token::Str(s) | Token::Path(s) => return Some(s.clone()),
            Token::Comma => ",",
            Token::Open => "(",
            Token::Close => ")",
            Token::Eq => "=",
            Token::Ne => "!=",
            Token::Eeq => "===",
            Token::Ene => "!==",
            Token::Gt => ">",
            Token::Gte => ">=",
            Token::Lt => "<",
            Token::Lte => "<=",
            Token::Rx => "=~",
            Token::NotRx => "!=~",
            Token::Like => "like",
            Token::NotLike => "notlike",
            Token::Between => "between",
            Token::In => "in",
            Token::Plus => "+",
            Token::Minus => "-",
            Token::Mul => "*",
            Token::Div => "/",
            Token::Mod => "%",
            Token::Select => "select",
            Token::From => "from",
            Token::Where => "where",
            Token::Group => "group",
            Token::Order => "order",
            Token::By => "by",
            Token::Limit => "limit",
            Token::Offset => "offset",
            Token::Into => "into",
            Token::And => "and",
            Token::Or => "or",
            Token::Not => "not",
            Token::As => "as",
            Token::Asc => "asc",
            Token::Desc => "desc",
            Token::Exists => "exists",
        };
        Some(s.to_string())
    }
}

pub struct Lexer {
    args: Vec<Vec<char>>,
    ai: usize,
    ci: usize,
    single: bool,
    after_from: bool,
    in_where: bool,
    last: Option<Token>,
    paren_depth_in_where: i32,
}

fn is_quote(c: char) -> bool {
    c == '\'' || c == '"' || c == '`'
}

fn is_special(c: char) -> bool {
    matches!(
        c,
        ' ' | ',' | '(' | ')' | '{' | '}' | '=' | '!' | '<' | '>' | '~' | '*' | '/' | '%' | '+' | '-'
    )
}

impl Lexer {
    pub fn new(args: &[String]) -> Lexer {
        Lexer {
            args: args.iter().map(|a| a.chars().collect()).collect(),
            ai: 0,
            ci: 0,
            single: args.len() == 1,
            after_from: false,
            in_where: false,
            last: None,
            paren_depth_in_where: 0,
        }
    }

    pub fn tokenize(args: &[String]) -> Result<Vec<Token>, String> {
        let mut lexer = Lexer::new(args);
        let mut tokens = vec![];
        while let Some(t) = lexer.next_token()? {
            tokens.push(t);
        }
        Ok(tokens)
    }

    fn cur_len(&self) -> usize {
        self.args.get(self.ai).map(|a| a.len()).unwrap_or(0)
    }

    fn peek(&self) -> Option<char> {
        self.args.get(self.ai).and_then(|a| a.get(self.ci)).copied()
    }

    fn peek_at(&self, offset: usize) -> Option<char> {
        self.args.get(self.ai).and_then(|a| a.get(self.ci + offset)).copied()
    }

    fn at_end_of_arg(&self) -> bool {
        self.ci >= self.cur_len()
    }

    fn at_end(&self) -> bool {
        self.ai >= self.args.len()
    }

    /// Move to the next argument after a token ended exactly at the end of an argument.
    fn next_arg_clean(&mut self) {
        if !self.at_end() && self.at_end_of_arg() {
            self.ai += 1;
            self.ci = 0;
        }
    }

    fn emit(&mut self, t: Token) -> Result<Option<Token>, String> {
        match &t {
            Token::From => {
                if !self.in_where {
                    self.after_from = true;
                }
            }
            Token::Where => {
                self.after_from = false;
                self.in_where = true;
            }
            Token::Group | Token::Order | Token::Limit | Token::Offset | Token::Into => {
                self.after_from = false;
            }
            _ => {}
        }
        self.last = Some(t.clone());
        Ok(Some(t))
    }

    pub fn next_token(&mut self) -> Result<Option<Token>, String> {
        // skip whitespace and argument boundaries
        loop {
            if self.at_end() {
                return Ok(None);
            }
            if self.at_end_of_arg() {
                // bug-compatible: assume a separator at the start of the next argument
                self.ai += 1;
                self.ci = 1;
                continue;
            }
            let c = self.peek().unwrap();
            if c == ' ' {
                self.ci += 1;
                continue;
            }
            break;
        }

        // path mode: after FROM or after a comma within the FROM clause
        if self.after_from && matches!(self.last, Some(Token::From) | Some(Token::Comma)) {
            let path = self.read_path()?;
            return self.emit(Token::Path(path));
        }

        let c = self.peek().unwrap();

        if is_quote(c) {
            let s = self.read_quoted(c)?;
            return self.emit(Token::Str(s));
        }

        match c {
            ',' => {
                self.ci += 1;
                self.next_arg_clean();
                return self.emit(Token::Comma);
            }
            '(' | '{' => {
                self.ci += 1;
                self.next_arg_clean();
                if self.in_where {
                    self.paren_depth_in_where += 1;
                }
                return self.emit(Token::Open);
            }
            ')' | '}' => {
                self.ci += 1;
                self.next_arg_clean();
                if self.in_where {
                    self.paren_depth_in_where -= 1;
                }
                return self.emit(Token::Close);
            }
            '*' => {
                self.ci += 1;
                self.next_arg_clean();
                return self.emit(Token::Mul);
            }
            '/' => {
                self.ci += 1;
                self.next_arg_clean();
                return self.emit(Token::Div);
            }
            '%' => {
                self.ci += 1;
                self.next_arg_clean();
                return self.emit(Token::Mod);
            }
            '+' => {
                self.ci += 1;
                self.next_arg_clean();
                return self.emit(Token::Plus);
            }
            '-' => {
                self.ci += 1;
                self.next_arg_clean();
                return self.emit(Token::Minus);
            }
            '=' | '!' | '<' | '>' | '~' => {
                let op = self.read_operator();
                self.next_arg_clean();
                let t = match op.as_str() {
                    "=" | "==" => Token::Eq,
                    "!=" | "<>" => Token::Ne,
                    "===" => Token::Eeq,
                    "!==" => Token::Ene,
                    ">" => Token::Gt,
                    ">=" => Token::Gte,
                    "<" => Token::Lt,
                    "<=" => Token::Lte,
                    "=~" | "~=" => Token::Rx,
                    "!=~" | "!~=" => Token::NotRx,
                    _ => return Err(format!("Unknown operator: {}", op)),
                };
                return self.emit(t);
            }
            _ => {}
        }

        let word = self.read_word();
        let after_comma = matches!(self.last, Some(Token::Comma));
        let lower = word.to_lowercase();
        let keyword = match lower.as_str() {
            "select" => Some(Token::Select),
            "from" => Some(Token::From),
            "where" => Some(Token::Where),
            "group" => Some(Token::Group),
            "order" => Some(Token::Order),
            "by" => Some(Token::By),
            "limit" => Some(Token::Limit),
            "offset" => Some(Token::Offset),
            "into" => Some(Token::Into),
            "and" => Some(Token::And),
            "or" => Some(Token::Or),
            "not" => Some(Token::Not),
            "as" => Some(Token::As),
            "asc" => Some(Token::Asc),
            "desc" => Some(Token::Desc),
            "exists" => Some(Token::Exists),
            "eq" => Some(Token::Eq),
            "ne" => Some(Token::Ne),
            "eeq" => Some(Token::Eeq),
            "ene" => Some(Token::Ene),
            "gt" => Some(Token::Gt),
            "gte" | "ge" => Some(Token::Gte),
            "lt" => Some(Token::Lt),
            "lte" | "le" => Some(Token::Lte),
            "regexp" | "rx" => Some(Token::Rx),
            "notrx" => Some(Token::NotRx),
            "like" => Some(Token::Like),
            "notlike" => Some(Token::NotLike),
            "between" => Some(Token::Between),
            "in" => Some(Token::In),
            "plus" => Some(Token::Plus),
            "minus" => Some(Token::Minus),
            "mul" => Some(Token::Mul),
            "div" => Some(Token::Div),
            "mod" => Some(Token::Mod),
            _ => None,
        };
        match keyword {
            Some(Token::Select) | Some(Token::As) => self.emit(keyword.unwrap()),
            Some(Token::Rx) if lower == "regexp" && self.after_from => self.emit(Token::Str(word)),
            Some(t) if !after_comma => self.emit(t),
            _ => self.emit(Token::Str(word)),
        }
    }

    fn read_operator(&mut self) -> String {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if matches!(c, '=' | '!' | '<' | '>' | '~') {
                s.push(c);
                self.ci += 1;
            } else {
                break;
            }
        }
        s
    }

    fn read_quoted(&mut self, q: char) -> Result<String, String> {
        let mut s = String::new();
        self.ci += 1;
        loop {
            if self.at_end() {
                return Err(format!("Unterminated quoted string: {}", s));
            }
            if self.at_end_of_arg() {
                self.ai += 1;
                self.ci = 0;
                continue;
            }
            let c = self.peek().unwrap();
            self.ci += 1;
            if c == q {
                break;
            }
            s.push(c);
        }
        Ok(s)
    }

    fn read_word(&mut self) -> String {
        let mut s = String::new();
        loop {
            if self.at_end_of_arg() {
                self.next_arg_clean();
                break;
            }
            let c = self.peek().unwrap();
            if c == '-' {
                if self.dash_continues_word(&s) {
                    s.push(c);
                    self.ci += 1;
                    continue;
                }
                break;
            }
            if is_special(c) {
                break;
            }
            s.push(c);
            self.ci += 1;
        }
        s
    }

    /// Decide whether a '-' inside a word is part of the word (e.g. dates like 2024-03-15)
    /// or an arithmetic operator.
    fn dash_continues_word(&self, word: &str) -> bool {
        if word.is_empty() {
            return false;
        }
        let next = self.peek_at(1);
        let next_is_digit = next.map(|c| c.is_ascii_digit()).unwrap_or(false);
        // a word with non-digit characters keeps the dash unless it is a known field name
        if word.chars().any(|c| !c.is_ascii_digit() && c != '-') {
            if crate::field::Field::from_str(word).is_some() {
                return false;
            }
            if word.chars().all(|c| c.is_ascii_digit() || c == '-') {
                return next_is_digit;
            }
            return true;
        }
        if !next_is_digit {
            return false;
        }
        let parts: Vec<&str> = word.split('-').collect();
        match parts.len() {
            1 => {
                let p = parts[0];
                if p.len() < 4 || p.len() > 5 {
                    return false;
                }
                match p[..4].parse::<u32>() {
                    Ok(y) => (1970..=2999).contains(&y),
                    Err(_) => false,
                }
            }
            2 => {
                let p = parts[1];
                if p.len() <= 1 {
                    return true;
                }
                match p[..2].parse::<u32>() {
                    Ok(m) => (1..=12).contains(&m),
                    Err(_) => false,
                }
            }
            _ => true,
        }
    }

    fn read_path(&mut self) -> Result<String, String> {
        let c = self.peek().unwrap();
        if is_quote(c) {
            let s = self.read_quoted(c)?;
            return Ok(s);
        }
        let mut s = String::new();
        loop {
            if self.at_end_of_arg() {
                self.next_arg_clean();
                break;
            }
            let c = self.peek().unwrap();
            if c == ',' {
                break;
            }
            if self.single && c == ' ' {
                break;
            }
            s.push(c);
            self.ci += 1;
        }
        Ok(s)
    }
}
EOF
echo done"}

