//! File attributes that can be selected or used in conditions.

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum FieldKind {
    Str,
    Num,
    Bool,
    DateTime,
}

macro_rules! fields {
    ( $( $variant:ident : [ $( $name:expr ),* ] , $display:expr , $kind:ident ; )* ) => {
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
        pub enum Field {
            $( $variant, )*
        }

        impl Field {
            pub fn from_str(s: &str) -> Option<Field> {
                let lower = s.to_lowercase();
                match lower.as_str() {
                    $( $( $name )|* => Some(Field::$variant), )*
                    _ => None,
                }
            }

            pub fn display_name(&self) -> &'static str {
                match self {
                    $( Field::$variant => $display, )*
                }
            }

            pub fn kind(&self) -> FieldKind {
                match self {
                    $( Field::$variant => FieldKind::$kind, )*
                }
            }
        }
    };
}

