    Literal(String),
    Function(Function, Vec<Expr>),
    Arith(Box<Expr>, ArithOp, Box<Expr>),
    Compare(Box<Expr>, CmpOp, Box<Expr>),
    Between(Box<Expr>, Box<Expr>, Box<Expr>, bool),
    InList(Box<Expr>, Vec<Expr>, bool),
    InSubquery(Box<Expr>, Box<Query>, bool),
    Exists(Box<Query>, bool),
    And(Box<Expr>, Box<Expr>),
    Or(Box<Expr>, Box<Expr>),
    Not(Box<Expr>),
}

impl Expr {
    /// textual representation used for json keys and value caching
    pub fn to_key(&self) -> String {
        match self {
            Expr::Field(f, alias) => match alias {
                Some(a) => format!("{}.{}", a, f.display_name()),
                None => f.display_name().to_string(),
            },
            Expr::Literal(s) => s.clone(),
            Expr::Function(func, args) => {
                let a: Vec<String> = args.iter().map(|x| x.to_key()).collect();
                format!("{}({})", func.display_name(), a.join(", "))
            }
            Expr::Arith(l, op, r) => format!("{} {} {}", l.to_key(), op.name(), r.to_key()),
            Expr::Compare(l, _, _) => l.to_key(),
            Expr::Between(l, _, _, _) => l.to_key(),
            Expr::InList(l, _, _) => l.to_key(),
            Expr::InSubquery(l, _, _) => l.to_key(),
            Expr::Exists(_, _) => "exists".to_string(),
            Expr::And(l, _) | Expr::Or(l, _) => l.to_key(),
            Expr::Not(e) => e.to_key(),
        }
    }

    pub fn kind(&self) -> FieldKind {
        match self {
            Expr::Field(f, _) => f.kind(),
            Expr::Literal(_) => FieldKind::Str,
            Expr::Function(func, _) => func.kind(),
            Expr::Arith(..) => FieldKind::Num,
            Expr::Compare(..)
            | Expr::Between(..)
            | Expr::InList(..)
            | Expr::InSubquery(..)
            | Expr::Exists(..)
            | Expr::And(..)
            | Expr::Or(..)
            | Expr::Not(..) => FieldKind::Bool,
        }
    }

    pub fn has_field(&self) -> bool {
        match self {
            Expr::Field(..) => true,
            Expr::Literal(_) => false,
            Expr::Function(_, args) => args.iter().any(|a| a.has_field()),
            Expr::Arith(l, _, r) => l.has_field() || r.has_field(),
            Expr::Compare(l, _, r) => l.has_field() || r.has_field(),
            Expr::Between(l, a, b, _) => l.has_field() || a.has_field() || b.has_field(),
            Expr::InList(l, list, _) => l.has_field() || list.iter().any(|a| a.has_field()),
            Expr::InSubquery(l, _, _) => l.has_field(),
            Expr::Exists(_, _) => false,
            Expr::And(l, r) | Expr::Or(l, r) => l.has_field() || r.has_field(),
            Expr::Not(e) => e.has_field(),
        }
    }

    pub fn has_aggregate(&self) -> bool {
        match self {
            Expr::Field(..) | Expr::Literal(_) => false,
            Expr::Function(f, args) => f.is_aggregate() || args.iter().any(|a| a.has_aggregate()),
            Expr::Arith(l, _, r) => l.has_aggregate() || r.has_aggregate(),
            Expr::Compare(l, _, r) => l.has_aggregate() || r.has_aggregate(),
            Expr::Between(l, a, b, _) => l.has_aggregate() || a.has_aggregate() || b.has_aggregate(),
            Expr::InList(l, list, _) => l.has_aggregate() || list.iter().any(|a| a.has_aggregate()),
            Expr::InSubquery(l, _, _) => l.has_aggregate(),
            Expr::Exists(_, _) => false,
            Expr::And(l, r) | Expr::Or(l, r) => l.has_aggregate() || r.has_aggregate(),
            Expr::Not(e) => e.has_aggregate(),
        }
    }

    /// collect fields used by the expression
    pub fn collect_fields(&self, out: &mut Vec<Field>) {
        match self {
            Expr::Field(f, _) => out.push(*f),
            Expr::Literal(_) => {}
            Expr::Function(_, args) => args.iter().for_each(|a| a.collect_fields(out)),
            Expr::Arith(l, _, r) | Expr::Compare(l, _, r) | Expr::And(l, r) | Expr::Or(l, r) => {
                l.collect_fields(out);
                r.collect_fields(out);
            }
            Expr::Between(l, a, b, _) => {
                l.collect_fields(out);
                a.collect_fields(out);
                b.collect_fields(out);
            }
            Expr::InList(l, list, _) => {
                l.collect_fields(out);
                list.iter().for_each(|a| a.collect_fields(out));
            }
            Expr::InSubquery(l, _, _) => l.collect_fields(out),
            Expr::Exists(_, _) => {}
            Expr::Not(e) => e.collect_fields(out),
        }
    }
}

