//! Query parser.

use crate::field::Field;
use crate::function::Function;
use crate::lexer::{Lexer, Token};
use crate::query::*;

pub struct Parser {
    tokens: Vec<Token>,
    pos: usize,
    aliases: Vec<String>,
    raw: String,
}

type PResult<T> = Result<T, String>;

const ERR_END: &str = "could not parse tokens at the end of the query";
const ERR_EXPECTING: &str = "Error parsing expression, expecting string";

impl Parser {
    pub fn parse_args(args: &[String]) -> PResult<Query> {
        let tokens = Lexer::tokenize(args)?;
        let mut parser = Parser {
            tokens,
            pos: 0,
            aliases: vec![],
            raw: args.join(" "),
        };
        let query = parser.parse_query(false)?;
        if parser.pos < parser.tokens.len() {
            return Err(ERR_END.to_string());
        }
        Ok(query)
    }

    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.pos)
    }

    fn peek_at(&self, n: usize) -> Option<&Token> {
        self.tokens.get(self.pos + n)
    }

    fn next(&mut self) -> Option<Token> {
        let t = self.tokens.get(self.pos).cloned();
        if t.is_some() {
            self.pos += 1;
        }
        t
    }

    fn eat(&mut self, t: &Token) -> bool {
        if self.peek() == Some(t) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn parse_query(&mut self, sub: bool) -> PResult<Query> {
        let fields = self.parse_fields(sub)?;
        let mut roots = self.parse_roots()?;
        let expr = self.parse_where()?;
        let grouping = self.parse_group_by()?;
        let ordering = self.parse_order_by(&fields)?;
        let limit = self.parse_limit()?;
        let offset = self.parse_offset()?;
        let output_format = self.parse_into()?;
        if roots.is_empty() {
            roots = self.parse_roots()?;
        }
        if fields.is_empty() {
            return Err(ERR_END.to_string());
        }
        Ok(Query {
            fields,
            roots,
            expr,
            grouping,
            ordering,
            limit,
            offset,
            output_format,
            raw: self.raw.clone(),
        })
    }

    fn parse_fields(&mut self, sub: bool) -> PResult<Vec<Column>> {
        let mut fields = vec![];
        if self.peek() == Some(&Token::Select) {
            self.pos += 1;
        }
        loop {
            match self.peek() {
                None => break,
                Some(Token::Comma) => {
                    self.pos += 1;
                    continue;
                }
                Some(Token::Close) if sub => break,
                Some(t) if t.is_clause_keyword() => break,
                Some(Token::Select) | Some(Token::As) => break,
                Some(Token::Mul) if sub => {
                    self.pos += 1;
                    fields.push(Column { expr: Expr::Literal("*".to_string()), alias: None });
                    continue;
                }
                Some(_) => {}
            }
            let expr = self.parse_column_expr()?;
            let mut alias = None;
            if self.peek() == Some(&Token::As) {
                match self.peek_at(1) {
                    Some(Token::Str(s)) => {
                        alias = Some(s.clone());
                        self.pos += 2;
                    }
                    _ => break,
                }
            }
            fields.push(Column { expr, alias });
        }
        if fields.is_empty() && self.peek().is_none() {
            return Err("Error parsing fields, no selector found".to_string());
        }
        Ok(fields)
    }

    /// expression in the column list: arithmetic with an optional (ignored) comparison
    fn parse_column_expr(&mut self) -> PResult<Expr> {
        let expr = self.parse_arith(false)?;
        if let Some(op) = self.peek_cmp_op() {
            self.pos += 1;
            let _right = self.parse_arith(false)?;
            let _ = op;
        }
        Ok(expr)
    }

    fn peek_cmp_op(&self) -> Option<CmpOp> {
        match self.peek() {
            Some(Token::Eq) => Some(CmpOp::Eq),
            Some(Token::Ne) => Some(CmpOp::Ne),
            Some(Token::Eeq) => Some(CmpOp::Eeq),
            Some(Token::Ene) => Some(CmpOp::Ene),
            Some(Token::Gt) => Some(CmpOp::Gt),
            Some(Token::Gte) => Some(CmpOp::Gte),
            Some(Token::Lt) => Some(CmpOp::Lt),
            Some(Token::Lte) => Some(CmpOp::Lte),
            Some(Token::Rx) => Some(CmpOp::Rx),
            Some(Token::NotRx) => Some(CmpOp::NotRx),
            Some(Token::Like) => Some(CmpOp::Like),
            Some(Token::NotLike) => Some(CmpOp::NotLike),
            _ => None,
        }
    }

    fn parse_arith(&mut self, in_where: bool) -> PResult<Expr> {
        let mut left = self.parse_term(in_where)?;
        loop {
            let op = match self.peek() {
                Some(Token::Plus) => ArithOp::Add,
                Some(Token::Minus) => ArithOp::Subtract,
                _ => break,
            };
            self.pos += 1;
            let right = self.parse_term(in_where)?;
            left = Expr::Arith(Box::new(left), op, Box::new(right));
        }
        Ok(left)
    }

    fn parse_term(&mut self, in_where: bool) -> PResult<Expr> {
        let mut left = self.parse_factor(in_where)?;
        loop {
            let op = match self.peek() {
                Some(Token::Mul) => ArithOp::Multiply,
                Some(Token::Div) => ArithOp::Divide,
                Some(Token::Mod) => ArithOp::Modulo,
                _ => break,
            };
            self.pos += 1;
            let right = self.parse_factor(in_where)?;
            left = Expr::Arith(Box::new(left), op, Box::new(right));
        }
        Ok(left)
    }

    fn parse_factor(&mut self, in_where: bool) -> PResult<Expr> {
        match self.peek().cloned() {
            None => Err(ERR_EXPECTING.to_string()),
            Some(Token::Open) => {
                self.pos += 1;
                let inner = if in_where { self.parse_or()? } else { self.parse_column_expr()? };
                if !self.eat(&Token::Close) {
                    return Err("Unmatched parenthesis".to_string());
                }
                Ok(inner)
            }
            Some(Token::Minus) | Some(Token::Plus) => {
                let sign = if self.peek() == Some(&Token::Minus) { "-" } else { "+" };
                self.pos += 1;
                match self.peek().cloned() {
                    Some(Token::Str(s)) => {
                        // a field or function keeps its value, anything else becomes a signed literal
                        if Field::from_str(&s).is_some() || self.is_function_call(&s) {
                            self.parse_factor(in_where)
                        } else {
                            self.pos += 1;
                            Ok(Expr::Literal(format!("{}{}", sign, s)))
                        }
                    }
                    _ => Err(ERR_END.to_string()),
                }
            }
            Some(Token::Str(s)) => {
                self.pos += 1;
                self.parse_word(s, in_where)
            }
            Some(Token::Path(s)) => {
                self.pos += 1;
                Ok(Expr::Literal(s))
            }
            Some(t) => {
                // keywords and operators used as plain strings
                if in_where || !t.is_clause_keyword() {
                    if let Some(w) = t.as_word() {
                        if !matches!(t, Token::Select | Token::As | Token::Open | Token::Close | Token::Comma) {
                            self.pos += 1;
                            return Ok(Expr::Literal(w));
                        }
                    }
                }
                Err(ERR_END.to_string())
            }
        }
    }

    fn is_function_call(&self, s: &str) -> bool {
        if let Some(f) = Function::from_str(s) {
            if self.peek_at(1) == Some(&Token::Open) {
                return true;
            }
            // functions without arguments do not need parentheses
            return !f.is_aggregate() || true;
        }
        false
    }

    fn parse_word(&mut self, s: String, in_where: bool) -> PResult<Expr> {
        // function call?
        if let Some(func) = Function::from_str(&s) {
            if self.peek() == Some(&Token::Open) {
                self.pos += 1;
                let args = self.parse_function_args(in_where)?;
                return Ok(Expr::Function(func, args));
            }
            // a function name without parentheses
            if Field::from_str(&s).is_none() {
                return Ok(Expr::Function(func, vec![]));
            }
        }
        if let Some(field) = Field::from_str(&s) {
            return Ok(Expr::Field(field, None));
        }
        // alias.field
        if !self.aliases.is_empty() {
            if let Some(pos) = s.find('.') {
                let (prefix, rest) = (&s[..pos], &s[pos + 1..]);
                if !prefix.is_empty() && !prefix.chars().all(|c| c.is_ascii_digit()) {
                    if self.aliases.iter().any(|a| a == prefix) {
                        if let Some(field) = Field::from_str(rest) {
                            return Ok(Expr::Field(field, Some(prefix.to_string())));
                        }
                    } else {
                        return Err(format!("Invalid root alias: {}", prefix));
                    }
                }
            }
        }
        Ok(Expr::Literal(s))
    }

    fn parse_function_args(&mut self, in_where: bool) -> PResult<Vec<Expr>> {
        let mut args = vec![];
        loop {
            match self.peek() {
                None => return Err("Unmatched parenthesis".to_string()),
                Some(Token::Close) => {
                    self.pos += 1;
                    break;
                }
                Some(Token::Comma) => {
                    self.pos += 1;
                    continue;
                }
                Some(Token::Mul) => {
                    self.pos += 1;
                    args.push(Expr::Literal("*".to_string()));
                    continue;
                }
                Some(_) => {
                    let e = self.parse_arith(in_where)?;
                    args.push(e);
                }
            }
        }
        Ok(args)
    }

    // ---------------------------------------------------------------- roots

    fn parse_roots(&mut self) -> PResult<Vec<Root>> {
        let mut roots = vec![];
        if self.peek() != Some(&Token::From) {
            return Ok(roots);
        }
        self.pos += 1;
        loop {
            match self.peek().cloned() {
                Some(Token::Path(p)) => {
                    self.pos += 1;
                    if p.is_empty() {
                        return Err(ERR_END.to_string());
                    }
                    let mut root = Root::new(p);
                    self.parse_root_options(&mut root)?;
                    if let Some(a) = &root.alias {
                        self.aliases.push(a.clone());
                    }
                    roots.push(root);
                    if self.peek() == Some(&Token::Comma) {
                        self.pos += 1;
                        if !matches!(self.peek(), Some(Token::Path(_))) {
                            break;
                        }
                        continue;
                    }
                    break;
                }
                _ => break,
            }
        }
        Ok(roots)
    }

    fn parse_root_options(&mut self, root: &mut Root) -> PResult<()> {
        loop {
            match self.peek().cloned() {
                Some(Token::Str(s)) => {
                    let lower = s.to_lowercase();
                    match lower.as_str() {
                        "mindepth" | "maxdepth" | "depth" => {
                            match self.peek_at(1) {
                                Some(Token::Str(v)) => match v.parse::<u32>() {
                                    Ok(n) => {
                                        if lower == "mindepth" {
                                            root.min_depth = n;
                                        } else {
                                            root.max_depth = n;
                                        }
                                        self.pos += 2;
                                    }
                                    Err(_) => return Ok(()),
                                },
                                None => return Err("Error parsing root options".to_string()),
                                _ => return Ok(()),
                            }
                        }
                        "symlinks" | "sym" => {
                            root.symlinks = true;
                            self.pos += 1;
                        }
                        "archives" | "arc" => {
                            root.archives = true;
                            self.pos += 1;
                        }
                        "gitignore" | "git" => {
                            root.gitignore = Some(true);
                            self.pos += 1;
                        }
                        "nogitignore" | "nogit" => {
                            root.gitignore = Some(false);
                            self.pos += 1;
                        }
                        "hgignore" | "hg" => {
                            root.hgignore = Some(true);
                            self.pos += 1;
                        }
                        "nohgignore" | "nohg" => {
                            root.hgignore = Some(false);
                            self.pos += 1;
                        }
                        "dockerignore" | "docker" | "dock" => {
                            root.dockerignore = Some(true);
                            self.pos += 1;
                        }
                        "nodockerignore" | "nodocker" | "nodock" => {
                            root.dockerignore = Some(false);
                            self.pos += 1;
                        }
                        "dfs" => {
                            root.traversal = Traversal::Dfs;
                            self.pos += 1;
                        }
                        "bfs" => {
                            root.traversal = Traversal::Bfs;
                            self.pos += 1;
                        }
                        "regexp" => {
                            root.regexp = true;
                            self.pos += 1;
                        }
                        _ => return Ok(()),
                    }
                }
                Some(Token::As) => match self.peek_at(1) {
                    Some(Token::Str(a)) => {
                        root.alias = Some(a.clone());
                        self.pos += 2;
                    }
                    None => return Err("Error parsing root options".to_string()),
                    _ => return Ok(()),
                },
                _ => return Ok(()),
            }
        }
    }

    // ---------------------------------------------------------------- where

    fn parse_where(&mut self) -> PResult<Option<Expr>> {
        if self.peek() != Some(&Token::Where) {
            return Ok(None);
        }
        self.pos += 1;
        let e = self.parse_or()?;
        Ok(Some(e))
    }

    fn parse_or(&mut self) -> PResult<Expr> {
        let mut left = self.parse_and()?;
        while self.peek() == Some(&Token::Or) {
            self.pos += 1;
            let right = self.parse_and()?;
            left = Expr::Or(Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_and(&mut self) -> PResult<Expr> {
        let mut left = self.parse_not()?;
        while self.peek() == Some(&Token::And) {
            self.pos += 1;
            let right = self.parse_not()?;
            left = Expr::And(Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_not(&mut self) -> PResult<Expr> {
        if self.peek() == Some(&Token::Not) {
            self.pos += 1;
            let e = self.parse_not()?;
            return Ok(Expr::Not(Box::new(e)));
        }
        self.parse_cond()
    }

    fn parse_cond(&mut self) -> PResult<Expr> {
        if self.peek() == Some(&Token::Exists) {
            self.pos += 1;
            return self.parse_exists(false);
        }
        let left = self.parse_arith(true)?;
        let mut negated = false;
        if self.peek() == Some(&Token::Not) {
            negated = true;
            self.pos += 1;
            match self.peek() {
                Some(Token::In) | Some(Token::Like) | Some(Token::NotLike) | Some(Token::Between) | Some(Token::Exists) => {}
                Some(_) if self.peek_cmp_op().is_some() => {}
                _ => return Err("Error parsing list".to_string()),
            }
            if self.peek() == Some(&Token::Exists) {
                self.pos += 1;
                return self.parse_exists(true);
            }
        }
        if let Some(op) = self.peek_cmp_op() {
            self.pos += 1;
            let right = self.parse_arith(true)?;
            let op = if negated { op.negate() } else { op };
            return Ok(Expr::Compare(Box::new(left), op, Box::new(right)));
        }
        match self.peek() {
            Some(Token::Between) => {
                self.pos += 1;
                let from = match self.peek() {
                    Some(Token::And) | None => return Err("Error parsing BETWEEN operator".to_string()),
                    _ => self.parse_arith(true)?,
                };
                if !self.eat(&Token::And) {
                    return Err("Error parsing BETWEEN operator".to_string());
                }
                let to = self.parse_arith(true)?;
                Ok(Expr::Between(Box::new(left), Box::new(from), Box::new(to), negated))
            }
            Some(Token::In) => {
                self.pos += 1;
                if !self.eat(&Token::Open) {
                    return Err(ERR_END.to_string());
                }
                if self.peek() == Some(&Token::Select) {
                    let q = self.parse_query(true)?;
                    if !self.eat(&Token::Close) {
                        return Err("Unmatched parenthesis".to_string());
                    }
                    return Ok(Expr::InSubquery(Box::new(left), Box::new(q), negated));
                }
                let mut list = vec![];
                loop {
                    match self.peek() {
                        None => return Err("Error parsing list".to_string()),
                        Some(Token::Close) => {
                            self.pos += 1;
                            break;
                        }
                        Some(Token::Comma) => {
                            self.pos += 1;
                        }
                        Some(_) => {
                            let e = self.parse_arith(true)?;
                            list.push(e);
                        }
                    }
                }
                Ok(Expr::InList(Box::new(left), list, negated))
            }
            _ => {
                if negated {
                    return Err("Error parsing list".to_string());
                }
                Ok(left)
            }
        }
    }

    fn parse_exists(&mut self, negated: bool) -> PResult<Expr> {
        if !self.eat(&Token::Open) {
            return Err(ERR_END.to_string());
        }
        let q = self.parse_query(true)?;
        if !self.eat(&Token::Close) {
            return Err("Unmatched parenthesis".to_string());
        }
        Ok(Expr::Exists(Box::new(q), negated))
    }

    // ---------------------------------------------------------------- group / order

    fn parse_group_by(&mut self) -> PResult<Vec<Expr>> {
        let mut groups = vec![];
        if self.peek() != Some(&Token::Group) {
            return Ok(groups);
        }
        if self.peek_at(1) != Some(&Token::By) {
            return Ok(groups);
        }
        self.pos += 2;
        loop {
            match self.peek() {
                None => break,
                Some(Token::Comma) => {
                    self.pos += 1;
                }
                Some(t) if t.is_clause_keyword() || matches!(t, Token::Close) => break,
                Some(_) => {
                    let e = self.parse_arith(false)?;
                    groups.push(e);
                }
            }
        }
        Ok(groups)
    }

    fn parse_order_by(&mut self, fields: &[Column]) -> PResult<Vec<Ordering>> {
        let mut ordering = vec![];
        if self.peek() != Some(&Token::Order) {
            return Ok(ordering);
        }
        if self.peek_at(1) != Some(&Token::By) {
            return Ok(ordering);
        }
        self.pos += 2;
        loop {
            match self.peek() {
                None => break,
                Some(Token::Comma) => {
                    self.pos += 1;
                }
                Some(t) if t.is_clause_keyword() || matches!(t, Token::Close) => break,
                Some(_) => {
                    let e = self.parse_arith(false)?;
                    let e = match &e {
                        Expr::Literal(s) => match s.parse::<usize>() {
                            Ok(n) => {
                                if n == 0 || n > fields.len() {
                                    return Err("Order by field index is out of range".to_string());
                                }
                                fields[n - 1].expr.clone()
                            }
                            Err(_) => e,
                        },
                        _ => e,
                    };
                    let mut asc = true;
                    if self.peek() == Some(&Token::Asc) {
                        self.pos += 1;
                    } else if self.peek() == Some(&Token::Desc) {
                        self.pos += 1;
                        asc = false;
                    }
                    ordering.push(Ordering { expr: e, asc });
                }
            }
        }
        Ok(ordering)
    }

    fn parse_limit(&mut self) -> PResult<usize> {
        if self.peek() != Some(&Token::Limit) {
            return Ok(0);
        }
        match self.peek_at(1).cloned() {
            None => Err("Error parsing limit, limit value not found".to_string()),
            Some(Token::Str(s)) => match s.parse::<usize>() {
                Ok(n) => {
                    self.pos += 2;
                    Ok(n)
                }
                Err(_) => {
                    self.pos += 1;
                    Ok(0)
                }
            },
            Some(_) => {
                self.pos += 1;
                Ok(0)
            }
        }
    }

    fn parse_offset(&mut self) -> PResult<usize> {
        if self.peek() != Some(&Token::Offset) {
            return Ok(0);
        }
        match self.peek_at(1).cloned() {
            None => Err("Error parsing offset, offset value not found".to_string()),
            Some(Token::Str(s)) => match s.parse::<usize>() {
                Ok(n) => {
                    self.pos += 2;
                    Ok(n)
                }
                Err(_) => Err("Error parsing offset".to_string()),
            },
            Some(_) => Err("Error parsing offset".to_string()),
        }
    }

    fn parse_into(&mut self) -> PResult<OutputFormat> {
        if self.peek() != Some(&Token::Into) {
            return Ok(OutputFormat::Tabs);
        }
        match self.peek_at(1).cloned() {
            None => Err("Error parsing output format".to_string()),
            Some(Token::Str(s)) => {
                let f = match s.to_lowercase().as_str() {
                    "tabs" => OutputFormat::Tabs,
                    "lines" => OutputFormat::Lines,
                    "list" => OutputFormat::List,
                    "csv" => OutputFormat::Csv,
                    "json" => OutputFormat::Json,
                    "html" => OutputFormat::Html,
                    _ => return Err("Unknown output format".to_string()),
                };
                self.pos += 2;
                Ok(f)
            }
            Some(_) => Err("Unknown output format".to_string()),
        }
    }
}
EOF
echo ok"}

actions.command:
cat > /workspace/src/parser.rs <<'EOF'
//! Query parser.

use crate::field::Field;
use crate::function::Function;
use crate::lexer::{Lexer, Token};
use crate::query::*;

pub struct Parser {
    tokens: Vec<Token>,
    pos: usize,
    aliases: Vec<String>,
    raw: String,
}

type PResult<T> = Result<T, String>;

const ERR_END: &str = "could not parse tokens at the end of the query";
const ERR_EXPECTING: &str = "Error parsing expression, expecting string";

impl Parser {
    pub fn parse_args(args: &[String]) -> PResult<Query> {
        let tokens = Lexer::tokenize(args)?;
        let mut parser = Parser {
            tokens,
            pos: 0,
            aliases: vec![],
            raw: args.join(" "),
        };
        let query = parser.parse_query(false)?;
        if parser.pos < parser.tokens.len() {
            return Err(ERR_END.to_string());
        }
        Ok(query)
    }

    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.pos)
    }

    fn peek_at(&self, n: usize) -> Option<&Token> {
        self.tokens.get(self.pos + n)
    }

    fn next(&mut self) -> Option<Token> {
        let t = self.tokens.get(self.pos).cloned();
        if t.is_some() {
            self.pos += 1;
        }
        t
    }

    fn eat(&mut self, t: &Token) -> bool {
        if self.peek() == Some(t) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn parse_query(&mut self, sub: bool) -> PResult<Query> {
        let fields = self.parse_fields(sub)?;
        let mut roots = self.parse_roots()?;
        let expr = self.parse_where()?;
        let grouping = self.parse_group_by()?;
        let ordering = self.parse_order_by(&fields)?;
        let limit = self.parse_limit()?;
        let offset = self.parse_offset()?;
        let output_format = self.parse_into()?;
        if roots.is_empty() {
            roots = self.parse_roots()?;
        }
        if fields.is_empty() {
            return Err(ERR_END.to_string());
        }
        Ok(Query {
            fields,
            roots,
            expr,
            grouping,
            ordering,
            limit,
            offset,
            output_format,
            raw: self.raw.clone(),
        })
    }

    fn parse_fields(&mut self, sub: bool) -> PResult<Vec<Column>> {
        let mut fields = vec![];
        if self.peek() == Some(&Token::Select) {
            self.pos += 1;
        }
        loop {
            match self.peek() {
                None => break,
                Some(Token::Comma) => {
                    self.pos += 1;
                    continue;
                }
                Some(Token::Close) if sub => break,
                Some(t) if t.is_clause_keyword() => break,
                Some(Token::Select) | Some(Token::As) => break,
                Some(Token::Mul) if sub => {
                    self.pos += 1;
                    fields.push(Column { expr: Expr::Literal("*".to_string()), alias: None });
                    continue;
                }
                Some(_) => {}
            }
            let expr = self.parse_column_expr()?;
            let mut alias = None;
            if self.peek() == Some(&Token::As) {
                match self.peek_at(1) {
                    Some(Token::Str(s)) => {
                        alias = Some(s.clone());
                        self.pos += 2;
                    }
                    _ => break,
                }
            }
            fields.push(Column { expr, alias });
        }
        if fields.is_empty() && self.peek().is_none() {
            return Err("Error parsing fields, no selector found".to_string());
        }
        Ok(fields)
    }

    /// expression in the column list: arithmetic with an optional (ignored) comparison
    fn parse_column_expr(&mut self) -> PResult<Expr> {
        let expr = self.parse_arith(false)?;
        if let Some(op) = self.peek_cmp_op() {
            self.pos += 1;
            let _right = self.parse_arith(false)?;
            let _ = op;
        }
        Ok(expr)
    }

    fn peek_cmp_op(&self) -> Option<CmpOp> {
        match self.peek() {
            Some(Token::Eq) => Some(CmpOp::Eq),
            Some(Token::Ne) => Some(CmpOp::Ne),
            Some(Token::Eeq) => Some(CmpOp::Eeq),
            Some(Token::Ene) => Some(CmpOp::Ene),
            Some(Token::Gt) => Some(CmpOp::Gt),
            Some(Token::Gte) => Some(CmpOp::Gte),
            Some(Token::Lt) => Some(CmpOp::Lt),
            Some(Token::Lte) => Some(CmpOp::Lte),
            Some(Token::Rx) => Some(CmpOp::Rx),
            Some(Token::NotRx) => Some(CmpOp::NotRx),
            Some(Token::Like) => Some(CmpOp::Like),
            Some(Token::NotLike) => Some(CmpOp::NotLike),
            _ => None,
        }
    }

    fn parse_arith(&mut self, in_where: bool) -> PResult<Expr> {
        let mut left = self.parse_term(in_where)?;
        loop {
            let op = match self.peek() {
                Some(Token::Plus) => ArithOp::Add,
                Some(Token::Minus) => ArithOp::Subtract,
                _ => break,
            };
            self.pos += 1;
            let right = self.parse_term(in_where)?;
            left = Expr::Arith(Box::new(left), op, Box::new(right));
        }
        Ok(left)
    }

    fn parse_term(&mut self, in_where: bool) -> PResult<Expr> {
        let mut left = self.parse_factor(in_where)?;
        loop {
            let op = match self.peek() {
                Some(Token::Mul) => ArithOp::Multiply,
                Some(Token::Div) => ArithOp::Divide,
                Some(Token::Mod) => ArithOp::Modulo,
                _ => break,
            };
            self.pos += 1;
            let right = self.parse_factor(in_where)?;
            left = Expr::Arith(Box::new(left), op, Box::new(right));
        }
        Ok(left)
    }

    fn parse_factor(&mut self, in_where: bool) -> PResult<Expr> {
        match self.peek().cloned() {
            None => Err(ERR_EXPECTING.to_string()),
            Some(Token::Open) => {
                self.pos += 1;
                let inner = if in_where { self.parse_or()? } else { self.parse_column_expr()? };
                if !self.eat(&Token::Close) {
                    return Err("Unmatched parenthesis".to_string());
                }
                Ok(inner)
            }
            Some(Token::Minus) | Some(Token::Plus) => {
                let sign = if self.peek() == Some(&Token::Minus) { "-" } else { "+" };
                self.pos += 1;
                match self.peek().cloned() {
                    Some(Token::Str(s)) => {
                        // a field or function keeps its value, anything else becomes a signed literal
                        if Field::from_str(&s).is_some() || self.is_function_call(&s) {
                            self.parse_factor(in_where)
                        } else {
                            self.pos += 1;
                            Ok(Expr::Literal(format!("{}{}", sign, s)))
                        }
                    }
                    _ => Err(ERR_END.to_string()),
                }
            }
            Some(Token::Str(s)) => {
                self.pos += 1;
                self.parse_word(s, in_where)
            }
            Some(Token::Path(s)) => {
                self.pos += 1;
                Ok(Expr::Literal(s))
            }
            Some(t) => {
                // keywords and operators used as plain strings
                if in_where || !t.is_clause_keyword() {
                    if let Some(w) = t.as_word() {
                        if !matches!(t, Token::Select | Token::As | Token::Open | Token::Close | Token::Comma) {
                            self.pos += 1;
                            return Ok(Expr::Literal(w));
                        }
                    }
                }
                Err(ERR_END.to_string())
            }
        }
    }

    fn is_function_call(&self, s: &str) -> bool {
        if let Some(f) = Function::from_str(s) {
            if self.peek_at(1) == Some(&Token::Open) {
                return true;
            }
            // functions without arguments do not need parentheses
            return !f.is_aggregate() || true;
        }
        false
    }

    fn parse_word(&mut self, s: String, in_where: bool) -> PResult<Expr> {
        // function call?
        if let Some(func) = Function::from_str(&s) {
            if self.peek() == Some(&Token::Open) {
                self.pos += 1;
                let args = self.parse_function_args(in_where)?;
                return Ok(Expr::Function(func, args));
            }
            // a function name without parentheses
            if Field::from_str(&s).is_none() {
                return Ok(Expr::Function(func, vec![]));
            }
        }
        if let Some(field) = Field::from_str(&s) {
            return Ok(Expr::Field(field, None));
        }
        // alias.field
        if !self.aliases.is_empty() {
            if let Some(pos) = s.find('.') {
                let (prefix, rest) = (&s[..pos], &s[pos + 1..]);
                if !prefix.is_empty() && !prefix.chars().all(|c| c.is_ascii_digit()) {
                    if self.aliases.iter().any(|a| a == prefix) {
                        if let Some(field) = Field::from_str(rest) {
                            return Ok(Expr::Field(field, Some(prefix.to_string())));
                        }
                    } else {
                        return Err(format!("Invalid root alias: {}", prefix));
                    }
                }
            }
        }
        Ok(Expr::Literal(s))
    }

    fn parse_function_args(&mut self, in_where: bool) -> PResult<Vec<Expr>> {
        let mut args = vec![];
        loop {
            match self.peek() {
                None => return Err("Unmatched parenthesis".to_string()),
                Some(Token::Close) => {
                    self.pos += 1;
                    break;
                }
                Some(Token::Comma) => {
                    self.pos += 1;
                    continue;
                }
                Some(Token::Mul) => {
                    self.pos += 1;
                    args.push(Expr::Literal("*".to_string()));
                    continue;
                }
                Some(_) => {
                    let e = self.parse_arith(in_where)?;
                    args.push(e);
                }
            }
        }
        Ok(args)
    }

    // ---------------------------------------------------------------- roots

    fn parse_roots(&mut self) -> PResult<Vec<Root>> {
        let mut roots = vec![];
        if self.peek() != Some(&Token::From) {
            return Ok(roots);
        }
        self.pos += 1;
        loop {
            match self.peek().cloned() {
                Some(Token::Path(p)) => {
                    self.pos += 1;
                    if p.is_empty() {
                        return Err(ERR_END.to_string());
                    }
                    let mut root = Root::new(p);
                    self.parse_root_options(&mut root)?;
                    if let Some(a) = &root.alias {
                        self.aliases.push(a.clone());
                    }
                    roots.push(root);
                    if self.peek() == Some(&Token::Comma) {
                        self.pos += 1;
                        if !matches!(self.peek(), Some(Token::Path(_))) {
                            break;
                        }
                        continue;
                    }
                    break;
                }
                _ => break,
            }
        }
        Ok(roots)
    }

    fn parse_root_options(&mut self, root: &mut Root) -> PResult<()> {
        loop {
            match self.peek().cloned() {
                Some(Token::Str(s)) => {
                    let lower = s.to_lowercase();
                    match lower.as_str() {
                        "mindepth" | "maxdepth" | "depth" => {
                            match self.peek_at(1) {
                                Some(Token::Str(v)) => match v.parse::<u32>() {
                                    Ok(n) => {
                                        if lower == "mindepth" {
                                            root.min_depth = n;
                                        } else {
                                            root.max_depth = n;
                                        }
                                        self.pos += 2;
                                    }
                                    Err(_) => return Ok(()),
                                },
                                None => return Err("Error parsing root options".to_string()),
                                _ => return Ok(()),
                            }
                        }
                        "symlinks" | "sym" => {
                            root.symlinks = true;
                            self.pos += 1;
                        }
                        "archives" | "arc" => {
                            root.archives = true;
                            self.pos += 1;
                        }
                        "gitignore" | "git" => {
                            root.gitignore = Some(true);
                            self.pos += 1;
                        }
                        "nogitignore" | "nogit" => {
                            root.gitignore = Some(false);
                            self.pos += 1;
                        }
                        "hgignore" | "hg" => {
                            root.hgignore = Some(true);
                            self.pos += 1;
                        }
                        "nohgignore" | "nohg" => {
                            root.hgignore = Some(false);
                            self.pos += 1;
                        }
                        "dockerignore" | "docker" | "dock" => {
                            root.dockerignore = Some(true);
                            self.pos += 1;
                        }
                        "nodockerignore" | "nodocker" | "nodock" => {
                            root.dockerignore = Some(false);
                            self.pos += 1;
                        }
                        "dfs" => {
                            root.traversal = Traversal::Dfs;
                            self.pos += 1;
                        }
                        "bfs" => {
                            root.traversal = Traversal::Bfs;
                            self.pos += 1;
                        }
                        "regexp" => {
                            root.regexp = true;
                            self.pos += 1;
                        }
                        _ => return Ok(()),
                    }
                }
                Some(Token::As) => match self.peek_at(1) {
                    Some(Token::Str(a)) => {
                        root.alias = Some(a.clone());
                        self.pos += 2;
                    }
                    None => return Err("Error parsing root options".to_string()),
                    _ => return Ok(()),
                },
                _ => return Ok(()),
            }
        }
    }

    // ---------------------------------------------------------------- where

    fn parse_where(&mut self) -> PResult<Option<Expr>> {
        if self.peek() != Some(&Token::Where) {
            return Ok(None);
        }
        self.pos += 1;
        let e = self.parse_or()?;
        Ok(Some(e))
    }

    fn parse_or(&mut self) -> PResult<Expr> {
        let mut left = self.parse_and()?;
        while self.peek() == Some(&Token::Or) {
            self.pos += 1;
            let right = self.parse_and()?;
            left = Expr::Or(Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_and(&mut self) -> PResult<Expr> {
        let mut left = self.parse_not()?;
        while self.peek() == Some(&Token::And) {
            self.pos += 1;
            let right = self.parse_not()?;
            left = Expr::And(Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_not(&mut self) -> PResult<Expr> {
        if self.peek() == Some(&Token::Not) {
            self.pos += 1;
            let e = self.parse_not()?;
            return Ok(Expr::Not(Box::new(e)));
        }
        self.parse_cond()
    }

    fn parse_cond(&mut self) -> PResult<Expr> {
        if self.peek() == Some(&Token::Exists) {
            self.pos += 1;
            return self.parse_exists(false);
        }
        let left = self.parse_arith(true)?;
        let mut negated = false;
        if self.peek() == Some(&Token::Not) {
            negated = true;
            self.pos += 1;
            match self.peek() {
                Some(Token::In) | Some(Token::Like) | Some(Token::NotLike) | Some(Token::Between) | Some(Token::Exists) => {}
                Some(_) if self.peek_cmp_op().is_some() => {}
                _ => return Err("Error parsing list".to_string()),
            }
            if self.peek() == Some(&Token::Exists) {
                self.pos += 1;
                return self.parse_exists(true);
            }
        }
        if let Some(op) = self.peek_cmp_op() {
            self.pos += 1;
            let right = self.parse_arith(true)?;
            let op = if negated { op.negate() } else { op };
            return Ok(Expr::Compare(Box::new(left), op, Box::new(right)));
        }
        match self.peek() {
            Some(Token::Between) => {
                self.pos += 1;
                let from = match self.peek() {
                    Some(Token::And) | None => return Err("Error parsing BETWEEN operator".to_string()),
                    _ => self.parse_arith(true)?,
                };
                if !self.eat(&Token::And) {
                    return Err("Error parsing BETWEEN operator".to_string());
                }
                let to = self.parse_arith(true)?;
                Ok(Expr::Between(Box::new(left), Box::new(from), Box::new(to), negated))
            }
            Some(Token::In) => {
                self.pos += 1;
                if !self.eat(&Token::Open) {
                    return Err(ERR_END.to_string());
                }
                if self.peek() == Some(&Token::Select) {
                    let q = self.parse_query(true)?;
                    if !self.eat(&Token::Close) {
                        return Err("Unmatched parenthesis".to_string());
                    }
                    return Ok(Expr::InSubquery(Box::new(left), Box::new(q), negated));
                }
                let mut list = vec![];
                loop {
                    match self.peek() {
                        None => return Err("Error parsing list".to_string()),
                        Some(Token::Close) => {
                            self.pos += 1;
                            break;
                        }
                        Some(Token::Comma) => {
                            self.pos += 1;
                        }
                        Some(_) => {
                            let e = self.parse_arith(true)?;
                            list.push(e);
                        }
                    }
                }
                Ok(Expr::InList(Box::new(left), list, negated))
            }
            _ => {
                if negated {
                    return Err("Error parsing list".to_string());
                }
                Ok(left)
            }
        }
    }

    fn parse_exists(&mut self, negated: bool) -> PResult<Expr> {
        if !self.eat(&Token::Open) {
            return Err(ERR_END.to_string());
        }
        let q = self.parse_query(true)?;
        if !self.eat(&Token::Close) {
            return Err("Unmatched parenthesis".to_string());
        }
        Ok(Expr::Exists(Box::new(q), negated))
    }

    // ---------------------------------------------------------------- group / order

    fn parse_group_by(&mut self) -> PResult<Vec<Expr>> {
        let mut groups = vec![];
        if self.peek() != Some(&Token::Group) {
            return Ok(groups);
        }
        if self.peek_at(1) != Some(&Token::By) {
            return Ok(groups);
        }
        self.pos += 2;
        loop {
            match self.peek() {
                None => break,
                Some(Token::Comma) => {
                    self.pos += 1;
                }
                Some(t) if t.is_clause_keyword() || matches!(t, Token::Close) => break,
                Some(_) => {
                    let e = self.parse_arith(false)?;
                    groups.push(e);
                }
            }
        }
        Ok(groups)
    }

    fn parse_order_by(&mut self, fields: &[Column]) -> PResult<Vec<Ordering>> {
        let mut ordering = vec![];
        if self.peek() != Some(&Token::Order) {
            return Ok(ordering);
        }
        if self.peek_at(1) != Some(&Token::By) {
            return Ok(ordering);
        }
        self.pos += 2;
        loop {
            match self.peek() {
                None => break,
                Some(Token::Comma) => {
                    self.pos += 1;
                }
                Some(t) if t.is_clause_keyword() || matches!(t, Token::Close) => break,
                Some(_) => {
                    let e = self.parse_arith(false)?;
                    let e = match &e {
                        Expr::Literal(s) => match s.parse::<usize>() {
                            Ok(n) => {
                                if n == 0 || n > fields.len() {
                                    return Err("Order by field index is out of range".to_string());
                                }
                                fields[n - 1].expr.clone()
                            }
                            Err(_) => e,
                        },
                        _ => e,
                    };
                    let mut asc = true;
                    if self.peek() == Some(&Token::Asc) {
                        self.pos += 1;
                    } else if self.peek() == Some(&Token::Desc) {
                        self.pos += 1;
                        asc = false;
                    }
                    ordering.push(Ordering { expr: e, asc });
                }
            }
        }
        Ok(ordering)
    }

    fn parse_limit(&mut self) -> PResult<usize> {
        if self.peek() != Some(&Token::Limit) {
            return Ok(0);
        }
        match self.peek_at(1).cloned() {
            None => Err("Error parsing limit, limit value not found".to_string()),
            Some(Token::Str(s)) => match s.parse::<usize>() {
                Ok(n) => {
                    self.pos += 2;
                    Ok(n)
                }
                Err(_) => {
                    self.pos += 1;
                    Ok(0)
                }
            },
            Some(_) => {
                self.pos += 1;
                Ok(0)
            }
        }
    }

    fn parse_offset(&mut self) -> PResult<usize> {
        if self.peek() != Some(&Token::Offset) {
            return Ok(0);
        }
        match self.peek_at(1).cloned() {
            None => Err("Error parsing offset, offset value not found".to_string()),
            Some(Token::Str(s)) => match s.parse::<usize>() {
                Ok(n) => {
                    self.pos += 2;
                    Ok(n)
                }
                Err(_) => Err("Error parsing offset".to_string()),
            },
            Some(_) => Err("Error parsing offset".to_string()),
        }
    }

    fn parse_into(&mut self) -> PResult<OutputFormat> {
        if self.peek() != Some(&Token::Into) {
            return Ok(OutputFormat::Tabs);
        }
        match self.peek_at(1).cloned() {
            None => Err("Error parsing output format".to_string()),
            Some(Token::Str(s)) => {
                let f = match s.to_lowercase().as_str() {
                    "tabs" => OutputFormat::Tabs,
                    "lines" => OutputFormat::Lines,
                    "list" => OutputFormat::List,
                    "csv" => OutputFormat::Csv,
                    "json" => OutputFormat::Json,
                    "html" => OutputFormat::Html,
                    _ => return Err("Unknown output format".to_string()),
                };
                self.pos += 2;
                Ok(f)
            }
            Some(_) => Err("Unknown output format".to_string()),
        }
    }
}
EOF
