//! Helper routines: number parsing and formatting, globs, sizes, durations.

use regex::Regex;

/// Format a float the way Rust's Display does (no trailing ".0").
pub fn format_f64(v: f64) -> String {
    if v == 0.0 {
        return "0".to_string();
    }
    format!("{}", v)
}

/// Parse a number with optional file size suffix. Returns None if not numeric.
pub fn parse_number(s: &str) -> Option<f64> {
    let s = s.trim();
    if s.is_empty() {
        return None;
    }
    if let Ok(v) = s.parse::<f64>() {
        if v.is_finite() {
            return Some(v);
        }
        return None;
    }
    parse_size(s).map(|v| v as f64)
}

/// Parse a file size with unit suffix (k, kb, kib, m, mb, g, gb, t, tb), case insensitive.
pub fn parse_size(s: &str) -> Option<f64> {
    let s = s.trim().to_lowercase();
    let idx = s.find(|c: char| !(c.is_ascii_digit() || c == '.' || c == '-' || c == '+'))?;
    let (num, unit) = s.split_at(idx);
    let num: f64 = num.parse().ok()?;
    let mult: f64 = match unit {
        "k" | "kib" => 1024.0,
        "kb" => 1000.0,
        "m" | "mib" => 1024.0 * 1024.0,
        "mb" => 1000.0 * 1000.0,
        "g" | "gib" => 1024.0 * 1024.0 * 1024.0,
        "gb" => 1000.0 * 1000.0 * 1000.0,
        "t" | "tib" => 1024.0 * 1024.0 * 1024.0 * 1024.0,
        "tb" => 1000.0 * 1000.0 * 1000.0 * 1000.0,
        _ => return None,
    };
    Some(num * mult)
}

pub fn parse_bool(s: &str) -> bool {
    matches!(s.trim().to_lowercase().as_str(), "true" | "1" | "yes" | "y" | "on")
}

/// Convert a glob pattern (with * and ?) into an anchored case-insensitive regex.
pub fn glob_to_regex(pattern: &str) -> Result<Regex, String> {
    let mut re = String::from("^(?i)");
    for c in pattern.chars() {
        match c {
            '*' => re.push_str(".*"),
            '?' => re.push('.'),
            c => re.push_str(&regex::escape(&c.to_string())),
        }
    }
    re.push('$');
    Regex::new(&re).map_err(|_| format!("Incorrect regex expression: {}", pattern))
}

pub fn is_glob(pattern: &str) -> bool {
    pattern.contains('*') || pattern.contains('?')
}

/// Convert an SQL LIKE pattern into a regex.
pub fn like_to_regex(pattern: &str) -> Result<Regex, String> {
    if pattern.is_empty() {
        return Err(format!("Error parsing LIKE expression: {}", pattern));
    }
    let mut re = String::from("^(?i)");
    for c in pattern.chars() {
        match c {
            '%' => re.push_str(".*"),
            '_' => re.push('.'),
            c => re.push_str(&regex::escape(&c.to_string())),
        }
    }
    re.push('$');
    Regex::new(&re).map_err(|_| format!("Error parsing LIKE expression: {}", pattern))
}

pub fn compile_regex(pattern: &str) -> Result<Regex, String> {
    Regex::new(pattern).map_err(|_| format!("Incorrect regex expression: {}", pattern))
}

const SCALE_BINARY: [&str; 9] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB", "ZiB", "YiB"];
const SCALE_DECIMAL: [&str; 9] = ["B", "KB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB"];
const SCALE_SHORT: [&str; 9] = ["B", "K", "M", "G", "T", "P", "E", "Z", "Y"];

struct SizeFormat {
    decimal_places: Option<usize>,
    space: bool,
    decimal_divider: bool,
    decimal_units: bool,
    short_units: bool,
    fixed_at: Option<usize>,
}

fn parse_size_format(fmt: &str) -> Option<SizeFormat> {
    let mut f = SizeFormat {
        decimal_places: None,
        space: false,
        decimal_divider: false,
        decimal_units: false,
        short_units: false,
        fixed_at: None,
    };
    let chars: Vec<char> = fmt.chars().collect();
    let mut i = 0;
    if chars.len() >= 2 && chars[0] == '%' && chars[1] == '.' {
        i = 2;
        let start = i;
        while i < chars.len() && chars[i].is_ascii_digit() {
            i += 1;
        }
        if i > start {
            let n: String = chars[start..i].iter().collect();
            f.decimal_places = n.parse().ok();
        }
    }
    if i < chars.len() && chars[i] == ' ' {
        f.space = true;
        i += 1;
    }
    let mut after_unit = false;
    let mut last_unit_b = false;
    while i < chars.len() {
        let c = chars[i].to_ascii_lowercase();
        match c {
            'd' => {
                f.decimal_divider = true;
                f.decimal_units = true;
                last_unit_b = false;
            }
            'c' => {
                f.decimal_units = true;
                last_unit_b = false;
            }
            's' => {
                f.short_units = true;
                last_unit_b = false;
            }
            'k' | 'm' | 'g' | 't' | 'p' | 'e' => {
                if f.fixed_at.is_some() {
                    return None;
                }
                f.fixed_at = Some(match c {
                    'k' => 1,
                    'm' => 2,
                    'g' => 3,
                    't' => 4,
                    'p' => 5,
                    _ => 6,
                });
                if (c == 'k' || c == 'm') && f.decimal_places.is_none() {
                    f.decimal_places = Some(0);
                }
                after_unit = true;
                last_unit_b = false;
            }
            'b' => {
                if last_unit_b {
                    return None;
                }
                if after_unit {
                    // kb, mb -> decimal kilo
                    if i >= 1 && chars[i - 1].to_ascii_lowercase() != 'i' {
                        f.decimal_divider = true;
                        f.decimal_units = true;
                    }
                } else {
                    if f.fixed_at.is_some() {
                        return None;
                    }
                    f.fixed_at = Some(0);
                    after_unit = true;
                }
                last_unit_b = true;
            }
            'i' => {
                // only valid as part of "ib" after a unit
                if !after_unit || i + 1 >= chars.len() || chars[i + 1].to_ascii_lowercase() != 'b' {
                    return None;
                }
                last_unit_b = false;
            }
            c if c.is_alphabetic() => return None,
            _ => break,
        }
        i += 1;
    }
    Some(f)
}

/// Format a file size (humansize-like).
pub fn format_size(size: u64, fmt: &str) -> Option<String> {
    let f = parse_size_format(fmt)?;
    let divider: f64 = if f.decimal_divider { 1000.0 } else { 1024.0 };
    let mut value = size as f64;
    let mut idx = 0usize;
    match f.fixed_at {
        Some(0) => {}
        Some(n) => {
            while idx < n {
                value /= divider;
                idx += 1;
            }
        }
        None => {
            while value >= divider && idx < 8 {
                value /= divider;
                idx += 1;
            }
        }
    }
    let unit = if f.short_units {
        SCALE_SHORT[idx]
    } else if f.decimal_units {
        SCALE_DECIMAL[idx]
    } else {
        SCALE_BINARY[idx]
    };
    let places = if value.fract() == 0.0 { 0 } else { f.decimal_places.unwrap_or(2) };
    let space = if f.space { " " } else { "" };
    Some(format!("{:.*}{}{}", places, value, space, unit))
}

/// Format a duration in seconds like "1d,2h,3m,4s".
pub fn format_time(secs: u64) -> String {
    if secs == 0 {
        return "0μs".to_string();
    }
    let mut parts = vec![];
    let d = secs / 86400;
    let h = (secs % 86400) / 3600;
    let m = (secs % 3600) / 60;
    let s = secs % 60;
    if d > 0 {
        parts.push(format!("{}d", d));
    }
    if h > 0 {
        parts.push(format!("{}h", h));
    }
    if m > 0 {
        parts.push(format!("{}m", m));
    }
    if s > 0 {
        parts.push(format!("{}s", s));
    }
    parts.join(",")
}

pub fn html_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '&' => out.push_str("&amp;"),
            '"' => out.push_str("&quot;"),
            c => out.push(c),
        }
    }
    out
}

pub fn csv_escape(s: &str) -> String {
    if s.contains(',') || s.contains('"') || s.contains('\n') || s.contains('\r') {
        format!("\"{}\"", s.replace('"', "\"\""))
    } else {
        s.to_string()
    }
}
