        let hour = c.get(4).map(|v| v.as_str().parse::<u32>().ok());
        let minute = c.get(5).map(|v| v.as_str().parse::<u32>().ok());
        let second = c.get(6).map(|v| v.as_str().parse::<u32>().ok());
        return match (hour, minute, second) {
            (None, _, _) => Some(day_interval(date)),
            (Some(h), None, _) => {
                let h = h?;
                Some((date.and_hms_opt(h, 0, 0)?, date.and_hms_opt(h, 59, 59)?))
            }
            (Some(h), Some(mi), None) => {
                let (h, mi) = (h?, mi?);
                Some((date.and_hms_opt(h, mi, 0)?, date.and_hms_opt(h, mi, 59)?))
            }
            (Some(h), Some(mi), Some(se)) => {
                let (h, mi, se) = (h?, mi?, se?);
                let dt = date.and_hms_opt(h, mi, se)?;
                Some((dt, dt))
            }
        };
    }
    // relative days: +N / -N
    let r = re(r"^([+-])(\d+)$", &RE_REL);
    if let Some(c) = r.captures(trimmed) {
        let n: i64 = c[2].parse().ok()?;
        let n = if &c[1] == "-" { -n } else { n };
        let date = now().date().checked_add_signed(Duration::days(n))?;
        return Some(day_interval(date));
    }
    let dt = parse_english(trimmed, us_dates)?;
    if dt.time() == NaiveTime::from_hms_opt(0, 0, 0).unwrap() {
        Some(day_interval(dt.date()))
    } else {
        Some((dt, dt))
    }
}

fn month_from_str(s: &str) -> Option<u32> {
    let s = s.to_lowercase();
    if s.len() < 3 {
        return None;
    }
    let months = [
        "january", "february", "march", "april", "may", "june", "july", "august", "september", "october",
        "november", "december",
    ];
    for (i, m) in months.iter().enumerate() {
        if m.starts_with(&s) {
            return Some(i as u32 + 1);
        }
    }
    None
}

fn weekday_from_str(s: &str, allow_abbrev: bool) -> Option<Weekday> {
    let s = s.to_lowercase();
    let days = [
        ("monday", Weekday::Mon),
        ("tuesday", Weekday::Tue),
        ("wednesday", Weekday::Wed),
        ("thursday", Weekday::Thu),
        ("friday", Weekday::Fri),
        ("saturday", Weekday::Sat),
        ("sunday", Weekday::Sun),
    ];
    for (name, wd) in days.iter() {
        if s == *name {
            return Some(*wd);
        }
        if allow_abbrev && s.len() >= 3 && s[..3] == name[..3] {
            return Some(*wd);
        }
    }
    None
}

fn parse_time(s: &str) -> Option<NaiveTime> {
    let r = re(r"^(\d{1,2}):(\d{2})(?::(\d{2}))?(?:\.(\d+))?$", &RE_TIME);
    let c = r.captures(s)?;
    let h: u32 = c[1].parse().ok()?;
    let m: u32 = c[2].parse().ok()?;
    let sec: u32 = c.get(3).map(|v| v.as_str().parse().ok()).unwrap_or(Some(0))?;
    NaiveTime::from_hms_opt(h, m, sec)
}

fn parse_english(s: &str, us_dates: bool) -> Option<NaiveDateTime> {
    let today = now();
    // full ISO with T / fractional seconds / timezone
    let r = re(
        r"^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ](\d{1,2}):(\d{2})(?::(\d{2}))?(?:\.\d+)?)?\s*(Z|[+-]\d{2}:?\d{2})?$",
        &RE_ISO_FULL,
    );
    if let Some(c) = r.captures(s) {
        let y: i32 = c[1].parse().ok()?;
        let m: u32 = c[2].parse().ok()?;
        let d: u32 = c[3].parse().ok()?;
        let date = NaiveDate::from_ymd_opt(y, m, d)?;
        let h: u32 = c.get(4).map(|v| v.as_str().parse().ok()).unwrap_or(Some(0))?;
        let mi: u32 = c.get(5).map(|v| v.as_str().parse().ok()).unwrap_or(Some(0))?;
        let se: u32 = c.get(6).map(|v| v.as_str().parse().ok()).unwrap_or(Some(0))?;
        return date.and_hms_opt(h, mi, se);
    }

    let tokens: Vec<String> = s
        .split(|c: char| c.is_whitespace() || c == ',')
        .filter(|t| !t.is_empty())
        .map(|t| t.to_string())
        .collect();
    if tokens.is_empty() {
        return None;
    }
    let lower: Vec<String> = tokens.iter().map(|t| t.to_lowercase()).collect();

    // optional trailing time
    let (date_tokens, time): (&[String], Option<NaiveTime>) = match parse_time(lower.last().unwrap()) {
        Some(t) if lower.len() > 1 => (&lower[..lower.len() - 1], Some(t)),
        _ => (&lower[..], None),
    };

    let with_time = |date: NaiveDate| -> Option<NaiveDateTime> {
        match time {
            Some(t) => Some(date.and_time(t)),
            None => date.and_hms_opt(0, 0, 0),
        }
    };

    if date_tokens.is_empty() {
        // time only: today at that time
        return with_time(today.date());
    }

    match date_tokens.len() {
        1 => {
            let w = &date_tokens[0];
            match w.as_str() {
                "today" => return with_time(today.date()),
                "yesterday" => return with_time(today.date() - Duration::days(1)),
                "tomorrow" => {
                    if time.is_some() {
                        return with_time(today.date() + Duration::days(1));
                    }
                    return Some(today + Duration::days(1));
                }
                _ => {}
            }
            // full weekday name (abbreviations are only accepted with a time or after last/next)
            if let Some(wd) = weekday_from_str(w, time.is_some()) {
                let date = next_weekday(today.date(), wd);
                return with_time(date);
            }
            // d/m[/y]
            if let Some(d) = parse_dmy(w, us_dates) {
                return with_time(d);
            }
            return None;
        }
        2 => {
            let (a, b) = (&date_tokens[0], &date_tokens[1]);
            if a == "last" || a == "next" {
                let wd = weekday_from_str(b, true)?;
                let date = if a == "last" { prev_weekday(today.date(), wd) } else { next_weekday(today.date(), wd) };
                return with_time(date);
            }
            // N units [ago]
            if let Ok(n) = a.parse::<i64>() {
                if let Some(dt) = apply_units(today, n, b, false) {
                    return Some(dt);
                }
            }
            // day month / month day
            if let Ok(d) = a.parse::<u32>() {
                if let Some(m) = month_from_str(b) {
                    let date = NaiveDate::from_ymd_opt(today.year(), m, d)?;
                    return with_time(date);
                }
            }
            if let Some(m) = month_from_str(a) {
                if let Ok(d) = b.parse::<u32>() {
                    let date = NaiveDate::from_ymd_opt(today.year(), m, d)?;
                    return with_time(date);
                }
            }
            None
        }
        3 => {
            let (a, b, c) = (&date_tokens[0], &date_tokens[1], &date_tokens[2]);
            if c == "ago" {
                if let Ok(n) = a.parse::<i64>() {
                    return apply_units(today, n, b, true);
                }
                return None;
            }
            // day month year
            if let Ok(d) = a.parse::<u32>() {
                if let Some(m) = month_from_str(b) {
                    if let Ok(y) = c.parse::<i32>() {
                        let date = NaiveDate::from_ymd_opt(y, m, d)?;
                        return with_time(date);
                    }
                }
            }
            // month day, year  (the comma was required in the original input)
            if let Some(m) = month_from_str(a) {
                if s.contains(',') {
                    if let (Ok(d), Ok(y)) = (b.parse::<u32>(), c.parse::<i32>()) {
                        let date = NaiveDate::from_ymd_opt(y, m, d)?;
                        return with_time(date);
                    }
                }
            }
            None
        }
        _ => None,
    }
}

fn parse_dmy(s: &str, us_dates: bool) -> Option<NaiveDate> {
    let r = re(r"^(\d{1,2})/(\d{1,2})(?:/(\d{2,4}))?$", &RE_DMY);
    let c = r.captures(s)?;
    let a: u32 = c[1].parse().ok()?;
    let b: u32 = c[2].parse().ok()?;
    let (d, m) = if us_dates { (b, a) } else { (a, b) };
    let y: i32 = match c.get(3) {
        Some(v) => {
            let y: i32 = v.as_str().parse().ok()?;
            if v.as_str().len() == 2 {
                2000 + y
            } else {
                y
            }
        }
        None => now().year(),
    };
    NaiveDate::from_ymd_opt(y, m, d)
}

fn apply_units(base: NaiveDateTime, n: i64, unit: &str, ago: bool) -> Option<NaiveDateTime> {
    let n = if ago { -n } else { n };
    let u = unit.trim_end_matches('s');
    match u {
        "second" | "sec" => base.checked_add_signed(Duration::seconds(n)),
        "minute" | "min" => base.checked_add_signed(Duration::minutes(n)),
        "hour" => base.checked_add_signed(Duration::hours(n)),
        "day" => base.checked_add_signed(Duration::days(n)),
        "week" => base.checked_add_signed(Duration::weeks(n)),
        "month" => add_months(base, n as i32),
        "year" => add_months(base, (n as i32) * 12),
        _ => None,
    }
}

fn add_months(base: NaiveDateTime, months: i32) -> Option<NaiveDateTime> {
    let total = base.year() * 12 + base.month0() as i32 + months;
    let y = total.div_euclid(12);
    let m = total.rem_euclid(12) as u32 + 1;
    let last = last_day_of_month(y, m)?;
    let d = base.day().min(last);
    NaiveDate::from_ymd_opt(y, m, d)?.and_hms_opt(base.hour(), base.minute(), base.second())
}

pub fn last_day_of_month(y: i32, m: u32) -> Option<u32> {
    let first_next = if m == 12 {
        NaiveDate::from_ymd_opt(y + 1, 1, 1)?
    } else {
        NaiveDate::from_ymd_opt(y, m + 1, 1)?
    };
    Some((first_next - Duration::days(1)).day())
}

fn next_weekday(from: NaiveDate, wd: Weekday) -> NaiveDate {
    let mut d = from + Duration::days(1);
    while d.weekday() != wd {
        d += Duration::days(1);
    }
    d
}

fn prev_weekday(from: NaiveDate, wd: Weekday) -> NaiveDate {
    let mut d = from - Duration::days(1);
    while d.weekday() != wd {
        d -= Duration::days(1);
    }
    d
}
