//! Typed values produced during expression evaluation.

use crate::datetime::{format_dt, parse_datetime, Interval};
use crate::util::{format_f64, parse_bool, parse_number};
use chrono::NaiveDateTime;

#[derive(Debug, Clone)]
pub enum Variant {
    Str(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    DateTime(Interval),
}

impl Variant {
    pub fn empty() -> Variant {
        Variant::Str(String::new())
    }

    pub fn from_u64(v: u64) -> Variant {
        Variant::Int(v as i64)
    }

    pub fn from_opt_u64(v: Option<u64>) -> Variant {
        match v {
            Some(v) => Variant::Int(v as i64),
            None => Variant::empty(),
        }
    }

    pub fn from_opt_bool(v: Option<bool>) -> Variant {
        match v {
            Some(v) => Variant::Bool(v),
            None => Variant::empty(),
        }
    }

    pub fn from_opt_string(v: Option<String>) -> Variant {
        match v {
            Some(v) => Variant::Str(v),
            None => Variant::empty(),
        }
    }

    pub fn from_dt(dt: NaiveDateTime) -> Variant {
        Variant::DateTime((dt, dt))
    }

    pub fn from_opt_dt(dt: Option<NaiveDateTime>) -> Variant {
        match dt {
            Some(dt) => Variant::DateTime((dt, dt)),
            None => Variant::empty(),
        }
    }

    pub fn from_f64(v: f64) -> Variant {
        Variant::Float(v)
    }

    pub fn is_empty(&self) -> bool {
        match self {
            Variant::Str(s) => s.is_empty(),
            _ => false,
        }
    }

    pub fn to_string(&self) -> String {
        match self {
            Variant::Str(s) => s.clone(),
            Variant::Int(i) => i.to_string(),
            Variant::Float(f) => format_f64(*f),
            Variant::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
            Variant::DateTime((from, _)) => format_dt(from),
        }
    }

    pub fn to_f64(&self) -> f64 {
        match self {
            Variant::Str(s) => parse_number(s).unwrap_or(0.0),
            Variant::Int(i) => *i as f64,
            Variant::Float(f) => *f,
            Variant::Bool(b) => if *b { 1.0 } else { 0.0 },
            Variant::DateTime((from, _)) => from.and_utc().timestamp() as f64,
        }
    }

    /// numeric value, None if not numeric
    pub fn to_num_opt(&self) -> Option<f64> {
        match self {
            Variant::Str(s) => parse_number(s),
            Variant::Int(i) => Some(*i as f64),
            Variant::Float(f) => Some(*f),
            Variant::Bool(_) => None,
            Variant::DateTime(_) => None,
        }
    }

    /// integer value if the value is an integer
    pub fn to_i64_opt(&self) -> Option<i64> {
        match self {
            Variant::Str(s) => s.trim().parse::<i64>().ok(),
            Variant::Int(i) => Some(*i),
            Variant::Float(f) => {
                if f.fract() == 0.0 && f.abs() < 9.2e18 {
                    Some(*f as i64)
                } else {
                    None
                }
            }
            Variant::Bool(_) => None,
            Variant::DateTime(_) => None,
        }
    }

    pub fn to_bool(&self) -> bool {
        match self {
            Variant::Str(s) => parse_bool(s),
            Variant::Int(i) => *i != 0,
            Variant::Float(f) => *f != 0.0,
            Variant::Bool(b) => *b,
            Variant::DateTime(_) => true,
        }
    }

    pub fn to_datetime(&self, us_dates: bool) -> Result<Interval, String> {
        match self {
            Variant::DateTime(i) => Ok(*i),
            other => {
                let s = other.to_string();
                parse_datetime(&s, us_dates).ok_or_else(|| format!("Can't parse datetime: {}", s))
            }
        }
    }
}
