//! Configuration file handling.

use serde::{Deserialize, Serialize};
use std::path::PathBuf;

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct Config {
    pub no_color: bool,
    pub gitignore: bool,
    pub hgignore: bool,
    pub dockerignore: bool,
    pub is_zip_archive: Vec<String>,
    pub is_archive: Vec<String>,
    pub is_audio: Vec<String>,
    pub is_book: Vec<String>,
    pub is_doc: Vec<String>,
    pub is_font: Vec<String>,
    pub is_image: Vec<String>,
    pub is_source: Vec<String>,
    pub is_video: Vec<String>,
    pub default_file_size_format: String,
    pub us_dates: bool,
    pub check_for_updates: bool,
}

fn strs(list: &[&str]) -> Vec<String> {
    list.iter().map(|s| s.to_string()).collect()
}

impl Default for Config {
    fn default() -> Config {
        Config {
            no_color: false,
            gitignore: false,
            hgignore: false,
            dockerignore: false,
            is_zip_archive: strs(&[".zip", ".jar", ".war", ".ear"]),
            is_archive: strs(&[".7z", ".bz2", ".bzip2", ".gz", ".gzip", ".lz", ".rar", ".tar", ".xz", ".zip"]),
            is_audio: strs(&[".aac", ".aiff", ".amr", ".flac", ".gsm", ".m4a", ".m4b", ".m4p", ".mp3", ".ogg", ".wav", ".wma"]),
            is_book: strs(&[".azw3", ".chm", ".djv", ".djvu", ".epub", ".fb2", ".mobi", ".pdf"]),
            is_doc: strs(&[
                ".accdb", ".doc", ".docm", ".docx", ".dot", ".dotm", ".dotx", ".mdb", ".odp", ".ods", ".odt", ".pdf",
                ".potm", ".potx", ".ppt", ".pptm", ".pptx", ".rtf", ".xlm", ".xls", ".xlsm", ".xlsx", ".xlt", ".xltm",
                ".xltx", ".xps",
            ]),
            is_font: strs(&[".eot", ".fon", ".otc", ".otf", ".ttc", ".ttf", ".woff", ".woff2"]),
            is_image: strs(&[
                ".bmp", ".exr", ".gif", ".heic", ".jpeg", ".jpg", ".jxl", ".png", ".psb", ".psd", ".svg", ".tga", ".tiff",
                ".webp",
            ]),
            is_source: strs(&[
                ".asm", ".awk", ".bas", ".c", ".cc", ".ceylon", ".clj", ".coffee", ".cpp", ".cs", ".d", ".dart", ".elm",
                ".erl", ".go", ".gradle", ".groovy", ".h", ".hh", ".hpp", ".java", ".jl", ".js", ".jsp", ".jsx", ".kt",
                ".kts", ".lua", ".nim", ".pas", ".php", ".pl", ".pm", ".py", ".rb", ".rs", ".scala", ".sol", ".swift",
                ".tcl", ".ts", ".tsx", ".vala", ".vb", ".zig",
            ]),
            is_video: strs(&[".3gp", ".avi", ".flv", ".m4p", ".m4v", ".mkv", ".mov", ".mp4", ".mpeg", ".mpg", ".webm", ".wmv"]),
            default_file_size_format: String::new(),
            us_dates: false,
            check_for_updates: false,
        }
    }
}

impl Config {
    pub fn default_path() -> Option<PathBuf> {
        let home = std::env::var_os("HOME")?;
        let mut p = PathBuf::from(home);
        p.push(".config");
        p.push("fselect");
        p.push("config.toml");
        Some(p)
    }

    /// Load the configuration. Returns the config and a flag telling whether a
    /// new default config file should be saved.
    pub fn load(custom: Option<&str>) -> Config {
        let path = match custom {
            Some(p) => PathBuf::from(p),
            None => match Config::default_path() {
                Some(p) => p,
                None => return Config::default(),
            },
        };
        if !path.exists() {
            // try next to the executable
            if custom.is_none() {
                if let Ok(exe) = std::env::current_exe() {
                    if let Some(dir) = exe.parent() {
                        let alt = dir.join("config.toml");
                        if alt.exists() {
                            if let Some(c) = Config::read(&alt) {
                                return c;
                            }
                        }
                    }
                }
                let cfg = Config::default();
                cfg.save(&path);
                return cfg;
            }
            eprintln!("Could not open config file. Using default settings.");
            let cfg = Config::default();
            if let Some(dp) = Config::default_path() {
                if !dp.exists() {
                    cfg.save(&dp);
                }
            }
            return cfg;
        }
        match Config::read(&path) {
            Some(c) => c,
            None => Config::default(),
        }
    }

    fn read(path: &PathBuf) -> Option<Config> {
        let content = match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(_) => {
                eprintln!("Could not read config file. Using default settings.");
                return None;
            }
        };
