impl Config {
    pub fn default_path() -> Option<PathBuf> {
        let home = std::env::var_os("HOME")?;
        let mut p = PathBuf::from(home);
        p.push(".config");
        p.push("fselect");
        p.push("config.toml");
        Some(p)
    }

    /// Load the configuration. Returns the config and a flag telling whether a
    /// new default config file should be saved.
    pub fn load(custom: Option<&str>) -> Config {
        let path = match custom {
            Some(p) => PathBuf::from(p),
            None => match Config::default_path() {
                Some(p) => p,
                None => return Config::default(),
            },
        };
        if !path.exists() {
            // try next to the executable
            if custom.is_none() {
                if let Ok(exe) = std::env::current_exe() {
                    if let Some(dir) = exe.parent() {
                        let alt = dir.join("config.toml");
                        if alt.exists() {
                            if let Some(c) = Config::read(&alt) {
                                return c;
                            }
                        }
                    }
                }
                let cfg = Config::default();
                cfg.save(&path);
                return cfg;
            }
            eprintln!("Could not open config file. Using default settings.");
            let cfg = Config::default();
            if let Some(dp) = Config::default_path() {
                if !dp.exists() {
                    cfg.save(&dp);
                }
            }
            return cfg;
        }
        match Config::read(&path) {
            Some(c) => c,
            None => Config::default(),
        }
    }

    fn read(path: &PathBuf) -> Option<Config> {
        let content = match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(_) => {
                eprintln!("Could not read config file. Using default settings.");
                return None;
            }
        };
        match toml::from_str::<Config>(&content) {
            Ok(c) => Some(c),
            Err(e) => {
                eprintln!("{}", e);
                None
            }
        }
    }

    pub fn save(&self, path: &PathBuf) {
        if let Some(dir) = path.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        if let Ok(s) = toml::to_string_pretty(self) {
            let _ = std::fs::write(path, s);
        }
    }
}
