//! Minimal zip central directory reader.

use chrono::{NaiveDate, NaiveDateTime};
use std::fs::File;
use std::io::{Read, Seek, SeekFrom};
use std::path::Path;

#[derive(Debug, Clone)]
pub struct ZipEntry {
    pub name: String,
    pub size: u64,
    pub is_dir: bool,
    pub mode: Option<u32>,
    pub modified: Option<NaiveDateTime>,
}

fn le16(d: &[u8], o: usize) -> u64 {
    u16::from_le_bytes([d[o], d[o + 1]]) as u64
}
fn le32(d: &[u8], o: usize) -> u64 {
    u32::from_le_bytes([d[o], d[o + 1], d[o + 2], d[o + 3]]) as u64
}

fn dos_datetime(time: u64, date: u64) -> Option<NaiveDateTime> {
    let sec = ((time & 0x1f) * 2) as u32;
    let min = ((time >> 5) & 0x3f) as u32;
    let hour = ((time >> 11) & 0x1f) as u32;
    let day = (date & 0x1f) as u32;
    let month = ((date >> 5) & 0x0f) as u32;
    let year = ((date >> 9) & 0x7f) as i32 + 1980;
    NaiveDate::from_ymd_opt(year, month, day)?.and_hms_opt(hour, min, sec.min(59))
}

pub fn list(path: &Path) -> Option<Vec<ZipEntry>> {
    let mut f = File::open(path).ok()?;
    let len = f.metadata().ok()?.len();
    if len < 22 {
        return None;
    }
