//! Information about a file system entry (or an archive entry) used during evaluation.

use crate::zip::ZipEntry;
use chrono::{Local, NaiveDateTime, TimeZone};
use std::cell::RefCell;
use std::ffi::CString;
use std::fs::{FileType, Metadata};
use std::io::Read;
use std::os::unix::fs::{FileTypeExt, MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};
use std::time::SystemTime;

#[derive(Debug, Clone)]
pub struct ArchiveEntry {
    pub archive_path: PathBuf,
    pub entry: ZipEntry,
}

#[derive(Default)]
pub struct FileCache {
    pub content: Option<Option<Vec<u8>>>,
    pub xattrs: Option<Option<Vec<String>>>,
    pub mime: Option<String>,
    pub dimensions: Option<Option<(u64, u64)>>,
    pub abspath: Option<Option<PathBuf>>,
    pub access_acl: Option<Option<Vec<AclEntry>>>,
    pub default_acl: Option<Option<Vec<AclEntry>>>,
}

pub struct FileInfo {
    pub full_path: PathBuf,
    pub rel_path: String,
    pub name: String,
    pub depth: u32,
    pub file_type: Option<FileType>,
    pub metadata: Option<Metadata>,
    pub archive: Option<ArchiveEntry>,
    pub cache: RefCell<FileCache>,
}

#[derive(Debug, Clone)]
pub struct AclEntry {
    pub tag: u16,
    pub perm: u16,
    pub id: u32,
}

pub fn system_time_to_local(t: SystemTime) -> Option<NaiveDateTime> {
    let dur = t.duration_since(SystemTime::UNIX_EPOCH).ok();
    match dur {
        Some(d) => Local.timestamp_opt(d.as_secs() as i64, 0).single().map(|dt| dt.naive_local()),
        None => {
            let d = SystemTime::UNIX_EPOCH.duration_since(t).ok()?;
            Local.timestamp_opt(-(d.as_secs() as i64), 0).single().map(|dt| dt.naive_local())
        }
    }
}

pub fn timestamp_to_local(ts: i64) -> Option<NaiveDateTime> {
    Local.timestamp_opt(ts, 0).single().map(|dt| dt.naive_local())
}

impl FileInfo {
    pub fn new(full_path: PathBuf, rel_path: String, depth: u32, file_type: Option<FileType>, follow: bool) -> FileInfo {
        let name = full_path
            .file_name()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_else(|| rel_path.clone());
        let metadata = if follow {
            std::fs::metadata(&full_path).ok()
        } else {
            std::fs::symlink_metadata(&full_path).ok()
        };
        FileInfo {
            full_path,
            rel_path,
            name,
            depth,
            file_type,
            metadata,
            archive: None,
            cache: RefCell::new(FileCache::default()),
        }
    }

    pub fn empty() -> FileInfo {
        FileInfo {
            full_path: PathBuf::new(),
            rel_path: String::new(),
            name: String::new(),
            depth: 0,
            file_type: None,
            metadata: None,
            archive: None,
            cache: RefCell::new(FileCache::default()),
        }
    }

    pub fn from_archive(archive_path: PathBuf, entry: ZipEntry) -> FileInfo {
        let rel = entry.name.clone();
        let trimmed = rel.trim_end_matches('/');
        let name = trimmed.rsplit('/').next().unwrap_or("").to_string();
        FileInfo {
            full_path: PathBuf::from(&rel),
            rel_path: rel,
            name,
            depth: 0,
            file_type: None,
            metadata: None,
            archive: Some(ArchiveEntry { archive_path, entry }),
            cache: RefCell::new(FileCache::default()),
        }
    }

    pub fn is_archive_entry(&self) -> bool {
        self.archive.is_some()
    }

    pub fn display_path(&self) -> String {
        self.full_path.to_string_lossy().to_string()
    }

    // ------------------------------------------------------------ names

    pub fn filename(&self) -> String {
        match self.name.rfind('.') {
            Some(0) | None => self.name.clone(),
            Some(idx) => self.name[..idx].to_string(),
        }
    }

    pub fn extension(&self) -> String {
        match self.name.rfind('.') {
            Some(0) | None => String::new(),
            Some(idx) => self.name[idx + 1..].to_string(),
        }
    }

    pub fn directory(&self) -> String {
        let p = self.rel_path.trim_end_matches('/');
        match p.rfind('/') {
            Some(idx) => p[..idx].to_string(),
            None => String::new(),
        }
    }

    pub fn abspath(&self) -> Option<PathBuf> {
        if self.archive.is_some() {
            return Some(PathBuf::from(&self.rel_path));
        }
        let mut cache = self.cache.borrow_mut();
        if cache.abspath.is_none() {
            cache.abspath = Some(std::fs::canonicalize(&self.full_path).ok());
        }
        cache.abspath.clone().unwrap()
    }

    pub fn absdir(&self) -> Option<PathBuf> {
        if self.archive.is_some() {
            return Some(PathBuf::from(self.directory()));
        }
        let abs = self.abspath()?;
        abs.parent().map(|p| p.to_path_buf())
    }

    // ------------------------------------------------------------ type checks

    pub fn is_dir(&self) -> Option<bool> {
        if let Some(a) = &self.archive {
            return Some(a.entry.is_dir);
        }
        self.metadata.as_ref().map(|m| m.is_dir())
    }

    pub fn is_file(&self) -> Option<bool> {
        if let Some(a) = &self.archive {
            return Some(!a.entry.is_dir);
        }
        self.metadata.as_ref().map(|m| m.is_file())
    }

    pub fn is_symlink(&self) -> Option<bool> {
        if self.archive.is_some() {
            return Some(false);
        }
        if let Some(ft) = &self.file_type {
            return Some(ft.is_symlink());
        }
        self.metadata.as_ref().map(|m| m.file_type().is_symlink())
    }

    pub fn mode(&self) -> Option<u32> {
        if let Some(a) = &self.archive {
            return Some(a.entry.mode.unwrap_or(0o100644));
        }
        self.metadata.as_ref().map(|m| m.mode())
    }

    pub fn size(&self) -> Option<u64> {
        if let Some(a) = &self.archive {
            return Some(a.entry.size);
        }
        self.metadata.as_ref().map(|m| m.len())
    }

    pub fn modified(&self) -> Option<NaiveDateTime> {
        if let Some(a) = &self.archive {
            return a.entry.modified;
        }
        self.metadata.as_ref().and_then(|m| timestamp_to_local(m.mtime()))
    }

    pub fn accessed(&self) -> Option<NaiveDateTime> {
        if self.archive.is_some() {
            return None;
        }
        self.metadata.as_ref().and_then(|m| timestamp_to_local(m.atime()))
    }

    pub fn created(&self) -> Option<NaiveDateTime> {
        if self.archive.is_some() {
            return None;
        }
        self.metadata.as_ref().and_then(|m| m.created().ok()).and_then(system_time_to_local)
    }

    pub fn is_empty(&self) -> Option<bool> {
        if let Some(a) = &self.archive {
            return Some(a.entry.size == 0);
        }
        let m = self.metadata.as_ref()?;
        if m.is_dir() {
            match std::fs::read_dir(&self.full_path) {
                Ok(mut rd) => Some(rd.next().is_none()),
                Err(_) => None,
            }
        } else {
            Some(m.len() == 0)
        }
    }

    // ------------------------------------------------------------ contents

    pub fn content(&self) -> Option<Vec<u8>> {
        if self.archive.is_some() {
            return None;
        }
        let m = self.metadata.as_ref()?;
        if !m.is_file() && !self.file_type.map(|t| t.is_symlink()).unwrap_or(false) {
            return None;
        }
        let mut cache = self.cache.borrow_mut();
        if cache.content.is_none() {
            let real = std::fs::metadata(&self.full_path).ok();
            let readable = real.map(|r| r.is_file()).unwrap_or(false);
            cache.content = Some(if readable { std::fs::read(&self.full_path).ok() } else { None });
        }
        cache.content.clone().unwrap()
    }

    pub fn head(&self, n: usize) -> Option<Vec<u8>> {
        if self.archive.is_some() {
            return None;
        }
        let real = std::fs::metadata(&self.full_path).ok()?;
        if real.is_dir() {
            return None;
        }
        if !real.is_file() {
            return None;
        }
        let mut f = std::fs::File::open(&self.full_path).ok()?;
        let mut buf = vec![0u8; n];
        let mut total = 0;
        while total < n {
            match f.read(&mut buf[total..]) {
                Ok(0) => break,
                Ok(k) => total += k,
                Err(_) => return None,
            }
        }
        buf.truncate(total);
        Some(buf)
    }

    pub fn mime(&self) -> Option<String> {
        if self.archive.is_some() {
            return None;
        }
        {
            let cache = self.cache.borrow();
            if let Some(m) = &cache.mime {
                return if m.is_empty() { None } else { Some(m.clone()) };
            }
        }
        let real = std::fs::metadata(&self.full_path).ok();
        let result = match real {
            Some(r) if r.is_dir() => Some("inode/directory".to_string()),
            Some(r) if r.is_file() => self.head(8192).map(|d| crate::mime::detect(&d)),
            _ => None,
        };
        self.cache.borrow_mut().mime = Some(result.clone().unwrap_or_default());
        result
    }

    pub fn line_count(&self) -> Option<u64> {
        if self.archive.is_some() {
            return None;
        }
        let real = std::fs::metadata(&self.full_path).ok()?;
        if !real.is_file() {
            return None;
        }
        let content = self.content()?;
        Some(content.iter().filter(|&&b| b == b'\n').count() as u64)
    }

    pub fn is_shebang(&self) -> Option<bool> {
        if self.archive.is_some() {
            return Some(false);
        }
        match self.head(2) {
            Some(h) => Some(h.starts_with(b"#!")),
            None => Some(false),
        }
    }

    pub fn dimensions(&self) -> Option<(u64, u64)> {
        if self.archive.is_some() {
            return None;
        }
        let mut cache = self.cache.borrow_mut();
        if cache.dimensions.is_none() {
            let real = std::fs::metadata(&self.full_path).ok();
            let d = match real {
                Some(r) if r.is_file() => crate::imagesize::dimensions(&self.full_path),
                _ => None,
            };
            cache.dimensions = Some(d);
        }
        cache.dimensions.unwrap()
    }

    pub fn hash(&self, kind: &str) -> Option<String> {
        let content = self.content()?;
        let bytes: Vec<u8> = match kind {
            "sha1" => {
                let mut h = crate::sha1::Sha1::new();
                h.update(&content);
                h.finalize().to_vec()
            }
            "sha256" => {
                use sha2::Digest;
                let mut h = sha2::Sha256::new();
                h.update(&content);
                h.finalize().to_vec()
            }
            "sha512" => {
                use sha2::Digest;
                let mut h = sha2::Sha512::new();
                h.update(&content);
                h.finalize().to_vec()
            }
            "sha3" => {
                let mut h = crate::sha3::Sha3_512::new();
                h.update(&content);
                h.finalize().to_vec()
            }
            _ => return None,
        };
        Some(bytes.iter().map(|b| format!("{:02x}", b)).collect())
    }

    // ------------------------------------------------------------ xattrs

    pub fn xattr_names(&self) -> Option<Vec<String>> {
        if self.archive.is_some() {
            return None;
        }
        let mut cache = self.cache.borrow_mut();
        if cache.xattrs.is_none() {
            cache.xattrs = Some(list_xattrs(&self.full_path));
        }
        cache.xattrs.clone().unwrap()
    }

    pub fn xattr(&self, name: &str) -> Option<Vec<u8>> {
        if self.archive.is_some() {
            return None;
        }
        get_xattr(&self.full_path, name)
    }

    pub fn acl(&self, default: bool) -> Option<Vec<AclEntry>> {
        if self.archive.is_some() {
            return None;
        }
        let mut cache = self.cache.borrow_mut();
        let slot = if default { &mut cache.default_acl } else { &mut cache.access_acl };
        if slot.is_none() {
            let attr = if default { "system.posix_acl_default" } else { "system.posix_acl_access" };
            let parsed = get_xattr(&self.full_path, attr).and_then(|d| parse_acl(&d));
            *slot = Some(parsed);
        }
        slot.clone().unwrap()
    }

    pub fn capabilities(&self) -> Option<Vec<String>> {
        if self.archive.is_some() {
            return None;
        }
        let data = get_xattr(&self.full_path, "security.capability")?;
        parse_capabilities(&data)
    }
}

// ---------------------------------------------------------------- helpers

pub fn list_xattrs(path: &Path) -> Option<Vec<String>> {
    use std::os::unix::ffi::OsStrExt;
    let cpath = CString::new(path.as_os_str().as_bytes()).ok()?;
    unsafe {
        let size = libc::listxattr(cpath.as_ptr(), std::ptr::null_mut(), 0);
        if size < 0 {
            return None;
        }
        if size == 0 {
            return Some(vec![]);
        }
        let mut buf = vec![0u8; size as usize];
        let size = libc::listxattr(cpath.as_ptr(), buf.as_mut_ptr() as *mut libc::c_char, buf.len());
        if size < 0 {
            return None;
        }
        buf.truncate(size as usize);
        let names = buf
            .split(|&b| b == 0)
            .filter(|s| !s.is_empty())
            .map(|s| String::from_utf8_lossy(s).to_string())
            .collect();
        Some(names)
    }
}

pub fn get_xattr(path: &Path, name: &str) -> Option<Vec<u8>> {
    use std::os::unix::ffi::OsStrExt;
    let cpath = CString::new(path.as_os_str().as_bytes()).ok()?;
    let cname = CString::new(name).ok()?;
    unsafe {
        let size = libc::getxattr(cpath.as_ptr(), cname.as_ptr(), std::ptr::null_mut(), 0);
        if size < 0 {
            return None;
        }
        let mut buf = vec![0u8; size as usize];
        if size > 0 {
            let size2 = libc::getxattr(cpath.as_ptr(), cname.as_ptr(), buf.as_mut_ptr() as *mut libc::c_void, buf.len());
            if size2 < 0 {
                return None;
            }
            buf.truncate(size2 as usize);
        }
        Some(buf)
    }
}

pub const ACL_USER_OBJ: u16 = 0x01;
pub const ACL_USER: u16 = 0x02;
pub const ACL_GROUP_OBJ: u16 = 0x04;
pub const ACL_GROUP: u16 = 0x08;
pub const ACL_MASK: u16 = 0x10;
pub const ACL_OTHER: u16 = 0x20;

fn parse_acl(data: &[u8]) -> Option<Vec<AclEntry>> {
    if data.len() < 4 {
        return None;
    }
    let version = u32::from_le_bytes([data[0], data[1], data[2], data[3]]);
    if version != 2 {
        return None;
    }
    let mut entries = vec![];
    let mut p = 4;
    while p + 8 <= data.len() {
        let tag = u16::from_le_bytes([data[p], data[p + 1]]);
        let perm = u16::from_le_bytes([data[p + 2], data[p + 3]]);
        let id = u32::from_le_bytes([data[p + 4], data[p + 5], data[p + 6], data[p + 7]]);
        entries.push(AclEntry { tag, perm, id });
        p += 8;
    }
    Some(entries)
}

pub fn acl_perm_string(perm: u16) -> String {
    let mut s = String::new();
    s.push(if perm & 4 != 0 { 'r' } else { '-' });
    s.push(if perm & 2 != 0 { 'w' } else { '-' });
    s.push(if perm & 1 != 0 { 'x' } else { '-' });
    s
}

pub fn acl_entry_string(e: &AclEntry) -> String {
    let perms = acl_perm_string(e.perm);
    match e.tag {
        ACL_USER_OBJ => format!("user::{}", perms),
        ACL_USER => format!("user:{}:{}", user_name(e.id).unwrap_or_else(|| e.id.to_string()), perms),
        ACL_GROUP_OBJ => format!("group::{}", perms),
        ACL_GROUP => format!("group:{}:{}", group_name(e.id).unwrap_or_else(|| e.id.to_string()), perms),
        ACL_MASK => format!("mask::{}", perms),
        ACL_OTHER => format!("other::{}", perms),
        _ => format!("unknown::{}", perms),
    }
}

pub fn acl_is_extended(entries: &[AclEntry]) -> bool {
    entries.iter().any(|e| matches!(e.tag, ACL_USER | ACL_GROUP | ACL_MASK))
}

const CAP_NAMES: [&str; 41] = [
    "cap_chown", "cap_dac_override", "cap_dac_read_search", "cap_fowner", "cap_fsetid", "cap_kill", "cap_setgid",
    "cap_setuid", "cap_setpcap", "cap_linux_immutable", "cap_net_bind_service", "cap_net_broadcast", "cap_net_admin",
    "cap_net_raw", "cap_ipc_lock", "cap_ipc_owner", "cap_sys_module", "cap_sys_rawio", "cap_sys_chroot", "cap_sys_ptrace",
    "cap_sys_pacct", "cap_sys_admin", "cap_sys_boot", "cap_sys_nice", "cap_sys_resource", "cap_sys_time",
    "cap_sys_tty_config", "cap_mknod", "cap_lease", "cap_audit_write", "cap_audit_control", "cap_setfcap",
    "cap_mac_override", "cap_mac_admin", "cap_syslog", "cap_wake_alarm", "cap_block_suspend", "cap_audit_read",
    "cap_perfmon", "cap_bpf", "cap_checkpoint_restore",
];

fn parse_capabilities(data: &[u8]) -> Option<Vec<String>> {
    if data.len() < 12 {
        return None;
    }
    let le32 = |o: usize| u32::from_le_bytes([data[o], data[o + 1], data[o + 2], data[o + 3]]);
    let magic = le32(0);
    let rev = magic & 0xff000000;
    let (perm_lo, inh_lo, perm_hi, inh_hi) = match rev {
        0x01000000 => (le32(4), le32(8), 0, 0),
        0x02000000 | 0x03000000 => {
            if data.len() < 20 {
                return None;
            }
            (le32(4), le32(8), le32(12), le32(16))
        }
        _ => return None,
    };
    let permitted = (perm_hi as u64) << 32 | perm_lo as u64;
    let inheritable = (inh_hi as u64) << 32 | inh_lo as u64;
    let effective = magic & 1 != 0;
    let mut caps = vec![];
    for i in 0..64 {
        let bit = 1u64 << i;
        if permitted & bit != 0 || inheritable & bit != 0 {
            let name = if i < CAP_NAMES.len() { CAP_NAMES[i].to_string() } else { format!("{}", i) };
            let mut flags = String::new();
            if effective && permitted & bit != 0 {
                flags.push('e');
            }
            if inheritable & bit != 0 {
                flags.push('i');
            }
            if permitted & bit != 0 {
                flags.push('p');
            }
            caps.push(format!("{}={}", name, flags));
        }
    }
    Some(caps)
}

pub fn user_name(uid: u32) -> Option<String> {
    unsafe {
        let pw = libc::getpwuid(uid);
        if pw.is_null() {
            return None;
        }
        let name = std::ffi::CStr::from_ptr((*pw).pw_name);
        Some(name.to_string_lossy().to_string())
    }
}

pub fn group_name(gid: u32) -> Option<String> {
    unsafe {
        let gr = libc::getgrgid(gid);
        if gr.is_null() {
            return None;
        }
        let name = std::ffi::CStr::from_ptr((*gr).gr_name);
        Some(name.to_string_lossy().to_string())
    }
}

pub fn uid_by_name(name: &str) -> Option<u32> {
    let c = CString::new(name).ok()?;
    unsafe {
        let pw = libc::getpwnam(c.as_ptr());
        if pw.is_null() {
            return None;
        }
        Some((*pw).pw_uid)
    }
}

pub fn gid_by_name(name: &str) -> Option<u32> {
    let c = CString::new(name).ok()?;
    unsafe {
        let gr = libc::getgrnam(c.as_ptr());
        if gr.is_null() {
            return None;
        }
        Some((*gr).gr_gid)
    }
}

pub fn mode_string(mode: u32) -> String {
    let mut s = String::with_capacity(10);
    let ft = mode & libc::S_IFMT;
    s.push(match ft {
        libc::S_IFDIR => 'd',
        libc::S_IFLNK => 'l',
        libc::S_IFIFO => 'p',
        libc::S_IFSOCK => 's',
        libc::S_IFCHR => 'c',
        libc::S_IFBLK => 'b',
        _ => '-',
    });
    s.push(if mode & 0o400 != 0 { 'r' } else { '-' });
    s.push(if mode & 0o200 != 0 { 'w' } else { '-' });
    s.push(match (mode & 0o100 != 0, mode & 0o4000 != 0) {
        (true, true) => 's',
        (false, true) => 'S',
        (true, false) => 'x',
        (false, false) => '-',
    });
    s.push(if mode & 0o040 != 0 { 'r' } else { '-' });
    s.push(if mode & 0o020 != 0 { 'w' } else { '-' });
    s.push(match (mode & 0o010 != 0, mode & 0o2000 != 0) {
        (true, true) => 's',
        (false, true) => 'S',
        (true, false) => 'x',
        (false, false) => '-',
    });
    s.push(if mode & 0o004 != 0 { 'r' } else { '-' });
    s.push(if mode & 0o002 != 0 { 'w' } else { '-' });
    s.push(match (mode & 0o001 != 0, mode & 0o1000 != 0) {
        (true, true) => 't',
        (false, true) => 'T',
        (true, false) => 'x',
        (false, false) => '-',
    });
    s
}

pub fn metadata_mode(m: &Metadata) -> u32 {
    m.permissions().mode()
}
