pub type EvalResult = Result<Variant, String>;

pub struct Ctx<'a> {
    pub config: &'a Config,
    /// values of the aggregate functions for the current output row
    pub aggregates: Option<&'a HashMap<String, Variant>>,
    /// outer file for correlated subqueries: (alias, file)
    pub outer: Vec<(String, &'a FileInfo)>,
    /// hook to run subqueries
    pub subquery_runner: Option<&'a dyn Fn(&Query, &[(String, &FileInfo)]) -> Vec<Vec<String>>>,
}

impl<'a> Ctx<'a> {
    pub fn new(config: &'a Config) -> Ctx<'a> {
        Ctx { config, aggregates: None, outer: vec![], subquery_runner: None }
    }
}

fn empty() -> EvalResult {
    Ok(Variant::empty())
}

fn ext_matches(file: &FileInfo, list: &[String]) -> bool {
    let lower = file.name.to_lowercase();
    list.iter().any(|e| lower.ends_with(&e.to_lowercase()))
}

pub fn eval(expr: &Expr, file: &FileInfo, ctx: &Ctx) -> EvalResult {
    match expr {
        Expr::Field(field, alias) => {
            if let Some(a) = alias {
                if let Some((_, outer)) = ctx.outer.iter().find(|(n, _)| n == a) {
                    return eval_field(*field, outer, ctx);
                }
            }
            eval_field(*field, file, ctx)
        }
        Expr::Literal(s) => Ok(Variant::Str(s.clone())),
        Expr::Function(func, args) => eval_function(*func, args, expr, file, ctx),
        Expr::Arith(l, op, r) => {
            let lv = eval(l, file, ctx)?.to_f64();
            let rv = eval(r, file, ctx)?.to_f64();
            let res = match op {
                ArithOp::Add => lv + rv,
                ArithOp::Subtract => lv - rv,
                ArithOp::Multiply => lv * rv,
                ArithOp::Divide => {
                    if rv == 0.0 {
                        return Err("Division by zero".to_string());
                    }
                    lv / rv
                }
                ArithOp::Modulo => {
                    if rv == 0.0 {
                        return Err("Division by zero".to_string());
                    }
                    lv % rv
                }
            };
            Ok(Variant::Float(res))
        }
        _ => Ok(Variant::Bool(eval_bool(expr, file, ctx)?)),
    }
}

/// Evaluate a condition.
pub fn eval_bool(expr: &Expr, file: &FileInfo, ctx: &Ctx) -> Result<bool, String> {
    match expr {
        Expr::And(l, r) => Ok(eval_bool(l, file, ctx)? && eval_bool(r, file, ctx)?),
        Expr::Or(l, r) => Ok(eval_bool(l, file, ctx)? || eval_bool(r, file, ctx)?),
        Expr::Not(e) => Ok(!eval_bool(e, file, ctx)?),
        Expr::Compare(l, op, r) => compare(l, *op, r, file, ctx),
        Expr::Between(l, a, b, negated) => {
            let lv = eval(l, file, ctx)?;
            let av = eval(a, file, ctx)?;
            let bv = eval(b, file, ctx)?;
            let res = match l.kind() {
                FieldKind::Num | FieldKind::Bool => {
                    let v = lv.to_f64();
                    v >= av.to_f64() && v <= bv.to_f64()
                }
                FieldKind::DateTime => {
                    let (from, _) = lv.to_datetime(ctx.config.us_dates)?;
                    let (afrom, _) = av.to_datetime(ctx.config.us_dates)?;
                    let (_, bto) = bv.to_datetime(ctx.config.us_dates)?;
                    from >= afrom && from <= bto
                }
                FieldKind::Str => {
                    let v = lv.to_string();
                    v >= av.to_string() && v <= bv.to_string()
                }
            };
            Ok(res != *negated)
        }
        Expr::InList(l, list, negated) => {
            let lv = eval(l, file, ctx)?;
            let mut found = false;
            match l.kind() {
                FieldKind::DateTime => {
                    return Err("Can't parse datetime: ".to_string());
                }
                FieldKind::Num => {
                    let v = lv.to_f64();
                    for item in list {
                        if eval(item, file, ctx)?.to_f64() == v {
                            found = true;
                            break;
                        }
                    }
                }
                FieldKind::Bool => {
                    let v = lv.to_bool();
                    for item in list {
                        if eval(item, file, ctx)?.to_bool() == v {
                            found = true;
                            break;
                        }
                    }
                }
                FieldKind::Str => {
                    let v = lv.to_string();
                    for item in list {
                        if eval(item, file, ctx)?.to_string() == v {
                            found = true;
                            break;
                        }
                    }
                }
            }
            Ok(found != *negated)
        }
        Expr::InSubquery(l, q, negated) => {
            let lv = eval(l, file, ctx)?.to_string();
            let rows = run_subquery(q, file, ctx);
            let found = rows.iter().any(|row| row.first().map(|v| v == &lv).unwrap_or(false));
            Ok(found != *negated)
        }
        Expr::Exists(q, negated) => {
            let rows = run_subquery(q, file, ctx);
            Ok(!rows.is_empty() != *negated)
        }
        Expr::Field(f, _) => {
            if f.is_boolean() {
                Ok(eval(expr, file, ctx)?.to_bool())
            } else {
                Ok(false)
            }
        }
        Expr::Function(f, _, ..) => {
            if f.kind() == FieldKind::Bool {
                Ok(eval(expr, file, ctx)?.to_bool())
            } else {
                Ok(false)
            }
        }
        _ => Ok(false),
    }
}

fn run_subquery(q: &Query, file: &FileInfo, ctx: &Ctx) -> Vec<Vec<String>> {
    match ctx.subquery_runner {
        Some(runner) => {
            let mut outer: Vec<(String, &FileInfo)> = ctx.outer.clone();
            // bind the current file to every alias of the parent query roots
            for (alias, _) in &ctx.outer {
                let _ = alias;
            }
            if let Some(alias) = &ctx_alias(ctx) {
                outer.push((alias.clone(), file));
            }
            runner(q, &outer)
        }
        None => vec![],
    }
}

