fn compare(l: &Expr, op: CmpOp, r: &Expr, file: &FileInfo, ctx: &Ctx) -> Result<bool, String> {
    let lv = eval(l, file, ctx)?;
    let rv = eval(r, file, ctx)?;
    match l.kind() {
        FieldKind::Num => {
            let a = lv.to_f64();
            let b = rv.to_f64();
            Ok(match op {
                CmpOp::Eq | CmpOp::Eeq => a == b,
                CmpOp::Ne | CmpOp::Ene => a != b,
                CmpOp::Gt => a > b,
                CmpOp::Gte => a >= b,
                CmpOp::Lt => a < b,
                CmpOp::Lte => a <= b,
                CmpOp::Rx | CmpOp::NotRx | CmpOp::Like | CmpOp::NotLike => false,
            })
        }
        FieldKind::Bool => {
            let a = lv.to_bool();
            let b = rv.to_bool();
            Ok(match op {
                CmpOp::Eq | CmpOp::Eeq => a == b,
                CmpOp::Ne | CmpOp::Ene => a != b,
                CmpOp::Gt => a & !b,
                CmpOp::Gte => a >= b,
                CmpOp::Lt => !a & b,
                CmpOp::Lte => a <= b,
                CmpOp::Rx | CmpOp::NotRx | CmpOp::Like | CmpOp::NotLike => false,
            })
        }
        FieldKind::DateTime => {
            let (rfrom, rto) = rv.to_datetime(ctx.config.us_dates)?;
            let (from, _) = match lv {
                Variant::DateTime(i) => i,
                Variant::Str(ref s) if s.is_empty() => return Ok(false),
                other => other.to_datetime(ctx.config.us_dates)?,
            };
            Ok(match op {
                CmpOp::Eq | CmpOp::Eeq => from >= rfrom && from <= rto,
                CmpOp::Ne | CmpOp::Ene => !(from >= rfrom && from <= rto),
                CmpOp::Gt => from > rto,
                CmpOp::Gte => from >= rfrom,
                CmpOp::Lt => from < rfrom,
                CmpOp::Lte => from <= rto,
                CmpOp::Rx | CmpOp::NotRx | CmpOp::Like | CmpOp::NotLike => false,
            })
        }
        FieldKind::Str => {
            let a = lv.to_string();
            let b = rv.to_string();
            Ok(match op {
                CmpOp::Eq | CmpOp::Ne => {
                    let res = if is_glob(&b) {
                        let re = glob_to_regex(&b)?;
                        re.is_match(&a)
                    } else {
                        a == b
                    };
                    if op == CmpOp::Eq { res } else { !res }
                }
                CmpOp::Eeq => a == b,
                CmpOp::Ene => a != b,
                CmpOp::Gt => a > b,
                CmpOp::Gte => a >= b,
                CmpOp::Lt => a < b,
                CmpOp::Lte => a <= b,
                CmpOp::Rx | CmpOp::NotRx => {
                    let re = compile_regex(&b)?;
                    let res = re.is_match(&a);
                    if op == CmpOp::Rx { res } else { !res }
                }
                CmpOp::Like | CmpOp::NotLike => {
                    let re = like_to_regex(&b)?;
                    let res = re.is_match(&a);
                    if op == CmpOp::Like { res } else { !res }
                }
            })
        }
    }
}

