fn arg_str(args: &[Expr], i: usize, file: &FileInfo, ctx: &Ctx) -> Result<String, String> {
    match args.get(i) {
        Some(e) => Ok(eval(e, file, ctx)?.to_string()),
        None => Ok(String::new()),
    }
}

fn arg_var(args: &[Expr], i: usize, file: &FileInfo, ctx: &Ctx) -> Result<Option<Variant>, String> {
    match args.get(i) {
        Some(e) => Ok(Some(eval(e, file, ctx)?)),
        None => Ok(None),
    }
}

fn num_or_empty(v: Option<f64>) -> Variant {
    match v {
        Some(v) => Variant::Float(v),
        None => Variant::empty(),
    }
}

fn eval_function(func: Function, args: &[Expr], expr: &Expr, file: &FileInfo, ctx: &Ctx) -> EvalResult {
    if func.is_aggregate() {
        if let Some(aggs) = ctx.aggregates {
            let key = expr.to_key().to_lowercase();
            return Ok(aggs.get(&key).cloned().unwrap_or_else(Variant::empty));
        }
        // when evaluated for a single file, return the value of the argument
        return match args.first() {
            Some(a) => eval(a, file, ctx),
            None => empty(),
        };
    }
    match func {
        Function::Lower => Ok(Variant::Str(arg_str(args, 0, file, ctx)?.to_lowercase())),
        Function::Upper => Ok(Variant::Str(arg_str(args, 0, file, ctx)?.to_uppercase())),
        Function::InitCap => {
            let s = arg_str(args, 0, file, ctx)?;
            let mut out = String::new();
            let mut start = true;
            for c in s.chars() {
                if c.is_alphanumeric() {
                    if start {
                        out.extend(c.to_uppercase());
                        start = false;
                    } else {
                        out.extend(c.to_lowercase());
                    }
                } else {
                    out.push(c);
                    start = true;
                }
            }
            Ok(Variant::Str(out))
        }
        Function::Length => Ok(Variant::Int(arg_str(args, 0, file, ctx)?.chars().count() as i64)),
        Function::ToBase64 => {
            use base64::Engine;
            let s = arg_str(args, 0, file, ctx)?;
            Ok(Variant::Str(base64::engine::general_purpose::STANDARD.encode(s.as_bytes())))
        }
        Function::FromBase64 => {
            use base64::Engine;
            let s = arg_str(args, 0, file, ctx)?;
            let decoded = base64::engine::general_purpose::STANDARD
                .decode(s.as_bytes())
                .or_else(|_| base64::engine::general_purpose::STANDARD_NO_PAD.decode(s.as_bytes()));
            match decoded {
                Ok(bytes) => Ok(Variant::Str(String::from_utf8_lossy(&bytes).to_string())),
                Err(_) => empty(),
            }
        }
        Function::Concat => {
            let mut out = String::new();
            for a in args {
                out.push_str(&eval(a, file, ctx)?.to_string());
            }
            Ok(Variant::Str(out))
        }
        Function::ConcatWs => {
            if args.len() < 2 {
                return empty();
            }
            let sep = eval(&args[0], file, ctx)?.to_string();
            let mut parts = vec![];
            for a in &args[1..] {
                parts.push(eval(a, file, ctx)?.to_string());
            }
            Ok(Variant::Str(parts.join(&sep)))
        }
        Function::Locate => {
            if args.len() < 2 {
                return Err("LOCATE requires a search substring argument".to_string());
            }
            let s = arg_str(args, 0, file, ctx)?;
            let sub = arg_str(args, 1, file, ctx)?;
            let mut pos: i64 = 1;
            if args.len() > 2 {
                let p = arg_str(args, 2, file, ctx)?;
                pos = p
                    .parse::<i64>()
                    .map_err(|_| format!("Could not parse position argument of LOCATE function: {}", p))?;
            }
            let chars: Vec<char> = s.chars().collect();
            let start = if pos < 1 { 0 } else { (pos - 1) as usize };
            if start > chars.len() {
                return Ok(Variant::Int(0));
            }
            let hay: String = chars[start..].iter().collect();
            match hay.find(&sub) {
                Some(byte_idx) => {
                    let char_idx = hay[..byte_idx].chars().count();
                    Ok(Variant::Int((start + char_idx + 1) as i64))
                }
                None => Ok(Variant::Int(0)),
            }
        }
        Function::Substring => {
            let s = arg_str(args, 0, file, ctx)?;
            let chars: Vec<char> = s.chars().collect();
            let mut pos: i64 = 1;
            if args.len() > 1 {
                let p = arg_str(args, 1, file, ctx)?;
                pos = p
                    .parse::<i64>()
                    .map_err(|_| format!("Could not parse position argument of SUBSTRING function: {}", p))?;
            }
            let len: Option<usize> = if args.len() > 2 {
                let l = arg_str(args, 2, file, ctx)?;
                Some(
                    l.parse::<usize>()
                        .map_err(|_| format!("Could not parse length argument of SUBSTRING function: {}", l))?,
                )
            } else {
                None
            };
            let start: usize = if pos > 0 {
                (pos - 1) as usize
            } else if pos == 0 {
                0
            } else {
                let back = (-pos) as usize;
                if back > chars.len() { 0 } else { chars.len() - back }
            };
            if start >= chars.len() {
                return Ok(Variant::Str(String::new()));
            }
            let end = match len {
                Some(l) => (start + l).min(chars.len()),
                None => chars.len(),
            };
            Ok(Variant::Str(chars[start..end].iter().collect()))
        }
        Function::Replace => {
            if args.len() < 3 {
                return Err("REPLACE requires two arguments: search string and replacement string".to_string());
            }
            let s = arg_str(args, 0, file, ctx)?;
            let from = arg_str(args, 1, file, ctx)?;
            let to = arg_str(args, 2, file, ctx)?;
            if from.is_empty() {
                return Ok(Variant::Str(s));
            }
            Ok(Variant::Str(s.replace(&from, &to)))
        }
        Function::Trim => Ok(Variant::Str(arg_str(args, 0, file, ctx)?.trim().to_string())),
        Function::LTrim => Ok(Variant::Str(arg_str(args, 0, file, ctx)?.trim_start().to_string())),
        Function::RTrim => Ok(Variant::Str(arg_str(args, 0, file, ctx)?.trim_end().to_string())),
        Function::ContainsJapanese => {
            let s = arg_str(args, 0, file, ctx)?;
            Ok(Variant::Bool(s.chars().any(|c| is_hiragana(c) || is_katakana(c) || is_kanji(c))))
        }
        Function::ContainsHiragana => Ok(Variant::Bool(arg_str(args, 0, file, ctx)?.chars().any(is_hiragana))),
        Function::ContainsKatakana => Ok(Variant::Bool(arg_str(args, 0, file, ctx)?.chars().any(is_katakana))),
        Function::ContainsKana => {
            let s = arg_str(args, 0, file, ctx)?;
            Ok(Variant::Bool(s.chars().any(|c| is_hiragana(c) || is_katakana(c))))
        }
        Function::ContainsKanji => Ok(Variant::Bool(arg_str(args, 0, file, ctx)?.chars().any(is_kanji))),
        Function::ContainsGreek => Ok(Variant::Bool(arg_str(args, 0, file, ctx)?.chars().any(is_greek))),
        Function::Bin | Function::Hex | Function::Oct => {
            let v = match arg_var(args, 0, file, ctx)? {
                Some(v) => v,
                None => return empty(),
            };
            match v.to_i64_opt() {
                Some(n) => Ok(Variant::Str(match func {
                    Function::Bin => format!("{:b}", n),
                    Function::Hex => format!("{:x}", n),
                    _ => format!("{:o}", n),
                })),
                None => empty(),
            }
        }
        Function::Abs => {
            let v = arg_var(args, 0, file, ctx)?.and_then(|v| v.to_num_opt());
            Ok(num_or_empty(v.map(|x| x.abs())))
        }
        Function::Power => {
            let base = match arg_var(args, 0, file, ctx)?.and_then(|v| v.to_num_opt()) {
                Some(b) => b,
                None => return empty(),
            };
            let exp = if args.len() > 1 {
                let e = arg_str(args, 1, file, ctx)?;
                e.trim()
                    .parse::<f64>()
                    .map_err(|_| format!("Could not parse exponent argument of POWER function: {}", e))?
            } else {
                1.0
            };
            let res = base.powf(exp);
            if !res.is_finite() {
                return Err(format!(
                    "POWER({}, {}) produces a non-finite result",
                    format_f64(base),
                    format_f64(exp)
                ));
            }
            Ok(Variant::Float(res))
        }
        Function::Sqrt => {
            let v = match arg_var(args, 0, file, ctx)?.and_then(|v| v.to_num_opt()) {
                Some(v) => v,
                None => return empty(),
            };
            if v < 0.0 {
                return Err(format!("SQRT of a negative number: {}", format_f64(v)));
            }
            Ok(Variant::Float(v.sqrt()))
        }
        Function::Log => {
            let v = match arg_var(args, 0, file, ctx)?.and_then(|v| v.to_num_opt()) {
                Some(v) => v,
                None => return empty(),
            };
            if v <= 0.0 {
                return Err(format!("LOG of a non-positive number: {}", format_f64(v)));
            }
            if args.len() > 1 {
                let b = arg_str(args, 1, file, ctx)?;
                let base = b
                    .trim()
                    .parse::<f64>()
                    .map_err(|_| format!("Could not parse base argument of LOG function: {}", b))?;
                if base <= 0.0 || base == 1.0 {
                    return Err(format!("LOG with invalid base: {}", format_f64(base)));
                }
                return Ok(Variant::Float(v.ln() / base.ln()));
            }
            Ok(Variant::Float(v.log10()))
        }
        Function::Ln => {
            let v = match arg_var(args, 0, file, ctx)?.and_then(|v| v.to_num_opt()) {
                Some(v) => v,
                None => return empty(),
            };
            if v <= 0.0 {
                return Err(format!("LN of a non-positive number: {}", format_f64(v)));
            }
            Ok(Variant::Float(v.ln()))
        }
        Function::Exp => {
            let v = match arg_var(args, 0, file, ctx)?.and_then(|v| v.to_num_opt()) {
                Some(v) => v,
                None => return empty(),
            };
            let r = v.exp();
            if !r.is_finite() {
                return Err(format!("EXP({}) overflows to infinity", format_f64(v)));
            }
            Ok(Variant::Float(r))
        }
        Function::Least | Function::Greatest => {
            let mut best: Option<f64> = None;
            for a in args {
                if let Some(v) = eval(a, file, ctx)?.to_num_opt() {
                    best = Some(match best {
                        None => v,
                        Some(b) => {
                            if func == Function::Least { b.min(v) } else { b.max(v) }
                        }
                    });
                }
            }
            Ok(num_or_empty(best))
        }
        Function::Pi => Ok(Variant::Float(std::f64::consts::PI)),
        Function::Floor => {
            let v = arg_var(args, 0, file, ctx)?.and_then(|v| v.to_num_opt());
            Ok(num_or_empty(v.map(|x| x.floor())))
        }
        Function::Ceil => {
            let v = arg_var(args, 0, file, ctx)?.and_then(|v| v.to_num_opt());
            Ok(num_or_empty(v.map(|x| x.ceil())))
        }
        Function::Round => {
            let v = match arg_var(args, 0, file, ctx)?.and_then(|v| v.to_num_opt()) {
                Some(v) => v,
                None => return empty(),
            };
            if args.len() > 1 {
                let p = arg_str(args, 1, file, ctx)?;
                let prec = p
                    .trim()
                    .parse::<i32>()
                    .map_err(|_| format!("Could not parse precision argument of ROUND function: {}", p))?;
                let m = 10f64.powi(prec);
                let r = (v * m).round() / m;
                if r.is_finite() {
                    return Ok(Variant::Float(r));
                }
                return Ok(Variant::Float(v));
            }
            Ok(Variant::Float(v.round()))
        }
        Function::Random => {
            use rand::Rng;
            let mut rng = rand::thread_rng();
            let mut nums: Vec<i64> = vec![];
            for a in args {
                let s = eval(a, file, ctx)?.to_string();
                if s.is_empty() {
                    continue;
                }
                let n = s
                    .trim()
                    .parse::<i64>()
                    .map_err(|_| format!("Could not parse an argument of RANDOM function: {}", s))?;
                nums.push(n);
            }
            match nums.len() {
                0 => Ok(Variant::Int(rng.gen::<i64>().abs())),
                1 => {
                    let (a, b) = if nums[0] >= 0 { (0, nums[0]) } else { (nums[0], 0) };
                    Ok(Variant::Int(rng.gen_range(a..=b)))
                }
                _ => {
                    let (a, b) = if nums[0] <= nums[1] { (nums[0], nums[1]) } else { (nums[1], nums[0]) };
                    Ok(Variant::Int(rng.gen_range(a..=b)))
                }
            }
        }
        Function::CurrentDate => {
            let d = Local::now().naive_local().date();
            Ok(Variant::Str(d.format("%Y-%m-%d").to_string()))
        }
        Function::CurrentTime => Ok(Variant::Str(Local::now().naive_local().format("%H:%M:%S").to_string())),
        Function::CurrentTimestamp => Ok(Variant::from_dt(Local::now().naive_local())),
        Function::Day | Function::Month | Function::Year | Function::DayOfWeek | Function::DayName | Function::DayOfYear => {
            let v = match arg_var(args, 0, file, ctx)? {
                Some(v) => v,
                None => return empty(),
            };
            if v.is_empty() {
                return empty();
            }
            let (dt, _) = match v.to_datetime(ctx.config.us_dates) {
                Ok(i) => i,
                Err(_) => return empty(),
            };
            Ok(match func {
                Function::Day => Variant::Int(dt.day() as i64),
                Function::Month => Variant::Int(dt.month() as i64),
                Function::Year => Variant::Int(dt.year() as i64),
                Function::DayOfWeek => Variant::Int(dt.weekday().number_from_sunday() as i64),
                Function::DayName => Variant::Str(dt.weekday().to_string_full()),
                _ => Variant::Int(dt.ordinal() as i64),
            })
        }
        Function::DateAdd | Function::DateSub => {
            if args.len() < 2 {
                let name = if func == Function::DateAdd { "DATE_ADD" } else { "DATE_SUB" };
                return Err(format!("{} requires a second argument (number of days)", name));
            }
            let v = eval(&args[0], file, ctx)?;
            if v.is_empty() {
                return empty();
            }
            let (dt, _) = match v.to_datetime(ctx.config.us_dates) {
                Ok(i) => i,
                Err(_) => return empty(),
            };
            let n = arg_str(args, 1, file, ctx)?;
            let days = match n.trim().parse::<i64>() {
                Ok(d) => d,
                Err(_) => return empty(),
            };
            let days = if func == Function::DateSub { -days } else { days };
            match dt.checked_add_signed(Duration::days(days)) {
                Some(r) => Ok(Variant::from_dt(r)),
                None => empty(),
            }
        }
        Function::DateDiff => {
            if args.len() < 2 {
                return Err("DATE_DIFF requires a second argument (date)".to_string());
            }
            let a = eval(&args[0], file, ctx)?;
            let b = eval(&args[1], file, ctx)?;
            if a.is_empty() || b.is_empty() {
                return empty();
            }
            let (da, _) = match a.to_datetime(ctx.config.us_dates) {
                Ok(i) => i,
                Err(_) => return empty(),
            };
            let (db, _) = match b.to_datetime(ctx.config.us_dates) {
                Ok(i) => i,
                Err(_) => return empty(),
            };
            Ok(Variant::Int((da.date() - db.date()).num_days()))
        }
        Function::FromUnixtime => {
            let s = arg_str(args, 0, file, ctx)?;
            match s.trim().parse::<i64>() {
                Ok(ts) => match timestamp_to_local(ts) {
                    Some(dt) => Ok(Variant::Str(format_dt(&dt))),
                    None => empty(),
                },
                Err(_) => empty(),
            }
        }
        Function::LastDay => {
            let v = match arg_var(args, 0, file, ctx)? {
                Some(v) => v,
                None => return empty(),
            };
            if v.is_empty() {
                return empty();
            }
            let (dt, _) = match v.to_datetime(ctx.config.us_dates) {
                Ok(i) => i,
                Err(_) => return empty(),
            };
            match last_day_of_month(dt.year(), dt.month()) {
                Some(d) => {
                    let date = NaiveDate::from_ymd_opt(dt.year(), dt.month(), d).unwrap();
                    Ok(Variant::Str(date.format("%Y-%m-%d").to_string()))
                }
                None => empty(),
            }
        }
        Function::HasXattr => {
            if args.is_empty() || file.archive.is_some() {
                return Ok(Variant::Bool(false));
            }
            let name = arg_str(args, 0, file, ctx)?;
            match file.xattr_names() {
                Some(names) => Ok(Variant::Bool(names.iter().any(|n| n == &name))),
                None => Ok(Variant::Bool(false)),
            }
        }
        Function::Xattr => {
            if args.is_empty() {
                return empty();
            }
            let name = arg_str(args, 0, file, ctx)?;
            match file.xattr(&name) {
                Some(v) => Ok(Variant::Str(String::from_utf8_lossy(&v).to_string())),
                None => empty(),
            }
        }
        Function::HasExtattr => {
            if args.is_empty() {
                return Ok(Variant::Bool(false));
            }
            let flag = arg_str(args, 0, file, ctx)?;
            let attrs = extattrs(file);
            Ok(Variant::Bool(!flag.is_empty() && flag.chars().all(|c| attrs.contains(c))))
        }
        Function::HasAclEntry | Function::AclEntry | Function::HasDefaultAclEntry | Function::DefaultAclEntry => {
            let default = matches!(func, Function::HasDefaultAclEntry | Function::DefaultAclEntry);
            let is_has = matches!(func, Function::HasAclEntry | Function::HasDefaultAclEntry);
            let entries = match file.acl(default) {
                Some(e) if default || acl_is_extended(&e) => e,
                _ => return empty(),
            };
            let spec = arg_str(args, 0, file, ctx)?;
            let found = find_acl_entry(&entries, &spec);
            if is_has {
                Ok(Variant::Bool(found.is_some()))
            } else {
                match found {
                    Some(e) => Ok(Variant::Str(acl_entry_string(e))),
                    None => empty(),
                }
            }
        }
        Function::HasCapability => {
            let caps = match file.capabilities() {
                Some(c) => c,
                None => return empty(),
            };
            let name = arg_str(args, 0, file, ctx)?.to_lowercase();
            Ok(Variant::Bool(caps.iter().any(|c| c.split('=').next().unwrap_or("") == name)))
        }
        Function::FormatSize => {
            let v = match arg_var(args, 0, file, ctx)? {
                Some(v) => v,
                None => return empty(),
            };
            let size = match v {
                Variant::Int(i) if i >= 0 => i as u64,
                Variant::Float(f) if f >= 0.0 && f.fract() == 0.0 => f as u64,
                Variant::Str(ref s) => match s.trim().parse::<u64>() {
                    Ok(n) => n,
                    Err(_) => return empty(),
                },
                _ => return empty(),
            };
            let fmt = if args.len() > 1 { arg_str(args, 1, file, ctx)? } else { String::new() };
            Ok(Variant::from_opt_string(format_size(size, &fmt)))
        }
        Function::FormatTime => {
            let v = match arg_var(args, 0, file, ctx)? {
                Some(v) => v,
                None => return empty(),
            };
            let secs = match v {
                Variant::Int(i) if i >= 0 => i as u64,
                Variant::Float(f) if f >= 0.0 && f.fract() == 0.0 => f as u64,
                Variant::Str(ref s) => match s.parse::<u64>() {
                    Ok(n) => n,
                    Err(_) => return empty(),
                },
                _ => return empty(),
            };
            Ok(Variant::Str(format_time(secs)))
        }
        Function::CurrentUid => Ok(Variant::Int(unsafe { libc::getuid() } as i64)),
        Function::CurrentGid => Ok(Variant::Int(unsafe { libc::getgid() } as i64)),
        Function::CurrentUser => Ok(Variant::from_opt_string(user_name(unsafe { libc::getuid() }))),
        Function::CurrentGroup => Ok(Variant::from_opt_string(group_name(unsafe { libc::getgid() }))),
        Function::Contains => {
            let needle = arg_str(args, 0, file, ctx)?;
            match file.content() {
                Some(content) => {
                    let found = if needle.is_empty() {
                        true
                    } else {
                        content.windows(needle.len()).any(|w| w == needle.as_bytes())
                    };
                    Ok(Variant::Bool(found))
                }
                None => empty(),
            }
        }
        Function::Coalesce => {
            for a in args {
                let v = eval(a, file, ctx)?;
                if !v.is_empty() {
                    return Ok(v);
                }
            }
            empty()
        }
        _ => empty(),
    }
}

fn find_acl_entry<'a>(entries: &'a [AclEntry], spec: &str) -> Option<&'a AclEntry> {
    let parts: Vec<&str> = spec.splitn(3, ':').collect();
    if parts.len() > 2 {
        return None;
    }
    let (tag, qualifier) = (parts[0], parts.get(1).copied());
    let (want_tag, named_tag) = match tag {
        "user" => (ACL_USER_OBJ, ACL_USER),
        "u" => (ACL_USER_OBJ, ACL_USER),
        "group" => (ACL_GROUP_OBJ, ACL_GROUP),
        "g" => (ACL_GROUP_OBJ, ACL_GROUP),
        "mask" | "m" => (ACL_MASK, ACL_MASK),
        "other" | "o" => (ACL_OTHER, ACL_OTHER),
        _ => return None,
    };
    match qualifier {
        None => {
            if tag == "user" || tag == "group" {
                return None;
            }
            entries.iter().find(|e| e.tag == want_tag)
        }
        Some("") => entries.iter().find(|e| e.tag == want_tag),
        Some(q) => {
            if want_tag == ACL_MASK || want_tag == ACL_OTHER {
                return None;
            }
            let id = match q.parse::<u32>() {
                Ok(n) => Some(n),
                Err(_) => {
                    if named_tag == ACL_USER { uid_by_name(q) } else { gid_by_name(q) }
                }
            }?;
            entries.iter().find(|e| e.tag == named_tag && e.id == id)
        }
    }
}

fn is_hiragana(c: char) -> bool {
    ('\u{3040}'..='\u{309f}').contains(&c)
}
fn is_katakana(c: char) -> bool {
    ('\u{30a0}'..='\u{30ff}').contains(&c) || ('\u{31f0}'..='\u{31ff}').contains(&c) || ('\u{ff66}'..='\u{ff9f}').contains(&c)
}
fn is_kanji(c: char) -> bool {
    ('\u{4e00}'..='\u{9fff}').contains(&c) || ('\u{3400}'..='\u{4dbf}').contains(&c)
}
fn is_greek(c: char) -> bool {
    ('\u{0370}'..='\u{03ff}').contains(&c) || ('\u{1f00}'..='\u{1fff}').contains(&c)
}

trait WeekdayFull {
    fn to_string_full(&self) -> String;
}
impl WeekdayFull for chrono::Weekday {
    fn to_string_full(&self) -> String {
        match self {
            chrono::Weekday::Mon => "Monday",
            chrono::Weekday::Tue => "Tuesday",
            chrono::Weekday::Wed => "Wednesday",
            chrono::Weekday::Thu => "Thursday",
            chrono::Weekday::Fri => "Friday",
            chrono::Weekday::Sat => "Saturday",
            chrono::Weekday::Sun => "Sunday",
        }
        .to_string()
    }
}

