pub type EvalResult = Result<Variant, String>;

pub struct Ctx<'a> {
    pub config: &'a Config,
    /// values of the aggregate functions for the current output row
    pub aggregates: Option<&'a HashMap<String, Variant>>,
    /// outer file for correlated subqueries: (alias, file)
    pub outer: Vec<(String, &'a FileInfo)>,
    /// hook to run subqueries
    pub subquery_runner: Option<&'a dyn Fn(&Query, &[(String, &FileInfo)]) -> Vec<Vec<String>>>,
}

impl<'a> Ctx<'a> {
    pub fn new(config: &'a Config) -> Ctx<'a> {
        Ctx { config, aggregates: None, outer: vec![], subquery_runner: None }
    }
}

fn empty() -> EvalResult {
    Ok(Variant::empty())
}

fn ext_matches(file: &FileInfo, list: &[String]) -> bool {
    let lower = file.name.to_lowercase();
    list.iter().any(|e| lower.ends_with(&e.to_lowercase()))
}

pub fn eval(expr: &Expr, file: &FileInfo, ctx: &Ctx) -> EvalResult {
    match expr {
        Expr::Field(field, alias) => {
            if let Some(a) = alias {
                if let Some((_, outer)) = ctx.outer.iter().find(|(n, _)| n == a) {
                    return eval_field(*field, outer, ctx);
                }
            }
            eval_field(*field, file, ctx)
        }
        Expr::Literal(s) => Ok(Variant::Str(s.clone())),
        Expr::Function(func, args) => eval_function(*func, args, expr, file, ctx),
        Expr::Arith(l, op, r) => {
            let lv = eval(l, file, ctx)?.to_f64();
            let rv = eval(r, file, ctx)?.to_f64();
            let res = match op {
                ArithOp::Add => lv + rv,
                ArithOp::Subtract => lv - rv,
                ArithOp::Multiply => lv * rv,
                ArithOp::Divide => {
                    if rv == 0.0 {
                        return Err("Division by zero".to_string());
                    }
                    lv / rv
                }
                ArithOp::Modulo => {
                    if rv == 0.0 {
                        return Err("Division by zero".to_string());
                    }
                    lv % rv
                }
            };
            Ok(Variant::Float(res))
        }
        _ => Ok(Variant::Bool(eval_bool(expr, file, ctx)?)),
    }
}

/// Evaluate a condition.
pub fn eval_bool(expr: &Expr, file: &FileInfo, ctx: &Ctx) -> Result<bool, String> {
    match expr {
        Expr::And(l, r) => Ok(eval_bool(l, file, ctx)? && eval_bool(r, file, ctx)?),
        Expr::Or(l, r) => Ok(eval_bool(l, file, ctx)? || eval_bool(r, file, ctx)?),
        Expr::Not(e) => Ok(!eval_bool(e, file, ctx)?),
        Expr::Compare(l, op, r) => compare(l, *op, r, file, ctx),
        Expr::Between(l, a, b, negated) => {
            let lv = eval(l, file, ctx)?;
            let av = eval(a, file, ctx)?;
            let bv = eval(b, file, ctx)?;
            let res = match l.kind() {
                FieldKind::Num | FieldKind::Bool => {
                    let v = lv.to_f64();
                    v >= av.to_f64() && v <= bv.to_f64()
                }
                FieldKind::DateTime => {
                    let (from, _) = lv.to_datetime(ctx.config.us_dates)?;
                    let (afrom, _) = av.to_datetime(ctx.config.us_dates)?;
                    let (_, bto) = bv.to_datetime(ctx.config.us_dates)?;
                    from >= afrom && from <= bto
                }
                FieldKind::Str => {
                    let v = lv.to_string();
                    v >= av.to_string() && v <= bv.to_string()
                }
            };
            Ok(res != *negated)
        }
        Expr::InList(l, list, negated) => {
            let lv = eval(l, file, ctx)?;
            let mut found = false;
            match l.kind() {
                FieldKind::DateTime => {
                    return Err("Can't parse datetime: ".to_string());
                }
                FieldKind::Num => {
                    let v = lv.to_f64();
                    for item in list {
                        if eval(item, file, ctx)?.to_f64() == v {
                            found = true;
                            break;
                        }
                    }
                }
                FieldKind::Bool => {
                    let v = lv.to_bool();
                    for item in list {
                        if eval(item, file, ctx)?.to_bool() == v {
                            found = true;
                            break;
                        }
                    }
                }
                FieldKind::Str => {
                    let v = lv.to_string();
                    for item in list {
                        if eval(item, file, ctx)?.to_string() == v {
                            found = true;
                            break;
                        }
                    }
                }
            }
            Ok(found != *negated)
        }
        Expr::InSubquery(l, q, negated) => {
            let lv = eval(l, file, ctx)?.to_string();
            let rows = run_subquery(q, file, ctx);
            let found = rows.iter().any(|row| row.first().map(|v| v == &lv).unwrap_or(false));
            Ok(found != *negated)
        }
        Expr::Exists(q, negated) => {
            let rows = run_subquery(q, file, ctx);
            Ok(!rows.is_empty() != *negated)
        }
        Expr::Field(f, _) => {
            if f.is_boolean() {
                Ok(eval(expr, file, ctx)?.to_bool())
            } else {
                Ok(false)
            }
        }
        Expr::Function(f, _, ..) => {
            if f.kind() == FieldKind::Bool {
                Ok(eval(expr, file, ctx)?.to_bool())
            } else {
                Ok(false)
            }
        }
        _ => Ok(false),
    }
}

fn run_subquery(q: &Query, file: &FileInfo, ctx: &Ctx) -> Vec<Vec<String>> {
    match ctx.subquery_runner {
        Some(runner) => {
            let mut outer: Vec<(String, &FileInfo)> = ctx.outer.clone();
            // bind the current file to every alias of the parent query roots
            for (alias, _) in &ctx.outer {
                let _ = alias;
            }
            if let Some(alias) = &ctx_alias(ctx) {
                outer.push((alias.clone(), file));
            }
            runner(q, &outer)
        }
        None => vec![],
    }
}

thread_local! {
    pub static CURRENT_ALIAS: std::cell::RefCell<Option<String>> = std::cell::RefCell::new(None);
}

fn ctx_alias(_ctx: &Ctx) -> Option<String> {
    CURRENT_ALIAS.with(|a| a.borrow().clone())
}

fn compare(l: &Expr, op: CmpOp, r: &Expr, file: &FileInfo, ctx: &Ctx) -> Result<bool, String> {
    let lv = eval(l, file, ctx)?;
    let rv = eval(r, file, ctx)?;
    match l.kind() {
        FieldKind::Num => {
            let a = lv.to_f64();
            let b = rv.to_f64();
            Ok(match op {
                CmpOp::Eq | CmpOp::Eeq => a == b,
                CmpOp::Ne | CmpOp::Ene => a != b,
                CmpOp::Gt => a > b,
                CmpOp::Gte => a >= b,
                CmpOp::Lt => a < b,
                CmpOp::Lte => a <= b,
                CmpOp::Rx | CmpOp::NotRx | CmpOp::Like | CmpOp::NotLike => false,
            })
        }
        FieldKind::Bool => {
            let a = lv.to_bool();
            let b = rv.to_bool();
            Ok(match op {
                CmpOp::Eq | CmpOp::Eeq => a == b,
                CmpOp::Ne | CmpOp::Ene => a != b,
                CmpOp::Gt => a & !b,
                CmpOp::Gte => a >= b,
                CmpOp::Lt => !a & b,
                CmpOp::Lte => a <= b,
                CmpOp::Rx | CmpOp::NotRx | CmpOp::Like | CmpOp::NotLike => false,
            })
        }
        FieldKind::DateTime => {
            let (rfrom, rto) = rv.to_datetime(ctx.config.us_dates)?;
            let (from, _) = match lv {
                Variant::DateTime(i) => i,
                Variant::Str(ref s) if s.is_empty() => return Ok(false),
                other => other.to_datetime(ctx.config.us_dates)?,
            };
            Ok(match op {
                CmpOp::Eq | CmpOp::Eeq => from >= rfrom && from <= rto,
                CmpOp::Ne | CmpOp::Ene => !(from >= rfrom && from <= rto),
                CmpOp::Gt => from > rto,
                CmpOp::Gte => from >= rfrom,
                CmpOp::Lt => from < rfrom,
                CmpOp::Lte => from <= rto,
                CmpOp::Rx | CmpOp::NotRx | CmpOp::Like | CmpOp::NotLike => false,
            })
        }
        FieldKind::Str => {
            let a = lv.to_string();
            let b = rv.to_string();
            Ok(match op {
                CmpOp::Eq | CmpOp::Ne => {
                    let res = if is_glob(&b) {
                        let re = glob_to_regex(&b)?;
                        re.is_match(&a)
                    } else {
                        a == b
                    };
                    if op == CmpOp::Eq { res } else { !res }
                }
                CmpOp::Eeq => a == b,
                CmpOp::Ene => a != b,
                CmpOp::Gt => a > b,
                CmpOp::Gte => a >= b,
                CmpOp::Lt => a < b,
                CmpOp::Lte => a <= b,
                CmpOp::Rx | CmpOp::NotRx => {
                    let re = compile_regex(&b)?;
                    let res = re.is_match(&a);
                    if op == CmpOp::Rx { res } else { !res }
                }
                CmpOp::Like | CmpOp::NotLike => {
                    let re = like_to_regex(&b)?;
                    let res = re.is_match(&a);
                    if op == CmpOp::Like { res } else { !res }
                }
            })
        }
    }
}

// ---------------------------------------------------------------- fields

pub fn eval_field(field: Field, file: &FileInfo, ctx: &Ctx) -> EvalResult {
    let is_empty_file = file.full_path.as_os_str().is_empty() && file.archive.is_none();
    if is_empty_file {
        return empty();
    }
    let md = file.metadata.as_ref();
    let arc = file.archive.as_ref();
    let r = match field {
        Field::Name => Variant::Str(file.name.clone()),
        Field::Filename => Variant::Str(file.filename()),
        Field::Extension => Variant::Str(file.extension()),
        Field::Path => Variant::Str(file.rel_path.clone()),
        Field::AbsPath => Variant::from_opt_string(file.abspath().map(|p| p.to_string_lossy().to_string())),
        Field::Directory => Variant::Str(file.directory()),
        Field::AbsDir => Variant::from_opt_string(file.absdir().map(|p| p.to_string_lossy().to_string())),
        Field::Size => Variant::from_opt_u64(file.size()),
        Field::FormattedSize => match file.size() {
            Some(s) => Variant::from_opt_string(format_size(s, &ctx.config.default_file_size_format)),
            None => Variant::empty(),
        },
        Field::Uid => {
            if arc.is_some() { Variant::empty() } else { Variant::from_opt_u64(md.map(|m| m.uid() as u64)) }
        }
        Field::Gid => {
            if arc.is_some() { Variant::empty() } else { Variant::from_opt_u64(md.map(|m| m.gid() as u64)) }
        }
        Field::User => {
            if arc.is_some() { Variant::empty() } else { Variant::from_opt_string(md.and_then(|m| user_name(m.uid()))) }
        }
        Field::Group => {
            if arc.is_some() { Variant::empty() } else { Variant::from_opt_string(md.and_then(|m| group_name(m.gid()))) }
        }
        Field::Created => Variant::from_opt_dt(file.created()),
        Field::Accessed => Variant::from_opt_dt(file.accessed()),
        Field::Modified => Variant::from_opt_dt(file.modified()),
        Field::IsDir => Variant::from_opt_bool(file.is_dir()),
        Field::IsFile => Variant::from_opt_bool(file.is_file()),
        Field::IsSymlink => Variant::from_opt_bool(file.is_symlink()),
        Field::IsPipe => {
            if arc.is_some() { Variant::Bool(false) } else { Variant::from_opt_bool(md.map(|m| m.file_type().is_fifo())) }
        }
        Field::IsCharacterDevice => {
            if arc.is_some() { Variant::Bool(false) } else { Variant::from_opt_bool(md.map(|m| m.file_type().is_char_device())) }
        }
        Field::IsBlockDevice => {
            if arc.is_some() { Variant::Bool(false) } else { Variant::from_opt_bool(md.map(|m| m.file_type().is_block_device())) }
        }
        Field::IsSocket => {
            if arc.is_some() { Variant::Bool(false) } else { Variant::from_opt_bool(md.map(|m| m.file_type().is_socket())) }
        }
        Field::Device => if arc.is_some() { Variant::empty() } else { Variant::from_opt_u64(md.map(|m| m.dev())) },
        Field::Rdev => if arc.is_some() { Variant::empty() } else { Variant::from_opt_u64(md.map(|m| m.rdev())) },
        Field::Inode => if arc.is_some() { Variant::empty() } else { Variant::from_opt_u64(md.map(|m| m.ino())) },
        Field::Blocks => if arc.is_some() { Variant::empty() } else { Variant::from_opt_u64(md.map(|m| m.blocks())) },
        Field::Hardlinks => if arc.is_some() { Variant::empty() } else { Variant::from_opt_u64(md.map(|m| m.nlink())) },
        Field::Atime => if arc.is_some() { Variant::empty() } else { match md { Some(m) => Variant::Int(m.atime()), None => Variant::empty() } },
        Field::Mtime => if arc.is_some() { Variant::empty() } else { match md { Some(m) => Variant::Int(m.mtime()), None => Variant::empty() } },
        Field::Ctime => if arc.is_some() { Variant::empty() } else { match md { Some(m) => Variant::Int(m.ctime()), None => Variant::empty() } },
        Field::Mode => Variant::from_opt_string(file.mode().map(mode_string)),
        Field::UserRead => Variant::from_opt_bool(file.mode().map(|m| m & 0o400 != 0)),
        Field::UserWrite => Variant::from_opt_bool(file.mode().map(|m| m & 0o200 != 0)),
        Field::UserExec => Variant::from_opt_bool(file.mode().map(|m| m & 0o100 != 0)),
        Field::UserAll => Variant::from_opt_bool(file.mode().map(|m| m & 0o700 == 0o700)),
        Field::GroupRead => Variant::from_opt_bool(file.mode().map(|m| m & 0o040 != 0)),
        Field::GroupWrite => Variant::from_opt_bool(file.mode().map(|m| m & 0o020 != 0)),
        Field::GroupExec => Variant::from_opt_bool(file.mode().map(|m| m & 0o010 != 0)),
        Field::GroupAll => Variant::from_opt_bool(file.mode().map(|m| m & 0o070 == 0o070)),
        Field::OtherRead => Variant::from_opt_bool(file.mode().map(|m| m & 0o004 != 0)),
        Field::OtherWrite => Variant::from_opt_bool(file.mode().map(|m| m & 0o002 != 0)),
        Field::OtherExec => Variant::from_opt_bool(file.mode().map(|m| m & 0o001 != 0)),
        Field::OtherAll => Variant::from_opt_bool(file.mode().map(|m| m & 0o007 == 0o007)),
        Field::Suid => Variant::from_opt_bool(file.mode().map(|m| m & 0o4000 != 0)),
        Field::Sgid => Variant::from_opt_bool(file.mode().map(|m| m & 0o2000 != 0)),
        Field::IsSticky => Variant::from_opt_bool(file.mode().map(|m| m & 0o1000 != 0)),
        Field::IsHidden => Variant::Bool(file.name.starts_with('.')),
        Field::HasXattrs => {
            if arc.is_some() { Variant::empty() } else { Variant::from_opt_bool(file.xattr_names().map(|x| !x.is_empty())) }
        }
        Field::XattrCount => {
            if arc.is_some() { Variant::empty() } else { Variant::from_opt_u64(file.xattr_names().map(|x| x.len() as u64)) }
        }
        Field::Extattrs => {
            if arc.is_some() { Variant::empty() } else { Variant::Str(extattrs(file)) }
        }
        Field::HasExtattrs => {
            if arc.is_some() { Variant::empty() } else { Variant::Bool(!extattrs(file).is_empty()) }
        }
        Field::Acl => match file.acl(false) {
            Some(entries) if acl_is_extended(&entries) => {
                Variant::Str(entries.iter().map(acl_entry_string).collect::<Vec<_>>().join(","))
            }
            _ => Variant::empty(),
        },
        Field::HasAcl => match file.acl(false) {
            Some(entries) if acl_is_extended(&entries) => Variant::Bool(true),
            _ => Variant::empty(),
        },
        Field::DefaultAcl => match file.acl(true) {
            Some(entries) if !entries.is_empty() => {
                Variant::Str(entries.iter().map(acl_entry_string).collect::<Vec<_>>().join(","))
            }
            _ => Variant::empty(),
        },
        Field::HasDefaultAcl => match file.acl(true) {
            Some(entries) if !entries.is_empty() => Variant::Bool(true),
            _ => Variant::empty(),
        },
        Field::HasCapabilities => {
            if arc.is_some() { Variant::empty() } else { Variant::Bool(file.capabilities().map(|c| !c.is_empty()).unwrap_or(false)) }
        }
        Field::Capabilities => Variant::from_opt_string(file.capabilities().map(|c| c.join(","))),
        Field::IsShebang => Variant::from_opt_bool(file.is_shebang()),
        Field::IsEmpty => Variant::from_opt_bool(file.is_empty()),
        Field::Width => Variant::from_opt_u64(file.dimensions().map(|d| d.0)),
        Field::Height => Variant::from_opt_u64(file.dimensions().map(|d| d.1)),
        Field::Duration | Field::Bitrate | Field::Freq | Field::Year => Variant::empty(),
        Field::Title | Field::Artist | Field::Album | Field::Genre => Variant::empty(),
        Field::Mime => Variant::from_opt_string(file.mime()),
        Field::LineCount => Variant::from_opt_u64(file.line_count()),
        Field::IsBinary => match file.mime() {
            Some(m) => Variant::Bool(m != "inode/directory" && !crate::mime::is_text_mime(&m)),
            None => Variant::empty(),
        },
        Field::IsText => match file.mime() {
            Some(m) => Variant::Bool(crate::mime::is_text_mime(&m)),
            None => Variant::empty(),
        },
        Field::IsArchive => Variant::Bool(ext_matches(file, &ctx.config.is_archive)),
        Field::IsAudio => Variant::Bool(ext_matches(file, &ctx.config.is_audio)),
        Field::IsBook => Variant::Bool(ext_matches(file, &ctx.config.is_book)),
        Field::IsDoc => Variant::Bool(ext_matches(file, &ctx.config.is_doc)),
        Field::IsFont => Variant::Bool(ext_matches(file, &ctx.config.is_font)),
        Field::IsImage => Variant::Bool(ext_matches(file, &ctx.config.is_image)),
        Field::IsSource => Variant::Bool(ext_matches(file, &ctx.config.is_source)),
        Field::IsVideo => Variant::Bool(ext_matches(file, &ctx.config.is_video)),
        Field::Sha1 => Variant::from_opt_string(file.hash("sha1")),
        Field::Sha256 => Variant::from_opt_string(file.hash("sha256")),
        Field::Sha512 => Variant::from_opt_string(file.hash("sha512")),
        Field::Sha3 => Variant::from_opt_string(file.hash("sha3")),
        _ => Variant::empty(),
    };
    Ok(r)
}

fn extattrs(file: &FileInfo) -> String {
    use std::os::unix::io::AsRawFd;
    if file.archive.is_some() {
        return String::new();
    }
    let f = match std::fs::File::open(&file.full_path) {
        Ok(f) => f,
        Err(_) => return String::new(),
    };
    let mut flags: libc::c_long = 0;
    const FS_IOC_GETFLAGS: libc::c_ulong = 0x80086601;
    let rc = unsafe { libc::ioctl(f.as_raw_fd(), FS_IOC_GETFLAGS as _, &mut flags) };
    if rc != 0 {
        return String::new();
    }
    let table: [(u64, char); 21] = [
        (0x00000001, 's'),
        (0x00000002, 'u'),
        (0x00000004, 'c'),
        (0x00000008, 'S'),
        (0x00000010, 'i'),
        (0x00000020, 'a'),
        (0x00000040, 'd'),
        (0x00000080, 'A'),
        (0x00000800, 'E'),
        (0x00001000, 'I'),
        (0x00004000, 'j'),
        (0x00008000, 't'),
        (0x00010000, 'D'),
        (0x00020000, 'T'),
        (0x00080000, 'e'),
        (0x00100000, 'V'),
        (0x00800000, 'C'),
        (0x02000000, 'x'),
        (0x10000000, 'N'),
        (0x20000000, 'P'),
        (0x40000000, 'F'),
    ];
    let mut s = String::new();
    for (bit, c) in table.iter() {
        if (flags as u64) & bit != 0 {
            s.push(*c);
        }
    }
    s
}

// ---------------------------------------------------------------- functions

fn arg_str(args: &[Expr], i: usize, file: &FileInfo, ctx: &Ctx) -> Result<String, String> {
    match args.get(i) {
        Some(e) => Ok(eval(e, file, ctx)?.to_string()),
        None => Ok(String::new()),
    }
}

fn arg_var(args: &[Expr], i: usize, file: &FileInfo, ctx: &Ctx) -> Result<Option<Variant>, String> {
    match args.get(i) {
        Some(e) => Ok(Some(eval(e, file, ctx)?)),
        None => Ok(None),
    }
}

fn num_or_empty(v: Option<f64>) -> Variant {
    match v {
        Some(v) => Variant::Float(v),
        None => Variant::empty(),
    }
}

fn eval_function(func: Function, args: &[Expr], expr: &Expr, file: &FileInfo, ctx: &Ctx) -> EvalResult {
    if func.is_aggregate() {
        if let Some(aggs) = ctx.aggregates {
            let key = expr.to_key().to_lowercase();
            return Ok(aggs.get(&key).cloned().unwrap_or_else(Variant::empty));
        }
        // when evaluated for a single file, return the value of the argument
        return match args.first() {
            Some(a) => eval(a, file, ctx),
            None => empty(),
        };
    }
    match func {
        Function::Lower => Ok(Variant::Str(arg_str(args, 0, file, ctx)?.to_lowercase())),
        Function::Upper => Ok(Variant::Str(arg_str(args, 0, file, ctx)?.to_uppercase())),
        Function::InitCap => {
            let s = arg_str(args, 0, file, ctx)?;
            let mut out = String::new();
            let mut start = true;
            for c in s.chars() {
                if c.is_alphanumeric() {
                    if start {
                        out.extend(c.to_uppercase());
                        start = false;
                    } else {
                        out.extend(c.to_lowercase());
                    }
                } else {
                    out.push(c);
                    start = true;
                }
            }
            Ok(Variant::Str(out))
        }
        Function::Length => Ok(Variant::Int(arg_str(args, 0, file, ctx)?.chars().count() as i64)),
        Function::ToBase64 => {
            use base64::Engine;
            let s = arg_str(args, 0, file, ctx)?;
            Ok(Variant::Str(base64::engine::general_purpose::STANDARD.encode(s.as_bytes())))
        }
        Function::FromBase64 => {
            use base64::Engine;
            let s = arg_str(args, 0, file, ctx)?;
            let decoded = base64::engine::general_purpose::STANDARD
                .decode(s.as_bytes())
                .or_else(|_| base64::engine::general_purpose::STANDARD_NO_PAD.decode(s.as_bytes()));
            match decoded {
                Ok(bytes) => Ok(Variant::Str(String::from_utf8_lossy(&bytes).to_string())),
                Err(_) => empty(),
            }
        }
        Function::Concat => {
            let mut out = String::new();
            for a in args {
                out.push_str(&eval(a, file, ctx)?.to_string());
            }
            Ok(Variant::Str(out))
        }
        Function::ConcatWs => {
            if args.len() < 2 {
                return empty();
            }
            let sep = eval(&args[0], file, ctx)?.to_string();
            let mut parts = vec![];
            for a in &args[1..] {
                parts.push(eval(a, file, ctx)?.to_string());
            }
            Ok(Variant::Str(parts.join(&sep)))
        }
        Function::Locate => {
            if args.len() < 2 {
                return Err("LOCATE requires a search substring argument".to_string());
            }
            let s = arg_str(args, 0, file, ctx)?;
            let sub = arg_str(args, 1, file, ctx)?;
            let mut pos: i64 = 1;
            if args.len() > 2 {
                let p = arg_str(args, 2, file, ctx)?;
                pos = p
                    .parse::<i64>()
                    .map_err(|_| format!("Could not parse position argument of LOCATE function: {}", p))?;
            }
