        lc.add(DEFAULT);
        if let Ok(env) = std::env::var("LS_COLORS") {
            lc.add(&env);
        }
        lc.finalize();
        lc
    }

    fn add(&mut self, s: &str) {
        for item in s.split(':') {
            let mut parts = item.splitn(2, '=');
            let key = parts.next().unwrap_or("");
            let value = match parts.next() {
                Some(v) => v,
                None => continue,
            };
            let style = Style::parse(value);
            if let Some(suffix) = key.strip_prefix('*') {
                match style {
                    Some(st) => {
                        self.suffixes.retain(|s| s.suffix != suffix);
                        self.suffixes.push(Suffix { suffix: suffix.to_string(), style: st, exact: false });
                    }
                    None => self.suffixes.retain(|s| s.suffix != suffix),
                }
            } else if let Some(ind) = Indicator::from_key(key) {
                match style {
                    Some(st) => {
                        self.indicators.insert(ind, st);
                    }
                    None => {
                        self.indicators.remove(&ind);
                    }
                }
            }
        }
    }

    fn finalize(&mut self) {
        let n = self.suffixes.len();
        for i in 0..n {
            for j in (i + 1)..n {
                let a = &self.suffixes[i];
                let b = &self.suffixes[j];
                if a.suffix.len() == b.suffix.len() && a.suffix.eq_ignore_ascii_case(&b.suffix) && a.style != b.style {
                    self.suffixes[i].exact = true;
                    self.suffixes[j].exact = true;
                }
            }
        }
    }

    fn colored(&self, ind: Indicator) -> bool {
        self.indicators.get(&ind).map(|s| !s.is_plain()).unwrap_or(false)
    }

    fn style_for_indicator(&self, ind: Indicator) -> Option<&Style> {
        if let Some(s) = self.indicators.get(&ind) {
            return Some(s);
        }
        let fallback = match ind {
            Indicator::Setuid
            | Indicator::Setgid
            | Indicator::Executable
            | Indicator::MultipleHardLinks
            | Indicator::Capability => Indicator::RegularFile,
            Indicator::Sticky | Indicator::OtherWritable | Indicator::StickyOtherWritable => Indicator::Directory,
            Indicator::OrphanedLink | Indicator::Missing => Indicator::SymbolicLink,
            _ => Indicator::Normal,
        };
        if let Some(s) = self.indicators.get(&fallback) {
            return Some(s);
        }
        self.indicators.get(&Indicator::Normal)
    }

    fn style_for_name(&self, name: &str) -> Option<&Style> {
        for s in self.suffixes.iter().rev() {
            let m = if s.exact {
                name.ends_with(&s.suffix)
            } else {
                name.len() >= s.suffix.len()
                    && name.is_char_boundary(name.len() - s.suffix.len())
                    && name[name.len() - s.suffix.len()..].eq_ignore_ascii_case(&s.suffix)
            };
            if m {
                return Some(&s.style);
            }
        }
        None
    }

    pub fn style_for(&self, path: &Path, name: &str, metadata: Option<&Metadata>) -> Option<&Style> {
        let md = metadata?;
        let ft = md.file_type();
        let mode = md.permissions().mode();
        let ind = if ft.is_file() {
            if mode & 0o4000 != 0 && self.colored(Indicator::Setuid) {
                Indicator::Setuid
            } else if mode & 0o2000 != 0 && self.colored(Indicator::Setgid) {
                Indicator::Setgid
            } else if mode & 0o111 != 0 && self.colored(Indicator::Executable) {
                Indicator::Executable
            } else if md.nlink() > 1 && self.colored(Indicator::MultipleHardLinks) {
                Indicator::MultipleHardLinks
            } else {
                Indicator::RegularFile
            }
        } else if ft.is_dir() {
            let sticky = mode & 0o1000 != 0;
            let ow = mode & 0o002 != 0;
            if sticky && ow && self.colored(Indicator::StickyOtherWritable) {
                Indicator::StickyOtherWritable
            } else if ow && self.colored(Indicator::OtherWritable) {
                Indicator::OtherWritable
            } else if sticky && self.colored(Indicator::Sticky) {
                Indicator::Sticky
            } else {
                Indicator::Directory
            }
        } else if ft.is_symlink() {
            if !path.exists() && self.colored(Indicator::OrphanedLink) {
                Indicator::OrphanedLink
            } else {
                Indicator::SymbolicLink
            }
        } else if ft.is_fifo() {
            Indicator::Fifo
        } else if ft.is_socket() {
            Indicator::Socket
        } else if ft.is_block_device() {
            Indicator::BlockDevice
        } else if ft.is_char_device() {
            Indicator::CharDevice
        } else {
            Indicator::Normal
        };
        if ind == Indicator::RegularFile {
            if let Some(s) = self.style_for_name(name) {
                return Some(s);
            }
        }
        self.style_for_indicator(ind)
    }
}
