#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Style {
    bold: bool,
    dimmed: bool,
    italic: bool,
    underline: bool,
    blink: bool,
    reverse: bool,
    hidden: bool,
    strikethrough: bool,
    fg: Option<Color>,
    bg: Option<Color>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Color {
    Basic(u8),
    Fixed(u8),
    Rgb(u8, u8, u8),
}

impl Style {
    pub fn is_plain(&self) -> bool {
        *self == Style::default()
    }

    pub fn parse(code: &str) -> Option<Style> {
        let mut st = Style::default();
        let mut it = code.split(';').map(|p| p.parse::<u8>());
        loop {
            match it.next() {
                None => break,
                Some(Err(_)) => return None,
                Some(Ok(n)) => match n {
                    0 => st = Style::default(),
                    1 => st.bold = true,
                    2 => st.dimmed = true,
                    3 => st.italic = true,
                    4 => st.underline = true,
                    5 | 6 => st.blink = true,
                    7 => st.reverse = true,
                    8 => st.hidden = true,
                    9 => st.strikethrough = true,
                    30..=37 => st.fg = Some(Color::Basic(n - 30)),
                    38 => st.fg = Some(parse_extended(&mut it)?),
                    39 => st.fg = None,
                    40..=47 => st.bg = Some(Color::Basic(n - 40)),
                    48 => st.bg = Some(parse_extended(&mut it)?),
                    49 => st.bg = None,
                    90..=97 => st.fg = Some(Color::Fixed(n - 90 + 8)),
                    100..=107 => st.bg = Some(Color::Fixed(n - 100 + 8)),
                    _ => {}
                },
            }
        }
        Some(st)
    }

    pub fn paint(&self, s: &str) -> String {
        if self.is_plain() {
            return s.to_string();
        }
        let mut codes: Vec<String> = vec![];
        if self.bold {
            codes.push("1".into());
        }
        if self.dimmed {
            codes.push("2".into());
        }
        if self.italic {
            codes.push("3".into());
        }
        if self.underline {
            codes.push("4".into());
        }
        if self.blink {
            codes.push("5".into());
        }
        if self.reverse {
            codes.push("7".into());
        }
        if self.hidden {
            codes.push("8".into());
        }
        if self.strikethrough {
            codes.push("9".into());
        }
        if let Some(bg) = &self.bg {
            codes.push(match bg {
                Color::Basic(n) => format!("{}", 40 + n),
                Color::Fixed(n) => format!("48;5;{}", n),
                Color::Rgb(r, g, b) => format!("48;2;{};{};{}", r, g, b),
            });
        }
        if let Some(fg) = &self.fg {
            codes.push(match fg {
                Color::Basic(n) => format!("{}", 30 + n),
                Color::Fixed(n) => format!("38;5;{}", n),
                Color::Rgb(r, g, b) => format!("38;2;{};{};{}", r, g, b),
            });
        }
        format!("\x1b[{}m{}\x1b[0m", codes.join(";"), s)
    }
}

fn parse_extended<I: Iterator<Item = Result<u8, std::num::ParseIntError>>>(it: &mut I) -> Option<Color> {
