//! Directory traversal, filtering and output.

use crate::config::Config;
use crate::eval::{eval, eval_bool, Ctx, CURRENT_ALIAS};
use crate::field::{Field, FieldKind};
use crate::fileinfo::FileInfo;
use crate::function::Function;
use crate::lscolors::LsColors;
use crate::query::*;
use crate::util::{csv_escape, html_escape};
use crate::variant::Variant;
use regex::Regex;
use std::collections::{HashMap, VecDeque};
use std::io::Write;
use std::path::{Path, PathBuf};

pub struct Options {
    pub show_errors: bool,
    pub use_colors_stdout: bool,
    pub use_colors_stderr: bool,
}

pub struct Searcher<'a> {
    query: &'a Query,
    config: &'a Config,
    opts: &'a Options,
    lscolors: Option<LsColors>,
    pub has_errors: bool,
    found: usize,
    skipped: usize,
    rows: Vec<Row>,
    first_row: bool,
    stop: bool,
    aggregate_mode: bool,
    buffered: bool,
    out: std::io::BufWriter<std::io::Stdout>,
    // files matched for aggregate computations: (values of group exprs, field values per aggregate expr)
    agg_files: Vec<AggRow>,
    outer: Vec<(String, &'a FileInfo)>,
    output_rows: Option<&'a std::cell::RefCell<Vec<Vec<String>>>>,
    docker_ignores: Vec<(PathBuf, Vec<(Regex, bool)>)>,
}

struct Row {
    values: Vec<String>,
    archive: Option<String>,
    sort_keys: Vec<Variant>,
    colored_name: Option<(usize, String)>,
}

struct AggRow {
    group: Vec<String>,
    values: HashMap<String, Variant>,
    plain: Vec<String>,
    archive: Option<String>,
}

pub fn yellow(s: &str, colors: bool) -> String {
    if colors {
        format!("\x1b[33m{}\x1b[0m", s)
    } else {
        s.to_string()
    }
}

impl<'a> Searcher<'a> {
    pub fn new(query: &'a Query, config: &'a Config, opts: &'a Options) -> Searcher<'a> {
        let aggregate_mode = query.has_aggregate();
        let buffered = aggregate_mode || !query.ordering.is_empty();
        let lscolors = if opts.use_colors_stdout
            && matches!(query.output_format, OutputFormat::Tabs | OutputFormat::Lines)
        {
            Some(LsColors::from_env())
        } else {
            None
        };
        Searcher {
            query,
            config,
            opts,
            lscolors,
            has_errors: false,
            found: 0,
            skipped: 0,
            rows: vec![],
            first_row: true,
            stop: false,
            aggregate_mode,
            buffered,
            out: std::io::BufWriter::new(std::io::stdout()),
            agg_files: vec![],
            outer: vec![],
            output_rows: None,
            docker_ignores: vec![],
        }
    }

    pub fn with_outer(mut self, outer: Vec<(String, &'a FileInfo)>, rows: &'a std::cell::RefCell<Vec<Vec<String>>>) -> Self {
        self.outer = outer;
        self.output_rows = Some(rows);
        self
    }

    fn error(&mut self, subject: &str, message: &str) {
        self.has_errors = true;
        if self.opts.show_errors && self.output_rows.is_none() {
            let _ = self.out.flush();
            eprintln!("{}: {}", yellow(subject, self.opts.use_colors_stderr), message);
        }
    }

    fn effective_limit(&self) -> usize {
        if self.query.limit > 0 {
            return self.query.limit;
        }
        if !self.aggregate_mode && !self.query.fields.iter().any(|c| c.expr.has_field()) {
            return 1;
        }
        0
    }

    pub fn run(&mut self) -> bool {
        let limit = self.effective_limit();
        self.write_header();
        let mut roots = self.query.roots.clone();
        if roots.is_empty() {
            roots.push(Root::new(".".to_string()));
        }
        for root in &roots {
            if self.stop {
                break;
            }
            let mut root = root.clone();
            if root.gitignore.is_none() {
                root.gitignore = Some(self.config.gitignore);
            }
            if root.hgignore.is_none() {
                root.hgignore = Some(self.config.hgignore);
            }
            if root.dockerignore.is_none() {
                root.dockerignore = Some(self.config.dockerignore);
            }
            let paths = if root.regexp { self.expand_regexp_root(&root.path) } else { vec![PathBuf::from(&root.path)] };
            for p in paths {
                if self.stop {
                    break;
                }
                CURRENT_ALIAS.with(|a| *a.borrow_mut() = root.alias.clone());
                self.search_root(&p, &root, limit);
            }
        }
        self.finish(limit);
        let _ = self.out.flush();
        !self.has_errors
    }

    fn expand_regexp_root(&mut self, path: &str) -> Vec<PathBuf> {
        let abs = path.starts_with('/');
        let components: Vec<&str> = path.split('/').filter(|c| !c.is_empty()).collect();
        let mut current: Vec<PathBuf> = vec![if abs { PathBuf::from("/") } else { PathBuf::new() }];
        for comp in components {
            let is_regex = comp.contains('*') || comp.contains('?') || comp.contains('[');
            if !is_regex {
                for c in current.iter_mut() {
                    c.push(comp);
                }
                continue;
            }
            let re = match Regex::new(&format!("^{}$", comp)) {
                Ok(r) => r,
                Err(_) => {
                    self.error("result", &format!("invalid regex in root path: {}", comp));
                    return vec![];
                }
            };
            let mut next = vec![];
            for c in &current {
                let dir = if c.as_os_str().is_empty() { PathBuf::from(".") } else { c.clone() };
                if let Ok(rd) = std::fs::read_dir(&dir) {
                    let mut entries: Vec<_> = rd.flatten().collect();
                    entries.sort_by_key(|e| e.file_name());
                    for e in entries {
                        let name = e.file_name().to_string_lossy().to_string();
                        if re.is_match(&name) && e.path().is_dir() {
                            let mut p = c.clone();
                            p.push(&name);
                            next.push(p);
                        }
                    }
                }
            }
            current = next;
        }
        current
    }

    fn search_root(&mut self, root_path: &Path, root: &Root, limit: usize) {
        let display = root_path.to_string_lossy().to_string();
        if let Err(e) = std::fs::canonicalize(root_path) {
            self.error(&display, &format!("could not canonicalize path: {}", e));
            return;
        }
        if root.dockerignore == Some(true) {
            self.load_dockerignore(root_path);
        }
        match root.traversal {
            Traversal::Bfs => {
                let mut queue: VecDeque<(PathBuf, String, u32)> = VecDeque::new();
                queue.push_back((root_path.to_path_buf(), String::new(), 0));
                while let Some((dir, rel, depth)) = queue.pop_front() {
                    if self.stop {
                        return;
                    }
                    let mut subdirs = vec![];
                    self.visit_dir(&dir, &rel, depth, root, limit, &mut subdirs);
                    for s in subdirs {
                        queue.push_back(s);
                    }
                }
            }
            Traversal::Dfs => {
                self.visit_dir_dfs(root_path, "", 0, root, limit);
            }
        }
    }

    fn visit_dir_dfs(&mut self, dir: &Path, rel: &str, depth: u32, root: &Root, limit: usize) {
        if self.stop {
            return;
        }
        let rd = match std::fs::read_dir(dir) {
            Ok(rd) => rd,
            Err(e) => {
                self.error(&dir.to_string_lossy(), &e.to_string());
                return;
            }
        };
        for entry in rd {
            if self.stop {
                return;
            }
            let entry = match entry {
                Ok(e) => e,
                Err(_) => continue,
            };
            let (subdir, child_rel) = self.visit_entry(&entry, rel, depth + 1, root, limit);
            if let Some(sub) = subdir {
                if root.max_depth == 0 || depth + 1 < root.max_depth {
                    self.visit_dir_dfs(&sub, &child_rel, depth + 1, root, limit);
                }
            }
        }
    }

    fn visit_dir(&mut self, dir: &Path, rel: &str, depth: u32, root: &Root, limit: usize, subdirs: &mut Vec<(PathBuf, String, u32)>) {
        let rd = match std::fs::read_dir(dir) {
            Ok(rd) => rd,
            Err(e) => {
                self.error(&dir.to_string_lossy(), &e.to_string());
                return;
            }
        };
        for entry in rd {
            if self.stop {
                return;
            }
            let entry = match entry {
                Ok(e) => e,
                Err(_) => continue,
            };
            let (subdir, child_rel) = self.visit_entry(&entry, rel, depth + 1, root, limit);
            if let Some(sub) = subdir {
                if root.max_depth == 0 || depth + 1 < root.max_depth {
                    subdirs.push((sub, child_rel, depth + 1));
                }
            }
        }
    }

    /// returns the path if the entry is a directory to descend into
    fn visit_entry(&mut self, entry: &std::fs::DirEntry, rel: &str, depth: u32, root: &Root, limit: usize) -> (Option<PathBuf>, String) {
        let name = entry.file_name().to_string_lossy().to_string();
        let child_rel = if rel.is_empty() { name.clone() } else { format!("{}/{}", rel, name) };
        let full = entry.path();
        let file_type = entry.file_type().ok();
        let is_dir = file_type.map(|t| t.is_dir()).unwrap_or(false);
        if root.dockerignore == Some(true) && self.is_docker_ignored(&child_rel, &name) {
            return (None, child_rel);
        }
        if depth >= root.min_depth {
            let info = FileInfo::new(full.clone(), child_rel.clone(), depth, file_type, root.symlinks);
            self.process_file(&info, limit);
            if root.archives && !self.stop && self.is_zip(&name) {
                if let Some(entries) = crate::zip::list(&full) {
                    let archive_display = format!("[{}]", full.to_string_lossy());
                    for e in entries {
                        if self.stop {
                            break;
                        }
                        let mut einfo = FileInfo::from_archive(full.clone(), e);
                        einfo.depth = depth;
                        self.process_archive_entry(&einfo, &archive_display, limit);
                    }
                }
            }
        }
        if is_dir {
            (Some(full), child_rel)
        } else {
            (None, child_rel)
        }
    }

    fn is_zip(&self, name: &str) -> bool {
        let lower = name.to_lowercase();
        self.config.is_zip_archive.iter().any(|e| lower.ends_with(&e.to_lowercase()))
    }

    fn ctx(&self) -> Ctx<'_> {
        let mut ctx = Ctx::new(self.config);
        ctx.outer = self.outer.clone();
        ctx.subquery_runner = Some(&run_subquery);
        ctx
    }

    fn process_archive_entry(&mut self, info: &FileInfo, archive_display: &str, limit: usize) {
        self.process_file_inner(info, Some(archive_display.to_string()), limit);
    }

    fn process_file(&mut self, info: &FileInfo, limit: usize) {
        self.process_file_inner(info, None, limit);
    }

    fn process_file_inner(&mut self, info: &FileInfo, archive: Option<String>, limit: usize) {
        let ctx = self.ctx();
        if let Some(expr) = &self.query.expr {
            match eval_bool(expr, info, &ctx) {
                Ok(true) => {}
                Ok(false) => return,
                Err(e) => {
                    let subject = if e.starts_with("Incorrect regex") { "expression".to_string() } else { info.display_path() };
                    drop(ctx);
                    self.error(&subject, &e);
                    return;
                }
            }
        }
        if self.aggregate_mode {
            let mut group = vec![];
            for g in &self.query.grouping {
                match eval(g, info, &ctx) {
                    Ok(v) => group.push(v.to_string()),
                    Err(_) => group.push(String::new()),
                }
            }
            let mut values = HashMap::new();
            let mut plain = vec![];
            for col in &self.query.fields {
                collect_agg_values(&col.expr, info, &ctx, &mut values);
                if !col.expr.has_aggregate() {
                    match eval(&col.expr, info, &ctx) {
                        Ok(v) => plain.push(v.to_string()),
                        Err(_) => plain.push(String::new()),
                    }
                } else {
                    plain.push(String::new());
                }
            }
            drop(ctx);
            self.agg_files.push(AggRow { group, values, plain, archive });
            return;
        }
        // compute columns
        let mut values = vec![];
        let mut cache: HashMap<String, Variant> = HashMap::new();
        let mut colored_name = None;
        for (i, col) in self.query.fields.iter().enumerate() {
            let key = col.expr.to_key();
            let v = if let Some(v) = cache.get(&key) {
                v.clone()
            } else {
                match eval(&col.expr, info, &ctx) {
                    Ok(v) => {
                        cache.insert(key, v.clone());
                        v
                    }
                    Err(e) => {
                        drop(ctx);
                        self.error(&info.display_path(), &e);
                        return;
                    }
                }
            };
            let s = v.to_string();
            if let Expr::Field(Field::Name, _) = &col.expr {
                if let Some(lc) = &self.lscolors {
                    if colored_name.is_none() && info.archive.is_none() {
                        if let Some(style) = lc.style_for(&info.full_path, &info.name, info.metadata.as_ref()) {
                            colored_name = Some((i, style.paint(&s)));
                        }
                    }
                }
            }
            values.push(s);
        }
        let mut sort_keys = vec![];
        for o in &self.query.ordering {
            match eval(&o.expr, info, &ctx) {
                Ok(v) => sort_keys.push(v),
                Err(_) => sort_keys.push(Variant::empty()),
            }
        }
        drop(ctx);
        let row = Row { values, archive, sort_keys, colored_name };
        if self.buffered {
            self.rows.push(row);
        } else {
            if self.skipped < self.query.offset {
                self.skipped += 1;
                return;
            }
            self.emit_row(&row);
            self.found += 1;
            if limit > 0 && self.found >= limit {
                self.stop = true;
            }
        }
    }

    fn finish(&mut self, limit: usize) {
        if self.aggregate_mode {
            self.finish_aggregates();
        } else if self.buffered {
            let ordering = &self.query.ordering;
            let mut rows = std::mem::take(&mut self.rows);
            rows.sort_by(|a, b| {
                for (i, o) in ordering.iter().enumerate() {
                    let ord = compare_variants(&a.sort_keys[i], &b.sort_keys[i]);
                    let ord = if o.asc { ord } else { ord.reverse() };
                    if ord != std::cmp::Ordering::Equal {
                        return ord;
                    }
                }
                std::cmp::Ordering::Equal
            });
            let mut count = 0;
            for row in rows.iter().skip(self.query.offset) {
                if limit > 0 && count >= limit {
                    break;
                }
                self.emit_row(row);
                count += 1;
            }
        }
        self.write_footer();
    }

    fn finish_aggregates(&mut self) {
        let files = std::mem::take(&mut self.agg_files);
        // group
        let mut groups: Vec<(Vec<String>, Vec<usize>)> = vec![];
        for (i, f) in files.iter().enumerate() {
            match groups.iter_mut().find(|(g, _)| *g == f.group) {
                Some((_, idx)) => idx.push(i),
                None => groups.push((f.group.clone(), vec![i])),
            }
        }
        let mut rows = vec![];
        for (group_key, idxs) in groups {
            let mut aggs: HashMap<String, Variant> = HashMap::new();
            let mut agg_keys: Vec<(String, Function)> = vec![];
            for col in &self.query.fields {
                collect_agg_keys(&col.expr, &mut agg_keys);
            }
            for (key, func) in agg_keys {
                let mut nums: Vec<f64> = vec![];
                let mut count = 0usize;
                for &i in &idxs {
                    if let Some(v) = files[i].values.get(&key) {
                        count += 1;
                        if let Some(n) = v.to_num_opt() {
                            nums.push(n);
                        }
                    }
                }
                let result = aggregate(func, &nums, count);
                aggs.insert(key.to_lowercase(), result);
            }
            let empty_file = FileInfo::empty();
            let mut ctx = Ctx::new(self.config);
            ctx.aggregates = Some(&aggs);
            let mut values = vec![];
            for (ci, col) in self.query.fields.iter().enumerate() {
                let is_group_col = self.query.grouping.iter().any(|g| g.to_key() == col.expr.to_key());
                if col.expr.has_aggregate() {
                    match eval(&col.expr, &empty_file, &ctx) {
                        Ok(v) => values.push(v.to_string()),
                        Err(_) => values.push(String::new()),
                    }
                } else if is_group_col {
                    let gi = self.query.grouping.iter().position(|g| g.to_key() == col.expr.to_key()).unwrap();
                    values.push(group_key[gi].clone());
                } else if self.query.grouping.is_empty() && !col.expr.has_field() {
                    match eval(&col.expr, &empty_file, &ctx) {
                        Ok(v) => values.push(v.to_string()),
                        Err(_) => values.push(String::new()),
                    }
                } else if self.query.grouping.is_empty() {
                    match eval(&col.expr, &empty_file, &ctx) {
                        Ok(v) => values.push(v.to_string()),
                        Err(_) => values.push(String::new()),
                    }
                } else {
                    let _ = ci;
                    values.push(String::new());
                }
            }
            let mut sort_keys = vec![];
            for o in &self.query.ordering {
                // order by a column of the result
                let pos = self.query.fields.iter().position(|c| c.expr.to_key() == o.expr.to_key());
                match pos {
                    Some(p) => sort_keys.push(Variant::Str(values[p].clone())),
                    None => match eval(&o.expr, &empty_file, &ctx) {
                        Ok(v) => sort_keys.push(v),
                        Err(_) => sort_keys.push(Variant::empty()),
                    },
                }
            }
            rows.push(Row { values, archive: None, sort_keys, colored_name: None });
        }
        let ordering = &self.query.ordering;
        rows.sort_by(|a, b| {
            for (i, o) in ordering.iter().enumerate() {
                let ord = compare_variants(&a.sort_keys[i], &b.sort_keys[i]);
                let ord = if o.asc { ord } else { ord.reverse() };
                if ord != std::cmp::Ordering::Equal {
                    return ord;
                }
            }
            std::cmp::Ordering::Equal
        });
        let limit = self.query.limit;
        let mut count = 0;
        for row in rows.iter().skip(self.query.offset) {
            if limit > 0 && count >= limit {
                break;
            }
            self.emit_row(row);
            count += 1;
        }
    }

    // ------------------------------------------------------------ output

    fn write_header(&mut self) {
        if self.output_rows.is_some() {
            return;
        }
        match self.query.output_format {
            OutputFormat::Json => {
                let _ = write!(self.out, "[");
            }
            OutputFormat::Html => {
                let title = html_escape(&self.query.raw);
                let _ = write!(
                    self.out,
                    "<html><head><title>{}</title></head><body><table><tr><th colspan=\"{}\">{}</th></tr>",
                    title,
                    self.query.fields.len(),
                    title
                );
            }
            _ => {}
        }
    }

    fn write_footer(&mut self) {
        if self.output_rows.is_some() {
            return;
        }
        match self.query.output_format {
            OutputFormat::Json => {
                let _ = write!(self.out, "]");
            }
            OutputFormat::Html => {
                let _ = write!(self.out, "</table></body></html>");
            }
            _ => {}
        }
    }

    fn emit_row(&mut self, row: &Row) {
        if let Some(collector) = self.output_rows {
            collector.borrow_mut().push(row.values.clone());
            return;
        }
        let mut values: Vec<String> = vec![];
        if let Some(a) = &row.archive {
            values.push(a.clone());
        }
        values.extend(row.values.iter().cloned());
        let result = match self.query.output_format {
            OutputFormat::Tabs => {
                let mut display = values.clone();
                if let Some((i, colored)) = &row.colored_name {
                    let idx = i + if row.archive.is_some() { 1 } else { 0 };
                    display[idx] = colored.clone();
                }
                writeln!(self.out, "{}", display.join("\t"))
            }
            OutputFormat::Lines => {
                let mut display = values.clone();
                if let Some((i, colored)) = &row.colored_name {
                    let idx = i + if row.archive.is_some() { 1 } else { 0 };
                    display[idx] = colored.clone();
                }
                let mut r = Ok(());
                for v in display {
                    r = writeln!(self.out, "{}", v);
                }
                r
            }
            OutputFormat::List => {
                let mut r = Ok(());
                for v in &values {
                    r = write!(self.out, "{}\0", v);
                }
                r
            }
            OutputFormat::Csv => {
                let line: Vec<String> = values.iter().map(|v| csv_escape(v)).collect();
                writeln!(self.out, "{}", line.join(","))
            }
            OutputFormat::Json => {
                let mut map = serde_json::Map::new();
                let mut keys: Vec<(String, String)> = vec![];
                for (i, col) in self.query.fields.iter().enumerate() {
                    let key = match &col.alias {
                        Some(a) => a.clone(),
                        None => {
                            let k = col.expr.to_key();
                            if self.aggregate_mode { k.to_lowercase() } else { k }
                        }
                    };
                    keys.push((key, row.values[i].clone()));
                }
                if let Some(a) = &row.archive {
                    keys.push(("archive".to_string(), a.clone()));
                }
                keys.sort_by(|a, b| a.0.cmp(&b.0));
                for (k, v) in keys {
                    map.insert(k, serde_json::Value::String(v));
                }
                let s = serde_json::to_string(&serde_json::Value::Object(map)).unwrap_or_default();
                let r = if self.first_row { write!(self.out, "{}", s) } else { write!(self.out, ",{}", s) };
                self.first_row = false;
                r
            }
            OutputFormat::Html => {
                let cells: Vec<String> = values.iter().map(|v| format!("<td>{}</td>", html_escape(v))).collect();
                write!(self.out, "<tr>{}</tr>", cells.join(""))
            }
        };
        if let Err(e) = result {
            if e.kind() == std::io::ErrorKind::BrokenPipe {
                self.error("output", "broken pipe");
                std::process::exit(1);
            }
        }
    }

    // ------------------------------------------------------------ dockerignore

    fn load_dockerignore(&mut self, root: &Path) {
        let file = root.join(".dockerignore");
        let content = match std::fs::read_to_string(&file) {
            Ok(c) => c,
            Err(_) => return,
        };
        let mut patterns = vec![];
        for line in content.lines() {
            let line = line.trim_end_matches('\r');
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let (neg, pat) = match line.strip_prefix('!') {
                Some(p) => (true, p),
                None => (false, line),
            };
            let pat = pat.strip_prefix('/').unwrap_or(pat);
            let pat = pat.strip_prefix("./").unwrap_or(pat);
            let mut re = String::from("^");
            for c in pat.chars() {
                match c {
                    '*' => re.push_str(".*"),
                    '?' => re.push('.'),
                    '.' | '+' | '(' | ')' | '|' | '^' | '$' | '\\' => {
                        re.push('\\');
                        re.push(c);
                    }
                    c => re.push(c),
                }
            }
            match Regex::new(&re) {
                Ok(r) => patterns.push((r, neg)),
                Err(_) => {
                    self.error(
                        &root.to_string_lossy(),
                        &format!("Error creating regex while parsing .dockerignore glob: {}", pat),
                    );
                }
            }
            if pat.is_empty() {
                self.error(
                    &root.to_string_lossy(),
                    &format!("Error creating regex while parsing .dockerignore glob: {}", line),
                );
                patterns.pop();
            }
        }
        self.docker_ignores.push((root.to_path_buf(), patterns));
    }

    fn is_docker_ignored(&self, rel: &str, name: &str) -> bool {
        let mut ignored = false;
        for (_, patterns) in &self.docker_ignores {
            for (re, neg) in patterns {
                if re.is_match(rel) || re.is_match(name) {
                    ignored = !neg;
                }
            }
        }
        ignored
    }
}

fn run_subquery(q: &Query, outer: &[(String, &FileInfo)]) -> Vec<Vec<String>> {
    let config = Config::default();
    let opts = Options { show_errors: false, use_colors_stdout: false, use_colors_stderr: false };
    let rows = std::cell::RefCell::new(vec![]);
    {
        let mut s = Searcher::new(q, &config, &opts).with_outer(outer.to_vec(), &rows);
        s.run();
    }
    rows.into_inner()
}

fn collect_agg_keys(expr: &Expr, out: &mut Vec<(String, Function)>) {
    match expr {
        Expr::Function(f, args) => {
            if f.is_aggregate() {
                out.push((expr.to_key(), *f));
            } else {
                for a in args {
                    collect_agg_keys(a, out);
                }
            }
        }
        Expr::Arith(l, _, r) => {
            collect_agg_keys(l, out);
            collect_agg_keys(r, out);
        }
        _ => {}
    }
}

fn collect_agg_values(expr: &Expr, info: &FileInfo, ctx: &Ctx, out: &mut HashMap<String, Variant>) {
    match expr {
        Expr::Function(f, args) => {
            if f.is_aggregate() {
                let v = match args.first() {
                    Some(Expr::Literal(s)) if s == "*" => Variant::Int(1),
                    Some(a) => eval(a, info, ctx).unwrap_or_else(|_| Variant::empty()),
                    None => Variant::Int(1),
                };
                out.insert(expr.to_key(), v);
            } else {
                for a in args {
                    collect_agg_values(a, info, ctx, out);
                }
            }
        }
        Expr::Arith(l, _, r) => {
            collect_agg_values(l, info, ctx, out);
            collect_agg_values(r, info, ctx, out);
        }
        _ => {}
    }
}

fn aggregate(func: Function, nums: &[f64], count: usize) -> Variant {
    match func {
        Function::Count => Variant::Int(count as i64),
        Function::Min => nums.iter().cloned().fold(None, |acc: Option<f64>, v| Some(acc.map_or(v, |a| a.min(v)))).map(Variant::Float).unwrap_or_else(Variant::empty),
        Function::Max => nums.iter().cloned().fold(None, |acc: Option<f64>, v| Some(acc.map_or(v, |a| a.max(v)))).map(Variant::Float).unwrap_or_else(Variant::empty),
        Function::Sum => {
            if nums.is_empty() { Variant::empty() } else { Variant::Float(nums.iter().sum()) }
        }
        Function::Avg => {
            if nums.is_empty() { Variant::empty() } else { Variant::Float(nums.iter().sum::<f64>() / nums.len() as f64) }
        }
        Function::VarPop | Function::StdDevPop => {
            if nums.is_empty() {
                return Variant::empty();
            }
            let n = nums.len() as f64;
            let mean = nums.iter().sum::<f64>() / n;
            let var = nums.iter().map(|v| (v - mean) * (v - mean)).sum::<f64>() / n;
            if func == Function::VarPop { Variant::Float(var) } else { Variant::Float(var.sqrt()) }
        }
        Function::VarSamp | Function::StdDevSamp => {
            if nums.len() < 2 {
                return Variant::empty();
            }
            let n = nums.len() as f64;
            let mean = nums.iter().sum::<f64>() / n;
            let var = nums.iter().map(|v| (v - mean) * (v - mean)).sum::<f64>() / (n - 1.0);
            if func == Function::VarSamp { Variant::Float(var) } else { Variant::Float(var.sqrt()) }
        }
        _ => Variant::empty(),
    }
}

pub fn compare_variants(a: &Variant, b: &Variant) -> std::cmp::Ordering {
    let num = |v: &Variant| -> Option<f64> {
        match v {
            Variant::Str(s) => {
                if s.is_empty() {
                    None
                } else {
                    s.trim().parse::<f64>().ok()
                }
            }
            Variant::Int(i) => Some(*i as f64),
            Variant::Float(f) => Some(*f),
            Variant::Bool(_) | Variant::DateTime(_) => None,
        }
    };
    match (num(a), num(b)) {
        (Some(x), Some(y)) => x.partial_cmp(&y).unwrap_or(std::cmp::Ordering::Equal),
        _ => a.to_string().cmp(&b.to_string()),
    }
}

#[allow(dead_code)]
pub fn kind_of(e: &Expr) -> FieldKind {
    e.kind()
}
