    for o in query.ordering.iter_mut() {
        resolve_expr(&mut o.expr, &aliases)?;
    }
    Ok(())
}

fn resolve_expr(expr: &mut Expr, aliases: &[String]) -> PResult<()> {
    match expr {
        Expr::Literal(s) => {
            if let Some(pos) = s.find('.') {
                let prefix = s[..pos].to_string();
                let rest = s[pos + 1..].to_string();
                if aliases.iter().any(|a| *a == prefix) {
                    *expr = match Field::from_str(&rest) {
                        Some(f) => Expr::Field(f, Some(prefix)),
                        None => Expr::Literal(rest),
                    };
                } else {
                    return Err(format!("Invalid root alias: {}", prefix));
                }
            }
            Ok(())
        }
        Expr::Field(..) => Ok(()),
        Expr::Function(_, args) => {
            for a in args.iter_mut() {
                resolve_expr(a, aliases)?;
            }
            Ok(())
        }
        Expr::Arith(l, _, r) | Expr::Compare(l, _, r) | Expr::And(l, r) | Expr::Or(l, r) => {
            resolve_expr(l, aliases)?;
            resolve_expr(r, aliases)
        }
        Expr::Between(l, a, b, _) => {
            resolve_expr(l, aliases)?;
            resolve_expr(a, aliases)?;
            resolve_expr(b, aliases)
        }
        Expr::InList(l, list, _) => {
            resolve_expr(l, aliases)?;
            for a in list.iter_mut() {
                resolve_expr(a, aliases)?;
            }
            Ok(())
        }
        Expr::InSubquery(l, q, _) => {
            resolve_expr(l, aliases)?;
            resolve_aliases(q, aliases)
        }
        Expr::Exists(q, _) => resolve_aliases(q, aliases),
        Expr::Not(e) => resolve_expr(e, aliases),
    }
}
