fn query_uses_outer_alias(q: &Query) -> bool {
    let own: Vec<String> = q.roots.iter().filter_map(|r| r.alias.clone()).collect();
    fn expr_uses(e: &Expr, own: &[String]) -> bool {
        match e {
            Expr::Field(_, Some(a)) => !own.contains(a),
            Expr::Field(_, None) | Expr::Literal(_) => false,
            Expr::Function(_, args) => args.iter().any(|a| expr_uses(a, own)),
            Expr::Arith(l, _, r) | Expr::Compare(l, _, r) | Expr::And(l, r) | Expr::Or(l, r) => {
                expr_uses(l, own) || expr_uses(r, own)
            }
            Expr::Between(l, a, b, _) => expr_uses(l, own) || expr_uses(a, own) || expr_uses(b, own),
            Expr::InList(l, list, _) => expr_uses(l, own) || list.iter().any(|a| expr_uses(a, own)),
            Expr::InSubquery(l, q, _) => expr_uses(l, own) || query_uses_outer_alias(q),
            Expr::Exists(q, _) => query_uses_outer_alias(q),
            Expr::Not(e) => expr_uses(e, own),
        }
    }
    q.fields.iter().any(|c| expr_uses(&c.expr, &own))
        || q.expr.as_ref().map(|e| expr_uses(e, &own)).unwrap_or(false)
        || q.grouping.iter().any(|e| expr_uses(e, &own))
        || q.ordering.iter().any(|o| expr_uses(&o.expr, &own))
}

fn run_subquery(q: &Query, file: &FileInfo, ctx: &Ctx) -> Vec<Vec<String>> {
    match ctx.subquery_runner {
