            let mut outer: Vec<(String, &FileInfo)> = ctx.outer.clone();
            if let Some(alias) = &ctx_alias(ctx) {
                outer.push((alias.clone(), file));
            }
            let rows = runner(q, &outer, ctx.config, ctx.show_errors);
            if !correlated {
                SUBQUERY_CACHE.with(|c| c.borrow_mut().insert(key, rows.clone()));
            }
            rows
        }
        None => vec![],
    }
}""")
