                (144 * br / sample_rate as usize + padding, 1152)
            } else {
                (72 * br / sample_rate as usize + padding, 576)
            }
        }
    };
    if size < 4 {
        return None;
    }
    Some(Frame { size, bitrate, sample_rate, samples })
