    let mut info = Mp3Info::default();
    let mut i = 0usize;
    let len = data.len();
    let mut frames = 0u32;
    let mut duration = 0f64;
    while i < len {
        let rem = len - i;
        if rem >= 128 && &data[i..i + 3] == b"TAG" {
            let t = &data[i..i + 128];
            info.title = tag_text(&t[3..33]);
            info.artist = tag_text(&t[33..63]);
            info.album = tag_text(&t[63..93]);
            info.year = tag_text(&t[93..97]).parse::<u32>().unwrap_or(0);
            info.genre = Some(t[127]);
            i += 128;
            continue;
        }
        if rem >= 10 && &data[i..i + 3] == b"ID3" {
            let size = ((data[i + 6] as usize & 0x7f) << 21)
                | ((data[i + 7] as usize & 0x7f) << 14)
                | ((data[i + 8] as usize & 0x7f) << 7)
                | (data[i + 9] as usize & 0x7f);
            let footer = if data[i + 5] & 0x10 != 0 { 10 } else { 0 };
            i += 10 + size + footer;
            continue;
        }
        if rem < 4 {
            return None;
        }
        match parse_header(&data[i..]) {
            Some(f) => {
                if i + f.size > len {
                    break;
                }
                if i + f.size + 4 > len {
                    return None;
                }
                if frames == 0 {
                    info.bitrate = f.bitrate;
                    info.frequency = f.sample_rate;
                }
                frames += 1;
                duration += f.samples as f64 / f.sample_rate as f64;
                i += f.size;
            }
            None => i += 1,
        }
    }
    if frames == 0 {
        return None;
    }
    info.duration_secs = duration as u64;
    Some(info)
}
