        match parse_header(&data[i..]) {
            Some(f) => {
                if i + f.size > len {
                    break;
                }
                if i + f.size + 4 > len {
                    return None;
                }
                if frames == 0 {
                    info.bitrate = f.bitrate;
                    info.frequency = f.sample_rate;
                }
                frames += 1;
                duration += f.samples as f64 / f.sample_rate as f64;
                i += f.size;
            }
            None => i += 1,
        }
    }
    if frames == 0 {
        return None;
    }
    info.duration_secs = duration as u64;
    Some(info)
}
