//! Minimal EXIF reader (JPEG APP1, TIFF, PNG eXIf) with display formatting close to kamadak-exif.

use std::collections::HashMap;

#[derive(Debug, Clone)]
pub enum Value {
    Byte(Vec<u8>),
    Ascii(Vec<Vec<u8>>),
    Short(Vec<u16>),
    Long(Vec<u32>),
    Rational(Vec<(u32, u32)>),
    SByte(Vec<i8>),
    Undefined(Vec<u8>),
    SShort(Vec<i16>),
    SLong(Vec<i32>),
    SRational(Vec<(i32, i32)>),
    Float(Vec<f32>),
    Double(Vec<f64>),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Ifd {
    Primary,
    Exif,
    Gps,
}

pub struct Exif {
    pub fields: HashMap<(Ifd, u16), Value>,
}

struct Reader<'a> {
    data: &'a [u8],
    le: bool,
}

impl<'a> Reader<'a> {
    fn u16(&self, o: usize) -> Option<u16> {
        let b = self.data.get(o..o + 2)?;
        Some(if self.le { u16::from_le_bytes([b[0], b[1]]) } else { u16::from_be_bytes([b[0], b[1]]) })
    }
    fn u32(&self, o: usize) -> Option<u32> {
        let b = self.data.get(o..o + 4)?;
        Some(if self.le {
            u32::from_le_bytes([b[0], b[1], b[2], b[3]])
        } else {
            u32::from_be_bytes([b[0], b[1], b[2], b[3]])
        })
    }
    fn f32(&self, o: usize) -> Option<f32> {
        Some(f32::from_bits(self.u32(o)?))
    }
    fn f64(&self, o: usize) -> Option<f64> {
        let b = self.data.get(o..o + 8)?;
        let arr: [u8; 8] = b.try_into().ok()?;
        Some(if self.le { f64::from_le_bytes(arr) } else { f64::from_be_bytes(arr) })
    }

    fn read_ifd(&self, offset: usize, ifd: Ifd, out: &mut HashMap<(Ifd, u16), Value>, depth: u32) {
        if depth > 2 {
            return;
        }
        let count = match self.u16(offset) {
            Some(c) => c as usize,
            None => return,
        };
        for i in 0..count {
            let e = offset + 2 + i * 12;
            let (tag, typ, cnt) = match (self.u16(e), self.u16(e + 2), self.u32(e + 4)) {
                (Some(t), Some(ty), Some(c)) => (t, ty, c as usize),
                _ => return,
            };
            let unit = match typ {
                1 | 2 | 6 | 7 => 1,
                3 | 8 => 2,
                4 | 9 | 11 => 4,
                5 | 10 | 12 => 8,
                _ => continue,
            };
            let total = unit * cnt;
            let data_off = if total <= 4 { e + 8 } else { self.u32(e + 8).map(|v| v as usize).unwrap_or(usize::MAX) };
            if data_off.checked_add(total).map(|end| end > self.data.len()).unwrap_or(true) {
                continue;
            }
            if ifd == Ifd::Primary && (tag == 0x8769 || tag == 0x8825) {
                if let Some(off) = self.u32(e + 8) {
                    let sub = if tag == 0x8769 { Ifd::Exif } else { Ifd::Gps };
                    self.read_ifd(off as usize, sub, out, depth + 1);
                }
                continue;
            }
            let value = match typ {
                1 => Value::Byte(self.data[data_off..data_off + total].to_vec()),
                2 => {
                    let raw = &self.data[data_off..data_off + total];
                    let parts: Vec<Vec<u8>> = raw
                        .split(|&b| b == 0)
                        .map(|p| p.to_vec())
                        .collect();
                    let mut parts = parts;
                    if parts.len() > 1 && parts.last().map(|p| p.is_empty()).unwrap_or(false) {
                        parts.pop();
                    }
                    Value::Ascii(parts)
                }
                3 => Value::Short((0..cnt).filter_map(|k| self.u16(data_off + k * 2)).collect()),
                4 => Value::Long((0..cnt).filter_map(|k| self.u32(data_off + k * 4)).collect()),
                5 => Value::Rational(
                    (0..cnt)
                        .filter_map(|k| Some((self.u32(data_off + k * 8)?, self.u32(data_off + k * 8 + 4)?)))
                        .collect(),
                ),
                6 => Value::SByte(self.data[data_off..data_off + total].iter().map(|&b| b as i8).collect()),
                7 => Value::Undefined(self.data[data_off..data_off + total].to_vec()),
                8 => Value::SShort((0..cnt).filter_map(|k| self.u16(data_off + k * 2).map(|v| v as i16)).collect()),
                9 => Value::SLong((0..cnt).filter_map(|k| self.u32(data_off + k * 4).map(|v| v as i32)).collect()),
                10 => Value::SRational(
                    (0..cnt)
                        .filter_map(|k| {
                            Some((self.u32(data_off + k * 8)? as i32, self.u32(data_off + k * 8 + 4)? as i32))
                        })
                        .collect(),
                ),
                11 => Value::Float((0..cnt).filter_map(|k| self.f32(data_off + k * 4)).collect()),
                12 => Value::Double((0..cnt).filter_map(|k| self.f64(data_off + k * 8)).collect()),
                _ => continue,
            };
            out.entry((ifd, tag)).or_insert(value);
        }
    }
}

fn parse_tiff(data: &[u8]) -> Option<Exif> {
    if data.len() < 8 {
        return None;
    }
    let le = match &data[0..2] {
        b"II" => true,
        b"MM" => false,
        _ => return None,
    };
    let r = Reader { data, le };
    if r.u16(2)? != 42 {
        return None;
    }
    let ifd0 = r.u32(4)? as usize;
    let mut fields = HashMap::new();
    r.read_ifd(ifd0, Ifd::Primary, &mut fields, 0);
    Some(Exif { fields })
}

pub fn parse(data: &[u8]) -> Option<Exif> {
    if data.starts_with(b"\xff\xd8") {
        // JPEG: look for APP1 Exif segment
        let mut i = 2;
        while i + 4 <= data.len() {
            if data[i] != 0xff {
                return None;
            }
            let marker = data[i + 1];
            if marker == 0xd8 || marker == 0x01 || (0xd0..=0xd7).contains(&marker) {
                i += 2;
                continue;
            }
            if marker == 0xda || marker == 0xd9 {
                return None;
            }
            let len = u16::from_be_bytes([data[i + 2], data[i + 3]]) as usize;
            if marker == 0xe1 && len >= 8 && data.len() >= i + 2 + len {
                let seg = &data[i + 4..i + 2 + len];
                if seg.starts_with(b"Exif\0\0") {
                    return parse_tiff(&seg[6..]);
                }
            }
            i += 2 + len;
        }
        return None;
    }
    if data.starts_with(b"II*\x00") || data.starts_with(b"MM\x00*") {
        return parse_tiff(data);
    }
    if data.starts_with(b"\x89PNG\r\n\x1a\n") {
        let mut i = 8;
        while i + 8 <= data.len() {
            let len = u32::from_be_bytes([data[i], data[i + 1], data[i + 2], data[i + 3]]) as usize;
            let typ = &data[i + 4..i + 8];
            if typ == b"eXIf" && i + 8 + len <= data.len() {
                return parse_tiff(&data[i + 8..i + 8 + len]);
            }
            if typ == b"IEND" {
                break;
            }
            i += 12 + len;
        }
        return None;
    }
    None
}

fn fmt_f64(v: f64) -> String {
    crate::util::format_f64(v)
}

fn ascii_string(v: &Value) -> Option<String> {
    match v {
        Value::Ascii(parts) => {
            let strs: Vec<String> = parts.iter().map(|p| String::from_utf8_lossy(p).to_string()).collect();
            Some(strs.join(", "))
        }
        _ => None,
    }
}

fn first_number(v: &Value) -> Option<f64> {
    match v {
        Value::Byte(x) => x.first().map(|&n| n as f64),
        Value::Short(x) => x.first().map(|&n| n as f64),
        Value::Long(x) => x.first().map(|&n| n as f64),
        Value::SByte(x) => x.first().map(|&n| n as f64),
        Value::SShort(x) => x.first().map(|&n| n as f64),
        Value::SLong(x) => x.first().map(|&n| n as f64),
        Value::Rational(x) => x.first().map(|&(n, d)| if d == 0 { 0.0 } else { n as f64 / d as f64 }),
        Value::SRational(x) => x.first().map(|&(n, d)| if d == 0 { 0.0 } else { n as f64 / d as f64 }),
        Value::Float(x) => x.first().map(|&n| n as f64),
        Value::Double(x) => x.first().copied(),
        _ => None,
    }
}

fn rational_f32(v: &Value, idx: usize) -> Option<f32> {
    match v {
        Value::Rational(x) => x.get(idx).map(|&(n, d)| if d == 0 { 0.0 } else { n as f32 / d as f32 }),
        Value::SRational(x) => x.get(idx).map(|&(n, d)| if d == 0 { 0.0 } else { n as f32 / d as f32 }),
        _ => None,
    }
}

/// Generic value display (numbers separated by ", ", undefined as hex).
fn display_default(v: &Value) -> String {
    fn join<T: std::fmt::Display>(items: &[T]) -> String {
        items.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(", ")
    }
    match v {
        Value::Byte(x) => join(x),
        Value::Ascii(_) => ascii_string(v).unwrap_or_default(),
        Value::Short(x) => join(x),
        Value::Long(x) => join(x),
        Value::Rational(x) => x.iter().map(|(n, d)| format!("{}/{}", n, d)).collect::<Vec<_>>().join(", "),
        Value::SByte(x) => join(x),
        Value::Undefined(x) => format!("0x{}", x.iter().map(|b| format!("{:02x}", b)).collect::<String>()),
        Value::SShort(x) => join(x),
        Value::SLong(x) => join(x),
        Value::SRational(x) => x.iter().map(|(n, d)| format!("{}/{}", n, d)).collect::<Vec<_>>().join(", "),
        Value::Float(x) => join(x),
        Value::Double(x) => join(x),
    }
}

fn display_decimal(v: &Value) -> String {
    match v {
        Value::Rational(x) => x
            .iter()
            .map(|&(n, d)| fmt_f64(if d == 0 { 0.0 } else { n as f64 / d as f64 }))
            .collect::<Vec<_>>()
            .join(", "),
        Value::SRational(x) => x
            .iter()
            .map(|&(n, d)| fmt_f64(if d == 0 { 0.0 } else { n as f64 / d as f64 }))
            .collect::<Vec<_>>()
            .join(", "),
        _ => display_default(v),
    }
}

fn display_exptime(v: &Value) -> String {
    match v {
        Value::Rational(x) => x
            .iter()
            .map(|&(n, d)| {
                if n != 0 && n < d {
                    format!("1/{}", fmt_f64(d as f64 / n as f64))
                } else {
                    fmt_f64(if d == 0 { 0.0 } else { n as f64 / d as f64 })
                }
            })
            .collect::<Vec<_>>()
            .join(", "),
        _ => display_default(v),
    }
}

fn display_enum(v: &Value, names: &[(u32, &str)]) -> String {
    match first_number(v) {
        Some(n) => {
            let n = n as u32;
            match names.iter().find(|(k, _)| *k == n) {
                Some((_, s)) => s.to_string(),
                None => format!("unknown ({})", n),
            }
        }
        None => display_default(v),
    }
}

fn display_flash(v: &Value) -> String {
    let n = match first_number(v) {
        Some(n) => n as u32,
        None => return display_default(v),
    };
    let fired = if n & 1 == 0 { "not fired" } else { "fired" };
    let ret = match (n >> 1) & 3 {
        0 => "no return light detection function",
        1 => "reserved",
        2 => "return light not detected",
        _ => "return light detected",
    };
    let mode = match (n >> 3) & 3 {
        0 => "unknown",
        1 => "compulsory firing",
        2 => "suppressed",
        _ => "auto",
    };
    let mut s = format!("{}, {}, {}", fired, ret, mode);
    if n & 0x20 != 0 {
        s.push_str(", no flash function");
    }
    if n & 0x40 != 0 {
        s.push_str(", red-eye reduction");
    }
    s
}

fn display_version(v: &Value) -> String {
    match v {
        Value::Undefined(b) if b.len() == 4 => {
            let s = String::from_utf8_lossy(b).to_string();
            if s.chars().all(|c| c.is_ascii_digit()) {
                let major = s[..2].trim_start_matches('0');
                let major = if major.is_empty() { "0" } else { major };
                let minor = s[2..].trim_end_matches('0');
                let minor = if minor.is_empty() { "0" } else { minor };
                return format!("{}.{}", major, minor);
            }
            display_default(v)
        }
        _ => display_default(v),
    }
}

fn display_datetime(v: &Value) -> String {
    let s = ascii_string(v).unwrap_or_default();
    // "YYYY:MM:DD HH:MM:SS" -> "YYYY-MM-DD HH:MM:SS"
    if s.len() >= 19 {
        let b = s.as_bytes();
        if b[4] == b':' && b[7] == b':' {
            let mut out = s.clone();
            out.replace_range(4..5, "-");
            out.replace_range(7..8, "-");
            return out;
        }
    }
    s
}

impl Exif {
    fn get(&self, ifd: Ifd, tag: u16) -> Option<&Value> {
        self.fields.get(&(ifd, tag))
    }

    fn get_any(&self, tag: u16) -> Option<&Value> {
        self.get(Ifd::Exif, tag).or_else(|| self.get(Ifd::Primary, tag))
    }

    pub fn string(&self, tag: u16) -> Option<String> {
        self.get_any(tag).map(display_default)
    }

    pub fn datetime(&self, tag: u16) -> Option<String> {
        self.get_any(tag).map(display_datetime)
    }

    pub fn decimal(&self, tag: u16) -> Option<String> {
        self.get_any(tag).map(display_decimal)
    }

    pub fn exptime(&self) -> Option<String> {
        self.get_any(0x829a).map(display_exptime)
    }

    pub fn version(&self) -> Option<String> {
        self.get_any(0x9000).map(display_version)
    }

    pub fn flash(&self) -> Option<String> {
        self.get_any(0x9209).map(display_flash)
    }

    pub fn enumerated(&self, tag: u16, names: &[(u32, &str)]) -> Option<String> {
        self.get_any(tag).map(|v| display_enum(v, names))
    }

    pub fn digital_zoom(&self) -> Option<String> {
        self.get_any(0xa404).map(|v| match v {
            Value::Rational(x) if x.first().map(|&(n, _)| n == 0).unwrap_or(false) => "unused".to_string(),
            _ => display_decimal(v),
        })
    }

    pub fn gps_coord(&self, value_tag: u16, ref_tag: u16) -> Option<String> {
        let v = self.get(Ifd::Gps, value_tag)?;
        let d = rational_f32(v, 0)?;
        let m = rational_f32(v, 1).unwrap_or(0.0);
        let s = rational_f32(v, 2).unwrap_or(0.0);
        let mut deg = d + m / 60.0 + s / 3600.0;
        if let Some(r) = self.get(Ifd::Gps, ref_tag).and_then(ascii_string) {
            if r.starts_with('S') || r.starts_with('W') {
                deg = -deg;
            }
        }
        Some(format!("{}", deg))
    }

    pub fn gps_altitude(&self) -> Option<String> {
        let v = self.get(Ifd::Gps, 0x0006)?;
        let mut alt = rational_f32(v, 0)?;
        if let Some(Value::Byte(b)) = self.get(Ifd::Gps, 0x0005) {
            if b.first() == Some(&1) {
                alt = -alt;
            }
        }
        Some(format!("{}", alt))
    }
}

pub const ORIENTATION: &[(u32, &str)] = &[
    (1, "row 0 at top and column 0 at left"),
    (2, "row 0 at top and column 0 at right"),
    (3, "row 0 at bottom and column 0 at right"),
    (4, "row 0 at bottom and column 0 at left"),
    (5, "row 0 at left and column 0 at top"),
    (6, "row 0 at right and column 0 at top"),
    (7, "row 0 at right and column 0 at bottom"),
    (8, "row 0 at left and column 0 at bottom"),
];
pub const COLOR_SPACE: &[(u32, &str)] = &[(1, "sRGB"), (0xffff, "uncalibrated")];
pub const EXPOSURE_PROGRAM: &[(u32, &str)] = &[
    (0, "not defined"),
    (1, "manual"),
    (2, "normal program"),
    (3, "aperture priority"),
